INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017827', 'AN1761', '竈門竹雄', 'タケオは、竈門炭治郎の最初の弟だった。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b196852-zzu0xZXJrFr9.png', NULL, NULL, '大地葉', NULL, 196852, 'SUPPORTING', 50) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017828', 'AN1761', '煉獄杏寿郎', '戦闘スタイル：炎を吐く　彼は「炎の柱」としての任務に非常に熱心で、しばしば陽気なほど風変わりな一面を見せる。人当たりが良く、親切で、厳しい修行と規律から培われた並外れた炎の技と剣術を誇る。   彼は、幼い頃に母から叩き込まれた道徳観と信条を忠実に守る高潔な戦士である。その中でも最も重要なのは、「生まれながらにして強い者は、弱い者を守る義務がある」という信念である。', 20, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b129133-VlTPowwt68rJ.png', '5月10日', NULL, '日野聡', 177, 129133, 'SUPPORTING', 12035) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017829', 'AN1761', '猗窩座', '「十二魔蒙」の一員であり、上蒙三の地位にある。', 18, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b141694-0COi0GVXPuEn.png', NULL, NULL, '石田彰', 173, 141694, 'SUPPORTING', 4221) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017830', 'AN1761', '堕姫', '堕姫は、花魁の姿では「わらび姫」として知られ、「十二魔門」の一員であり、上門六の地位にある。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b139734-ZEy1ccFcwjaK.jpg', NULL, NULL, '沢城みゆき', NULL, 139734, 'SUPPORTING', 969) ON CONFLICT DO NOTHING;
