INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017838', 'AN1761', '継国緑壱', '戦闘スタイル：太陽の呼吸　継国緑壱は、『鬼滅の刃』の主要な脇役の一人である。戦国時代、鬼殺隊の伝説的な鬼殺隊員であった。', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b149220-OuBk7B3O6WD6.jpg', NULL, NULL, '井上和彦', NULL, 149220, 'SUPPORTING', 1254) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017839', 'AN1761', '竈門花子', 'ハナコは、竈門炭治郎の末の妹だった。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b196853-3MBhoPxBTvrN.png', NULL, NULL, '小原好美', NULL, 196853, 'SUPPORTING', 51) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017840', 'AN1761', '竈門六太', '炭治郎の末っ子。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b207857-sn24LyeKSrPr.jpg', NULL, NULL, '古賀葵', NULL, 207857, 'SUPPORTING', 39) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017841', 'AN1761', '忍にん獣ムキムキねずみ', '宇髄天元の配下として働く知性を持つネズミたち。東京・吉原での出来事でも見られたように、これらのネズミは天元やその知人たちの助手となるべく、特別な訓練を受けている。 1匹につき1本の刀を運べるほどの力があり、通常なら人間が通り抜けられないような狭い場所も自在に動き回ることができる。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b246712-DYIZvLfd3pEM.png', NULL, NULL, '木村昴', NULL, 246712, 'SUPPORTING', 169) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017842', 'AN1761', '産屋敷 ひなき', '産屋敷ひなきは、産屋敷耀哉の長女の一人である。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b167549-1fG4eh5KkmZg.png', NULL, NULL, '花守ゆみり', NULL, 167549, 'SUPPORTING', 35) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017843', 'AN1761', '童磨', '彼は上弦の二であり、無惨と上弦の後に次ぐ、三番目に強い鬼である。非常に親しみやすい性格で、一対の金属製の扇を使って戦う。「永遠の楽園教団」と呼ばれるカルト教団の創始者であり、信者たちを「生きる苦しみから解放するため」という名目で、彼らを食していると言われている。', 20, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b144591-v2yrXtHorZFS.png', NULL, NULL, '宮野真守', 187, 144591, 'SUPPORTING', 1249) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017844', 'AN1761', '産屋敷 にちか', '産屋敷 にちかは、産屋敷耀哉の長女の一人である。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b167548-2bPBlCKBiIBY.png', NULL, NULL, '小澤亜李', NULL, 167548, 'SUPPORTING', 26) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017845', 'AN1761', '竈門葵枝', 'キエは竈門炭治郎の母親です。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b196849-xnYBt0Jf5Htf.png', NULL, NULL, '桑島法子', NULL, 196849, 'SUPPORTING', 85) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017846', 'AN1761', '竈門炭十郎', '竈門炭十郎は、竈門葵枝の夫であり、炭治郎、禰豆子、武雄、花子、茂、六太の亡き父であった。炭十郎は、物静かで思慮深く、寛容で、カリスマ性があり、愛情深い人物だった。 彼は家族と穏やかな関係を築き、たじろうには定期的に人生について説教をしていた。外見は穏やかに見えたが、周囲を静かに見極める力と、気高く高潔なオーラを漂わせていた。息子の話によると、彼は目立つことや、他人に自分の真の実力を見せつけることを好まなかったという。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b206330-dDKOKM4O2pVg.png', NULL, NULL, '三木眞一郎', NULL, 206330, 'SUPPORTING', 148) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017847', 'AN1761', '茶々丸', '茶々丸は、タマヨの「悪魔の血」に関する医学研究を手助けする猫の使い魔である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b268212-cdX6j5xYomyU.jpg', NULL, NULL, NULL, NULL, 268212, 'SUPPORTING', 181) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017848', 'AN1762', 'ガビ・ブラウン', 'ガビ・ブラウンは、リベリオ収容区に住むエルディア人で、ライナー・ブラウンのいとこである。彼女は、同じく戦士候補生であるウド、ゾフィア、そしてファルコ・グライスと親しい間柄だ。   ガビは非常に情熱的で頑固な性格で、感情や意見を遠慮なく表現する。また、勇敢で揺るぎない決意を持ち、自分にとってより偉大だと信じる神のために、目標を達成するためなら命を賭けることも厭わない。しかし、こうした性格ゆえに、時に横暴で威圧的な態度をとってしまうこともある。T', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b125659-O37MZQWibV7g.png', '4月14日', NULL, '佐倉綾音', 138, 125659, 'MAIN', 9795) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017849', 'AN1762', 'ジャン・キルシュタイン', '親族：母親のジーン・キルシュタインは第104期士官候補生隊の卒業生であり、ODM装備の操作技術と、より戦術的な視点で物事を見極める能力により、同期生の中で6位の成績を収めた。 ジーンはウォール・ローズのトロスト地区出身で、憲兵として城壁内で平穏な生活を送ることを望んで軍に入隊した。しかし、親友であるマルコ・ボットの言葉に説得され、また目の当たりにした惨状をきっかけに、後に調査兵団に加わることとなる。', 16, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b46498-ritqAj9FW6jX.png', '4月7日', NULL, '谷山紀章', 175, 46498, 'MAIN', 7253) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017850', 'AN1762', 'ミカサ・アッカーマン', '所属：第104訓練兵団、調査兵団 家族：実母（故人）、実父（故人）、グリシャ・イェーガー（養父）、カーラ・イェーガー（養母、故人）、エレン・イェーガー （養兄弟） ミカサはエレン・イェーガーの養妹であり、アルミン・アルレルトの幼なじみでもあり、ウォール・マリア南部のシガンシナ地区で二人と暮らしている。   幼い頃、両親は人身売買業者に殺害され、彼女自身も誘拐された。エレンはこの事実を突き止め、', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b40881-F3gr1PkreDvj.png', '2月10日', NULL, '石川由依', 170, 40881, 'MAIN', 28457) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017851', 'AN1762', 'エレン・イェーガー', '所属：調査兵団第104期訓練兵。   エレンは、ウォール・マリア南部のシガンシナ地区で、カーラとグリシャ・イェーガーの間に生まれた。彼は両親と、幼い頃にイェーガー家に引き取られた義理の妹ミカサと共に、この町で育った。 エレンは、ミカサや、二人が共通の親友であるアルミン・アルレルトと過ごす時間がほとんどで、二人はよく近所のいじめっ子からアルミンを守っていた。    エレンは情熱的で、意志が強く、頑固で、衝動的な若者である。彼らが子供の頃', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b40882-dsj7IP943WFF.jpg', '3月30日', NULL, '梶裕貴', 170, 40882, 'MAIN', 34518) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017852', 'AN1762', 'コニー・スプリンガー', '家族：母、マーティン・スプリンガー（兄）、サニー・スプリンガー（姉）  コニー・スプリンガーは第104期調査兵団の卒業生で、同期中8位の成績を収めた。ODMギアを駆使する際、最も素早い兵士の一人として知られており、鋭い旋回をこなすのが得意だ。 彼はウォール・ローズ内にある田舎のラガコ村の出身で、家族や村の人々に誇りに思ってもらうことが最大の夢である。卒業後、彼は調査兵団への入隊を選んだ。   明るく純真なコニーだが、やや集中力に欠ける面があり、', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n46486-izhPjzut6WCZ.png', '5月2日', NULL, '下野紘', 158, 46486, 'MAIN', 2794) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017853', 'AN1762', 'アルミン・アルレルト', '所属：調査兵団第104期訓練兵隊　家族：祖父　アルミンは、壁内のシガンシナ地区で生まれ育った少年で、エレン・イェーガーやミカサ・アッカーマンとは幼なじみである。 壁マリアが破られた後、彼はミカサやエレンと共に軍に入隊することを選んだ。それは、世界に偉大で意義ある影響を与えたいという思いと、外の世界を見るという夢を叶えたいという思いの両方からだった。幼い頃から、生まれつき好奇心旺盛なアルミンは常に', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b46494-g7xYYuBtYPnO.png', '11月3日', NULL, '井上麻里奈', 163, 46494, 'MAIN', 16006) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017854', 'AN1762', 'ジーク', 'ジークは現在、獣の巨人の継承者であり、ライナー・ブラウンからは「人類最強の戦士」というリヴァイの称号とは対照的に、最強の戦士と見なされている。', 25, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b125661-FiqFvAtNlL0v.png', '8月1日', NULL, '子安武人', 183, 125661, 'MAIN', 3713) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017855', 'AN1762', 'ファルコ・グライス', '役職：戦士候補生　ファルコ・グライス は、マーレイ政府に所属するエルディア人の戦士候補生であり、コルト・グライスの弟である。ファルコは、同じく戦士候補生であるウド、ゾフィア、ガビと親しい友人関係にある。  仲間の兵士たちほど体力には恵まれていないが、その欠点を機転の利いた対応と臨機応変な判断力で補っている。彼は非常に慈悲深く思いやりのある人物で、敵の兵士であっても、人々の命を守るために惜しみなく尽力する。また、非常に礼儀正しく、', 12, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b125660-mrmpOJLjJIkv.jpg', '2月10日', NULL, '花江夏樹', 140, 125660, 'MAIN', 1301) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017856', 'AN1762', 'ライナー・ブラウン', '調査兵団の隊員であり、第104期訓練兵の出身。 ライナーは、情熱的で意志が強く、強い責任感を持つ青年である。卒業時には訓練課程でミカサに次ぐ2位の成績を収めた。仲間たちからは絶大な信頼を寄せられており、第104期訓練兵たちの「兄貴分」と称されている。', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b46484-P6A2GjNQn49F.png', '8月1日', NULL, '細谷佳正', 185, 46484, 'MAIN', 8250) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017857', 'AN1762', 'コルト・グライス', '役職：戦士候補生　コルト・グライス は、マーリーに住むエルディア人で、ファルコ・グライスの兄である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b125665-TicVG3OEhTqc.jpg', '8月12日', NULL, '松風雅也', 180, 125665, 'SUPPORTING', 184) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017858', 'AN1762', 'ドット・ピクシス', '南部地域の最高位行政官。駐屯軍の南部領土を統括するピクシスは、鋭い洞察力を持つ狡猾な指導者である。しかし、彼はアルコール依存症でもあり、側近のアンカに常に監視されている。アンカは、重要な局面で彼が寝たり酒を飲んだりするたびに、絶えず叱責している。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b62485-I0U5Cat3z65K.png', NULL, NULL, '田中正彦', NULL, 62485, 'SUPPORTING', 701) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017859', 'AN1762', 'カリナ・ブラウン', 'カリナ・ブラウンは、ライナー・ブラウンの母親です。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b199712-YOV8LXBcQT1R.png', NULL, NULL, '湯屋敦子', NULL, 199712, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017860', 'AN1762', 'アルトゥル・ブラウス', '家族：リサ・ブラウス（妻）、サーシャ・ブラウス（娘）。アルトゥル・ブラウスはサーシャ・ブラウスの父親であり、ドーパー村の狩人である。サーシャが家を離れて軍に入隊するきっかけとなったのは、彼の言葉だった。  アルトゥルは、一族に深く献身する、成熟した父親のような存在であるようだ。彼は自身の生き方を大切にしている一方で、多くの人々が巨人に家を奪われたこと、そして大いなる神のために森を分かち合わなければならないことを理解している。彼は非常に賢明で、変化を受け入れる姿勢を見せ、', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b131281-TDm3VmnXgseC.png', NULL, NULL, 'かわのをとや', NULL, 131281, 'SUPPORTING', 39) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017861', 'AN1762', 'エーベル・レイス', 'エーベル・レイスは、ロッド・レイスとその妻の娘たちの中でも、比較的年下のひとりだった。', 12, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b310145-jzhLPSp1UlEd.png', NULL, NULL, '三浦千幸', NULL, 310145, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017862', 'AN1762', 'テオ・マガト', 'マーリー軍エルディア部隊の指揮官。 かつては第1期戦士候補生の訓練における主任監督官の一人であり、その後、中東連合軍との「マーレイ・中東戦争」においてエルディア戦士団を率い、マーレイの勝利に重要な役割を果たした。     （出典：進撃の巨人ウィキ）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b131763-YNYd9scK4Den.jpg', NULL, NULL, '斉藤次郎', NULL, 131763, 'SUPPORTING', 81) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017863', 'AN1762', 'ハンジ・ゾエ', '所属：調査兵団；分隊長、小隊長。調査兵団第4小隊の隊長であるハンゲは、巨人の研究も担当しており、その知識を追求するあまり、結果として巨人に執着するようになってしまった。 当初は巨人を深く憎んでいたハンジだったが、巨人への憎しみを捨て、被験者に思いやりを持って接するという、従来の枠にとらわれない新たな研究手法を採用することにした。  ハンジ', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b71121-7R7CnQd3lHgt.png', '9月5日', NULL, '朴璐美', 170, 71121, 'SUPPORTING', 15302) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017864', 'AN1762', 'アニの父', 'アニ・レオンハートの父親であり、トレーナーでもある。彼は主に蹴りと、攻撃者の体重を逆手に取る技を用いて、アニーに容赦なく戦闘訓練を施した。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b131257-EywhPQF0aqVU.png', NULL, NULL, '石井康嗣', NULL, 131257, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017865', 'AN1762', 'リサ・ブラウス', 'サシャ・ブラウスの母親であり、ブロース氏の妻。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b134952-DKs88MOSsIzE.png', NULL, NULL, '岩男潤子', NULL, 134952, 'SUPPORTING', 14) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017866', 'AN1762', 'キヨミ・アズマビト', 'キヨミはヒズルの大使であり、パラディス島のエルディア人の味方である。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b202799-WlK66SqrhzED.png', NULL, NULL, '吉沢希梨', NULL, 202799, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017867', 'AN1762', 'ヒッチ・ドリス', '所属：第104士官候補生隊。  ストーヘス地区に駐屯する憲兵隊の新兵。アニ・レオンハートと同室だった。ヒッチは時折子供っぽい振る舞いを見せるが、皮肉屋で気さくな性格であり、特にマーロ・フロイデンベルクをはじめとする同僚の将校たちをからかったり、いじったりすることを悪戯っぽく楽しんでいるようだ。 彼女は、上級将校たちが信じられないほど腐敗していることは周知の事実であり、その体制を自分自身の利益に利用したかったため、怠惰から憲兵隊に入隊したと主張している。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b86017-m6vXFRKWMwUo.jpg', '5月10日', NULL, '渡辺明乃', 168, 86017, 'SUPPORTING', 621) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017868', 'AN1762', 'キース・シャーディス', 'キース・シャーディスは、第104期訓練兵隊の主任教官だった。彼は、エレンがグリシャ医師の息子であることを知っており、エレンの努力を称賛していたことから、グリシャ医師と友人関係にあるか、何らかの関係があったようだ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n84305-15nngV5nTUp6.png', '8月18日', NULL, '最上嗣生', NULL, 84305, 'SUPPORTING', 276) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017869', 'AN1762', 'リヴァイ', '調査兵団内の特殊作戦班（通称「リヴァイ班」）の班長。人類最強の兵士として知られている。リヴァイは口調が荒く、物言いが率直で、規律と秩序を重んじる。潔癖症であり、自分自身、装備、そして周囲の環境に対して、一点の汚れもないほどの清潔さを求める。 兵士になる前の生活で、地下犯罪に関与していたという噂がある。感情を表に出さず、人当たりも悪いが、リヴァイは自分の分隊を深く気遣い、大いに', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b45627-CR68RyZmddGG.png', '12月25日', 'A', '神谷浩史', 160, 45627, 'SUPPORTING', 42797) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017870', 'AN1762', 'クリスタ・レンズ', '所属：調査兵団 第104期訓練生隊　訓練生クラスで10位の成績を収めたクリスタは、とても内気で優しく思いやりのある人物であり、仲間たちからは「女神」や「天使」とよく称されている。ユミルとは親友同士である。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b62481-ZZDa7vn17lMU.png', '1月15日', NULL, '三上枝織', 145, 62481, 'SUPPORTING', 4174) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017871', 'AN1762', 'フリーダ・レイス', 'フリーダはロッド・レイスの長女であり、ヒストリアの年上の異母姉だった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n127624-mmQqGCYRW69r.jpg', '2月2日', NULL, '日笠陽子', NULL, 127624, 'SUPPORTING', 93) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017872', 'AN1762', 'ダズ', 'ダズは第104期訓練兵隊の一員である。（出典：進撃の巨人ウィキア）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b84321-i4A69zVC6YMM.png', NULL, NULL, '田久保修平', NULL, 84321, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017873', 'AN1762', 'サシャ・ブラウス', '身長：168cm　所属：第104訓練隊、調査兵団　兵士　親族：アルトゥル・ブラウス（父）、リサ・ブラウス （母）　ウォール・ローズ南部の山岳森林地帯にある、人里離れた狩猟民の村ドーパー出身のサーシャは、第104期訓練兵団の士官候補生として入隊し、卒業時には9位の成績を収めた。 卒業後、彼女はスカウト連隊への配属を選んだ。  サーシャは親しみやすく、陽気な少女だ。彼女はウィットに富んだ話し方をし', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b45887-QPtJH0KwqthW.jpg', '7月26日', NULL, '小林ゆう', 168, 45887, 'SUPPORTING', 9188) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017874', 'AN1762', 'ポルコガリアード', '役職：マーリーの戦士　ポルコ・ガリアードはエルディアンであり、マルセル・ガリアードの弟である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b125662-an9dgh4LZ016.png', '11月11日', NULL, '増田俊樹', 175, 125662, 'SUPPORTING', 497) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017875', 'AN1762', 'ピーク・フィンガー', 'ピエックは、マーレーの戦士の一人として活動するエルディア人である。彼女はどこか優しく気さくな性格で、仲間の戦士や戦士候補生たちを常に気遣っている様子がうかがえる。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b125603-Z2rgiHUGbAmY.png', '8月5日', NULL, '沼倉愛美', 155, 125603, 'SUPPORTING', 3655) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017876', 'AN1762', 'ナイル・ドーク', '憲兵隊長。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b71123-FswK9rrdbR9h.png', '11月1日', NULL, '勝杏里', NULL, 71123, 'SUPPORTING', 38) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017877', 'AN1762', 'カルラ・イェーガー', 'エレンの母親。    注：カルラ・イェーガーは、講談社による公式の英語訳である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n62475-CExspVnLfweu.png', '1月29日', NULL, '鷹森淑乃', NULL, 62475, 'SUPPORTING', 451) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017878', 'AN1762', 'サムエル・リンケ-ジャクソン', 'サミュエルは第104期訓練兵の一員である。第3章に登場する。トロスト地区の外に超大型巨人が現れた際、その体から噴き出した蒸気の衝撃で、多くの訓練兵が壁から吹き飛ばされた。 ほとんどの訓練生は三次元機動装置に切り替えて壁に身を固定することができたが、サミュエルは落下してきた岩片が頭に直撃し、意識を失ってしまった。サシャは自分のグラップリングフックをサミュエルの脚に打ち込み、彼が転落死するのを防いだ。エレンはサシャにサミュエルを連れて行くよう指示した。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b84315-MwzNp8eSjg8v.png', NULL, NULL, '高橋研二', NULL, 84315, 'SUPPORTING', 30) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017879', 'AN1762', 'フリッツ', '彼は壁の王者だ。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n129941-R8tUKp7o10Jr.png', NULL, NULL, NULL, NULL, 129941, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017880', 'AN1762', 'グリシャ・イェーガー', 'エレン・イェーガーの父であり、ミカサ・アッカーマンの世話役である。ワクチンを開発して謎のウイルス性疫病から村を救ったことで、シガンシナ地区で広く尊敬を集める著名な医師である。 また、シガンシナ地区軍団内の人脈を持つほか、シガンシナの住民や周辺のいくつかの町に対して、往診サービスも行っている。妻はカーラ・イェーガーである。', 39, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b62477-3AHBGul9bXK8.jpg', '1月26日', NULL, '土田大', NULL, 62477, 'SUPPORTING', 629) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017881', 'AN1762', 'ユミル・フリッツ', 'ユミル・フリッツはエルディア人の始祖である。彼女は幼い頃、巨人の力を目覚めさせ、最初の巨人である「始祖の巨人」となった。 彼女の死後、その魂は九体の巨人に分かれた。彼女は、真の意図や動機を明かさない、物静かな性格であるとされている。    （出典：進撃の巨人 Wiki）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b199551-UNzb9vgcbOIx.png', NULL, NULL, '三浦千幸', NULL, 199551, 'SUPPORTING', 228) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017882', 'AN1762', 'ルイーゼ', '巨人の襲来時、母親と共にトロストで脱出を試みていた少女。ミカサ・アッカーマンや第104期生たちに救われた後、彼らの英雄的な行動に感化され、後に憧れのミカサに近づきたいという思いから、自ら調査兵団の新兵として入隊する。  ルイーゼは、この世で最も重要な資質は「強さ」であると信じており、その考え方は「力こそが正義」という姿勢に近いほどだ。この考え方の多くは、', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b209870-urk2Tf2nV0mQ.png', '4月25日', NULL, '永井真里子', NULL, 209870, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017883', 'AN1762', 'ロッド・レイス', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/127360-UgSpq6e0DAYz.jpg', NULL, NULL, NULL, NULL, 127360, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017884', 'AN1762', 'アニ・レオンハート', '士官候補生団の第104南部師団に所属していた。第104師団を卒業後、トップ10の中で4位という成績を収め、最終的に憲兵隊に入隊した。 ルームメイトはヒッチ・ドリス。無表情な少女であるアニーは、めったに笑顔を見せず、人付き合いもほとんどせず、感情の表れない表情を浮かべていることから、孤立した一匹狼タイプと見なされている。無気力で眠たげな性格で、無意味な規律や活動に努力を注ぐ意欲はほとんどない。それにもかかわらず、アニーを突き動かすものは……', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b46490-tan274Ifc1Jf.jpg', '3月22日', NULL, '嶋村侑', 153, 46490, 'SUPPORTING', 5385) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017885', 'AN1762', 'フロック・フォルスター', 'フロックは調査兵団の新入隊員である。彼は、オルヴド地区での襲撃からシガンシナ地区への帰還までの2か月の間に、調査兵団に入隊した。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b127703-qNIccR0yPZKu.png', NULL, NULL, '小野賢章', NULL, 127703, 'SUPPORTING', 803) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017886', 'AN1762', 'イェレナ', 'イェレナは、ジーク・イェーガーの指揮下で活動する「反マーレイ義勇軍」のリーダーである。彼女は、マーレイによるパラディス島への攻撃作戦が失敗に終わった後、同島へ向かった最初の調査艦隊に乗船していたマーレイ兵の一人だった。 彼女は非常に背の高い女性で、金髪の髪はストレートな前髪のあるショートボブに整えられている。大きな黒い瞳を持ち、体格やスタイルのせいでやや中性的な顔立ちをしている。イェレナはジーク・イェーガーの熱烈な信奉者であり、彼に対して深い敬意と尊敬を抱いている。普段は冷静で、', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b133216-HKl61n4F7eYv.png', NULL, NULL, '斎賀みつき', NULL, 133216, 'SUPPORTING', 1091) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017887', 'AN1762', 'カヤ', 'ウォール・ローゼに住む一般市民。ウォール・ローゼ侵攻の際、サシャ・ブラウスに巨人から救われ、現在はブロース家と暮らしている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n132738-I8jNSdoNIhZI.jpg', NULL, NULL, '浜崎奈々', NULL, 132738, 'SUPPORTING', 54) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017888', 'AN1762', 'ローグ', '軍警察連隊の高位将校。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b210462-XYnFRAnXLAmK.png', NULL, NULL, '大久保利洋', NULL, 210462, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017889', 'AN1762', 'スルマ', 'イェーガー主義者のメンバーであり、第109士官候補生団の元士官候補生。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b268344-QOirELiCXpnP.png', NULL, NULL, '坂田将吾', NULL, 268344, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017890', 'AN1762', 'マルセル・ガリアード', '<br><br> （出典：進撃の巨人ウィキア）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b127683-VDnuXVkMerjU.png', NULL, NULL, NULL, NULL, 127683, 'SUPPORTING', 18) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017891', 'AN1762', 'ニコロ', 'ニコロは、かつてマーレー海軍に所属していた元マーレー兵士であり、パラディス島作戦の失敗後、パラディス島へ向かった最初の偵察艦隊の一員だった。捕虜となった後、彼は島で軍用の料理人として働き始める。  ニコロは当初、パラディス島のエルディア人を「悪魔」と呼び、彼らを恐れる、ごく典型的なマーレ人だった。エルディア人に捕らえられ、彼らの傍らで生活しなければならないことに強い嫌悪感を抱いていたが、調査兵団と多くの時間を共にするうちに', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b133218-G3SQp19jnFIJ.png', NULL, NULL, '花輪英司', NULL, 133218, 'SUPPORTING', 446) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017892', 'AN1762', 'オニャンコポン', 'オニャンコポンは反マーリー派義勇兵の一人で、リベリオ襲撃の際には調査兵団を支援した。彼はハンジの命令に従い、調査兵団が撤退の際に使用する飛行船を操縦した。（出典：Attack on Titan Fandom）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b192909-81EoCndP0uEH.png', NULL, NULL, '樋渡宏嗣', NULL, 192909, 'SUPPORTING', 232) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017893', 'AN1762', 'コスロ', '彼は、マーリーが勝利を収める前に、中東連合軍との戦争で戦ったマーリー軍の将校である。（出典：進撃の巨人ウィキ）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b199549-ispr2ccdtGOw.png', NULL, NULL, '奈良徹', NULL, 199549, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017894', 'AN1762', 'フリッツ', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b268348-o2upT1kMLrYq.png', NULL, NULL, '津田英三', NULL, 268348, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017895', 'AN1762', 'ユミル', '所属：スコティング・レギオン第104訓練生小隊　スコティング・レギオンの一員。彼女は自己中心的で、皮肉屋で、横暴で、狡猾で、協力的ではなく、他人を搾取し、対立を好むように見えるが、特にクリスタに対しては親切な一面もあるようだ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b71479-huCD908XIdqv.png', '2月17日', NULL, NULL, 172, 71479, 'SUPPORTING', 3763) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017896', 'AN1763', '五条美織', 'ミオリは五条新菜のいとこだ。彼女は、一見奇妙に見える彼の行動（ストッキングを買うこと）を温かく見守っている。', 26, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b261779-55oYUO853NxE.png', NULL, NULL, '冨岡美沙子', NULL, 261779, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017897', 'AN1763', '天花寺ミライ', 'アニメ『フラワー・プリンセス・レツ!!』のヒロイン', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b275521-FxjjrI6l6Kum.jpg', NULL, NULL, '丹下桜', NULL, 275521, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017898', 'AN1763', 'のばら', 'ワカナは彼女の幼なじみだったが、男性であるワカナがひな人形に夢中になっていることを知った彼女は、彼を「気持ち悪い」と呼び、関係を断った。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b260976-BJaZR85k4YFp.png', NULL, NULL, '菅野真衣', NULL, 260976, 'SUPPORTING', 22) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017899', 'AN1763', '二階堂シオン', 'シオンは、アニメ『フラワー・プリンセス・ブレイズ』に登場する主人公です。サジュナは、このキャラクターの「ブラック・リリー」の姿をモチーフにしたコスプレ衣装を五条に作ってもらいたいと思っています。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b264037-6TxWVazNnEjx.png', NULL, NULL, '宍戸留美', NULL, 264037, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017900', 'AN1764', 'ハンセン', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b280443-Nd4GiXIk1zNd.png', NULL, NULL, '山口太郎', NULL, 280443, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017901', 'AN1764', 'エリヒド・Ｓ・Ｂ・ハイリヒ', '地球からの英雄たちがトルタスに召喚された当時、彼はハイリグ王国の王であった。彼は中村恵里のアンデッド軍団によって暗殺され、密かに彼女の奴隷の一人へと変えられていたが、南雲ハジメによって倒された。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b280446-T0t4Q5UXs1OX.jpg', NULL, NULL, '木村雅史', NULL, 280446, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017902', 'AN1764', 'メルド・ロギンス', '彼はハイリヒ王国の騎士団長である。異世界から召喚された英雄たちの訓練を監督する役割を担っていた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b280433-j6KYptApLa2f.jpg', NULL, NULL, '間宮康弘', NULL, 280433, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017903', 'AN1764', 'ノイント', '銀色の髪と青い目をした謎めいた女性。無機質で無表情なのが特徴だ。どのような存在なのかは不明である。予告編では、彼女がハジメと戦う様子が描かれている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b218473-MQLGL45FJN3i.png', NULL, NULL, '佐藤利奈', NULL, 218473, 'SUPPORTING', 40) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017904', 'AN1764', 'イシュタル・ランゴバルド', 'エヒットによって地球からの学生たちが召喚された当時、彼はトルトゥスで最も有力な宗教である聖教会の教皇であった。その後、ティオ・クラルスとアイコが教会の大聖堂を破壊した際、彼はティオ・クラルスによって殺害された。', 70, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b280445-T4Dn1N9dUvYD.jpg', NULL, NULL, '樫井笙人', NULL, 280445, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
