INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017907', 'AN1764', 'ハルガ・クラルス', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b280437-Stq29jS7X6BP.png', NULL, NULL, '小柳良寛', NULL, 280437, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017908', 'AN1764', '遠藤浩介', '遠藤浩介は、「召喚事件」に巻き込まれ、他のクラスメートたちと共にトルタスにたどり着いた日本人学生の一人である。 彼は永山ジュゴや野村健太郎と友人関係にあり、オルクスダンジョンでの訓練中は永山のパーティの一員だった。また、彼の存在感は極めて薄く、迷宮のモンスターや自動ドアには感知されない。', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b266647-MkSKaSe2sOir.jpg', NULL, NULL, '榎木淳弥', NULL, 266647, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017909', 'AN1764', '宮崎奈々', '彼女は「召喚事件」に巻き込まれた日本人学生の一人で、他のクラスメートたちと共にトルタスにたどり着いた。 園部優花や菅原妙子とは友人関係にあり、現在はあらゆる危険（王国のテンプラー騎士団の護衛を含む）から彼女を守るための「アイコちゃんのボディーガード」の一員となっている。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b280438-8s9lSzDCe220.png', NULL, NULL, '紡木吏佐', NULL, 280438, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017910', 'AN1765', 'ウェイン・サレマ・アルバレスト', 'ワインはナトラの皇太子である。彼は病に伏す父に代わって、この国の将来を担うことになる。家臣たちは彼の地位の高さゆえに彼を信頼しているが、実のところ彼は怠け者だ。彼は行き詰まったナトラ王国を売り払い、のんびりとした隠居生活を送りたいと考えている。  （出典：公式サイト、翻訳）', 16, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b206359-djoSGPyvgZW4.png', NULL, NULL, '斉藤壮馬', NULL, 206359, 'MAIN', 477) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017911', 'AN1765', 'ニニム・ラーレイ', 'ニニムは、美しい白髪と赤い瞳を持つフラームの少女で、ワインの幼なじみである。彼の首席補佐官として、国政から戦闘に至るまであらゆる面で彼を支えている。彼女は、ワインの本当の姿や、王国が現在直面している深刻な窮状を知っている数少ない人物の一人である。', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b206374-2idUUtEdB1Lo.jpg', NULL, NULL, '高橋李依', NULL, 206374, 'MAIN', 1801) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017912', 'AN1765', 'ハガル', 'ナトラ王国の将軍。戦場のベテランであり、ワインから軍事面の任を任されている。ワインの才能を高く評価しており、その指導力に不満を抱く地方の領主たちを鎮圧するために尽力している。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b206739-sKdDr7micCyr.jpg', NULL, NULL, '菅生隆之', NULL, 206739, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017913', 'AN1765', 'ウルギオ', 'マーデン軍の将軍。ニニムとの戦いで戦死した。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b206745-UDe57xYUBKs6.jpg', NULL, NULL, '稲田徹', NULL, 206745, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017914', 'AN1765', 'グリナッヘ・アントガダル', '第2代ゲイラン侯爵。多くの人々は、彼がその悪名高い父が知られていたような資質を欠いていると評している。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b207260-ZrS1BoROSx9m.jpg', NULL, NULL, '深澤純', NULL, 207260, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017915', 'AN1765', 'ジーヴァ', '元々はマーデン王国の外交官だった。その愛国心と誠実な人柄がゼノヴィアの信頼を勝ち取り、同王国が属国となった後、彼女の補佐官兼右腕としての地位を得た。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b206738-mHZ5jj2j3LI6.jpg', NULL, NULL, '荻野晴朗', NULL, 206738, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017916', 'AN1765', 'カルドメリア', 'レヴェティアのゴスペル局局長。女性が重要な役職に就くことが許されない社会において、名門ゴスペル局の局長という地位にまで上り詰めた、抜け目のない女性である。笑顔と穏やかな雰囲気の背後に、その狡猾さを隠している。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b207180-S3bvayWUjWFB.jpg', NULL, NULL, '能登麻美子', NULL, 207180, 'SUPPORTING', 24) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017917', 'AN1765', 'ホロヌィエ', 'マーデン王国の財務大臣。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b206747-94zPsrwALWCU.jpg', NULL, NULL, '高橋伸也', NULL, 206747, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017918', 'AN1765', 'テオルド・タルム', 'フィッシュ氏が解任された後、後任として就任した大使。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b206748-95o1B3g4lWa4.jpg', NULL, NULL, '島田高虎', NULL, 206748, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017919', 'AN1765', 'シリジス', 'デルニオの首相。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b276007-WeAERQhYpenJ.jpg', NULL, NULL, '土師孝也', NULL, 276007, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017920', 'AN1765', 'フラーニャ・エルク・アルバレスト', 'ヴァイン・サレマ・アーバレストの妹。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b206391-YfAJV4PiErr5.png', NULL, NULL, '千本木彩花', NULL, 206391, 'SUPPORTING', 130) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017921', 'AN1765', 'マンフレッド・アースワルド', 'アースワールド帝国の第三王子。物腰が柔らかく、雄弁な紳士である。将来の皇帝として恩恵を約束し、新興の貴族や諸州から多大な協力を得ている。ワインを高く評価しているが、彼の考えを読み取るのに苦労している。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b207647-eJ5GB6pp3rJJ.jpg', NULL, NULL, '河西健吾', NULL, 207647, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017922', 'AN1765', 'ドラーウッド', 'マーデンの将軍。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b263707-Ol5ym6AZY0DU.jpg', NULL, NULL, '柳田淳一', NULL, 263707, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017923', 'AN1765', '総督', 'ガイランの知事。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b264186-OAydyJNRLHjn.jpg', NULL, NULL, '若林佑', NULL, 264186, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017924', 'AN1765', 'ロウェルミナ・アースワルド', 'アースワールド帝国の最年少の王女であり、ワインとニニムの元同級生。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b206741-3dEMacrdCj8K.jpg', NULL, NULL, '東山奈央', NULL, 206741, 'SUPPORTING', 142) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017925', 'AN1765', 'ディメトリオ・アースワルド', 'アースワールド帝国の第一王子。その能力や人柄で評価されているわけではなく、長男であるという理由だけで一部の貴族から支持されている。強い自尊心を持っており、他人を抑圧する傾向があり、何事にも攻撃的である。弟や妹たちをあまり好んでいない。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b207646-cnGCkFkDhAFl.jpg', NULL, NULL, '木島隆一', NULL, 207646, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017926', 'AN1765', 'クラディオス', 'ファラニャの指導者であり、ワインが幼少期の頃の指導者でもあった。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b263708-okJrFLYDe2W7.jpg', NULL, NULL, '小形満', NULL, 263708, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017927', 'AN1765', 'ルベール', 'カヴァラン将軍の軍。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b207257-qJZXMvA9NK3l.jpg', NULL, NULL, '五味洸一', NULL, 207257, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017928', 'AN1765', 'ナナキ・ラーレイ', 'ナナキは、フラーニャ・エルク・アルバレスト王女の護衛である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b206750-7TtGMOfwiQYL.jpg', NULL, NULL, '榊原優希', NULL, 206750, 'SUPPORTING', 55) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017929', 'AN1765', 'ラークルム', 'ナトラ王国の軍司令官。ワインに忠誠を尽くし、戦いの先頭に立って彼を護り、時には護衛を務めることもある。がっしりとした体格だが、控えめな性格のため、威圧的な印象を与えることはない。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b206740-5ZoTbKUOIBTZ.jpg', NULL, NULL, '濱野大輝', NULL, 206740, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017930', 'AN1765', 'オルドラッセ', 'カヴァリンの王。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b207256-JKvvWALn7D83.jpg', NULL, NULL, '高木渉', NULL, 207256, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017931', 'AN1765', 'ゼノ', 'マーデン解放軍の幹部。同軍の指導者であるヘルムート王子の側近である。鋭い洞察力を持つ聡明な人物だが、故郷を征服したカヴァリン王国への復讐に感情的にのめり込んでしまうこともある。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b207181-8h0tI8vQZtO7.jpg', NULL, NULL, '中島由貴', NULL, 207181, 'SUPPORTING', 161) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017932', 'AN1765', 'トルチェイラ・ソルジェスト', 'ソルジェスト王国の王女。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b208484-WwYLFwjF4Umh.jpg', NULL, NULL, '釘宮理恵', NULL, 208484, 'SUPPORTING', 27) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017933', 'AN1765', 'コジモ', 'ミールターズ市長。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b207649-HiO1V0pASuxx.jpg', NULL, NULL, '樫井笙人', NULL, 207649, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017934', 'AN1765', 'フィシュ・ブランデル', 'アースワールド帝国からナトラ王国へ派遣された大使。帝国ではローウェルミナ王女の補佐官としてその信頼を勝ち得てきた、冷静で有能な若手官僚である。彼女はワインの才能と動向を注視している。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b206373-9TKto8w3Jh5w.png', NULL, NULL, '日笠陽子', NULL, 206373, 'SUPPORTING', 43) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017935', 'AN1765', 'バルドロッシュ・アースワルド', 'アースワールド帝国の第二王子。幼い頃から戦士として鍛えられ、軍事にも精通しており、帝国軍からの支持も厚い。将軍として部隊を率いた経験があり、戦闘能力も一流だが、政治に疎いことが足かせとなっている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b207648-pCcZ2aLkvboc.jpg', NULL, NULL, '松田健一郎', NULL, 207648, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017936', 'AN1765', 'オウル', '帝国打倒を目指すグリンヘの反乱における協力者。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b264184-DAsRtCDkTqeI.jpg', NULL, NULL, '今井文也', NULL, 264184, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017937', 'AN1765', 'グリュエール・ソルジェスト', 'ソルジェスト王国の王。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b208485-ZKFLaX7MvK1P.png', NULL, NULL, '大塚明夫', NULL, 208485, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017938', 'AN1765', 'ペリント', '彼はジラート金鉱山の運営を統括している。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b206742-fDKjCmWSXwWL.jpg', NULL, NULL, '中村光樹', NULL, 206742, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017939', 'AN1765', 'ゲラルト・アントガダル', 'グリナッヘ・アントガダルの息子。ローウェルミナを困らせることに、彼は絶えず二人の婚約に関する空想を口にしては彼女を煩わせている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b207259-pLl39hRIYHO8.jpg', NULL, NULL, '手塚ヒロミチ', NULL, 207259, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017940', 'AN1766', 'ノエ・アルシヴィスト', '種族：ヴァンパイア　職業：学生　パートナー：ヴァニタス　ノエは紳士的なヴァンパイアである。彼の物語は、「先生」から一通の手紙を受け取ったことから始まった。その手紙には、「ヴァニタスの『ボック』がパリで発見されたという噂があるため、直ちにパリへ飛んでくるように」と書かれていた。 その後、「師」はノエに対し、「ヴァニタスの本」の真の正体を突き止めるよう、明確に命じた。', 19, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89835-xnAJMex6Uq0U.png', '9月28日', NULL, '石川界人', 187, 89835, 'MAIN', 3903) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017941', 'AN1766', 'ヴァ二タス', '種族：人間　職業：医師　パートナー：ノエ・アルシヴィスト（現在）、ダンテ（元）　ヴァニタスは、あの悪名高い吸血鬼からその名と『ヴァニタスの書』を受け継いだ、ごく普通の人間である。  彼は物事をあまり真剣に受け止めず、ほとんどいつも満面の笑みを浮かべている。彼の計画はたいてい無謀なものなので、行動は思考よりも感情に左右されることが多い。また、いたずらっぽい雰囲気を漂わせている。', 18, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89590-K3RdKR4VnYM4.png', '2月7日', NULL, '花江夏樹', 176, 89590, 'MAIN', 5925) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017942', 'AN1766', 'ルスヴン', '種族：ヴァンパイア　パートナー：ジャンヌ（元）　ルースヴェン卿は、上院議員として女王に仕えるヴァンパイアの領主である。その地位ゆえに、ルースヴェン卿は人間とヴァンパイアの戦争以来、一貫して重要な地位を占めてきた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155326-IZqGLZVEVuWh.png', NULL, NULL, '森川智之', NULL, 155326, 'SUPPORTING', 78) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017943', 'AN1766', 'ミハイル', '種族：人間　年齢：不明　ミシャは明るい笑顔を浮かべており、とても親しみやすく、洞察力にも富んでいるように見えるが、どこか少し危険な印象も受ける。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b181061-hBbyje40Grml.png', NULL, NULL, '小松未可子', NULL, 181061, 'SUPPORTING', 92) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017944', 'AN1766', '先生', 'マスターはド・サド家の貴族の一員であり――ドミニク・ド・サドの祖父にあたる――多くの人々から恐れられている。（出典：Pandora Hearts Wikia）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b230438-6Cj7opQNCiFH.jpg', NULL, NULL, '石田彰', NULL, 230438, 'SUPPORTING', 37) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017945', 'AN1766', 'ロキ・オリフラム', 'ロキはルカ・オリフラムの兄であり、強力なビーストイアとして女王に仕えているが、同時に「呪いを持つ者」としても知られている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b266525-55VQnVnzhF3O.png', NULL, NULL, '杉山紀彰', NULL, 266525, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017946', 'AN1766', 'パークス・オルロック', 'パークス・オルロックは、人間と吸血鬼の戦争を経て、女王によって吸血鬼側の代表に任命された人物である。吸血鬼に関連する活動を監視し、人間界と吸血鬼界のバランスを維持することを任務としている。（出典：望月ウィキ）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b242839-nwq2Mg2hk9O6.png', NULL, NULL, NULL, NULL, 242839, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017947', 'AN1766', 'クロエ・ダプシェ', '種族：吸血鬼　パートナー：ジャン＝ジャック　彼女はアプシェール侯爵の城に住む吸血鬼であり、その存在は隠されており、侯爵家では「隠された吸血鬼」として知られている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b146014-lhZxoInTtvNc.jpg', NULL, NULL, '釘宮理恵', NULL, 146014, 'SUPPORTING', 546) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017948', 'AN1766', 'ヴェロニカ・ド・サド', '「クリムゾン・モン」のヴァンパイアであり、コント・ド・サドの次女、ドミニク・ド・サドの姉にあたる。彼女は「ビーストイア」――すなわちファウスティナ女王の執行者――として活動しており、これは彼女が「ワールド・フォーミュラ」を改変して氷を生み出す能力を持つことに由来する。 ビーストイアとしての在任中、ヴェロニカは同じくビーストイアであるマキナ侯爵と親密な関係になった。（出典：望月ウィキ）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b242848-ZrwK3icUxCJM.jpg', NULL, NULL, '日笠陽子', NULL, 242848, 'SUPPORTING', 55) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017949', 'AN1766', '蒼月の吸血鬼　"ヴァニタス"', '「ブルー・モンのヴァニタス」は吸血鬼である。伝説によれば、彼らはブルー・モンの下で生まれ、『ヴァニタスの書』と「マルノメン」という病の、表向きの生みの親とされる。 その目的は、吸血鬼たちの「真の名」を汚すことで彼らを滅ぼし、自らの出生ゆえに生涯にわたって受けた迫害への復讐を果たすことだった。この力は子孫へと受け継がれ、すべての吸血鬼の終焉をもたらすと予言されていた。（出典：望月淳ウィキ）', NULL, 'なし', 'https://s4.anilist.co/file/anilistcdn/character/large/b236204-j2oLxMGsmdxY.png', NULL, NULL, '朴璐美', NULL, 236204, 'SUPPORTING', 96) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017950', 'AN1766', 'ルイ・ド・サド', '彼は「クリムゾン・モン」の吸血鬼である。ロイスはヴェロニカやドミニク・ド・サドらと同様に、ド・サド家の貴族として生まれたが、ある事情により、コンテ・ド・サドによって祖父のもとへ永久に預けられた。 祖父のもとで暮らすうちに、ロイスはノエ・アルシヴィストと出会い、二人は親しい友人となった。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b146017-Ne3YSTuBIAI7.png', NULL, NULL, NULL, NULL, 146017, 'SUPPORTING', 342) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017951', 'AN1766', 'ジャン＝ ジャック', '種族：吸血鬼　パートナー：クロエ・ダプシェール　ジャン＝ジャックは、ジェヴォダンにあるシルバー・フォレストのダプシェール家城で、クロエ・ダプシェールの従者であることが示されている吸血鬼である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155330-V8SgSF3P5FTV.png', NULL, NULL, '濱野大輝', NULL, 155330, 'SUPPORTING', 145) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017952', 'AN1766', 'ダンテ', '種族：ダンピール　職業：情報ブローカー　パートナー： 	ヨハン（現在）、リシェ（現在）、ヴァニタス（元）  ダンテは、保険ブローカー兼何でも屋として活動するダンピールである。彼はしばしばヴァニタスとパートナーを組み、情報を売り込んだり、呪いを宿した吸血鬼を追跡するために共に活動したりしている。  ダンテはヴァ二タスと接する際、かなり気楽な態度をとる傾向がある――とはいえ、雇い主でありパートナーであるヴァ二タスにはすぐに苛立ちを覚える。特に、ヴァ二タスに「ハゲ」と呼ばれると、その傾向が顕著だ。二人はよく互いに皮肉を言い合っている。', 18, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155328-odVkNctgtTp0.jpg', NULL, NULL, '木内太郎', NULL, 155328, 'SUPPORTING', 81) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017953', 'AN1766', 'Riche', '種族：ダンピール　職業：情報ブローカー　パートナー：ダンテ、ヨハン　リシェは、情報ブローカーとして活動するダンピールである。同じくダンピールであるダンテやヨハンとよくタッグを組み、主に「呪いを背負った吸血鬼」に関連する事件を担当している。  リシェは学識豊かで情熱的な女性であり、興味のある話題になるとつい熱く語り込んでしまう。また、自分の知識を語りすぎたり、話が脱線したりする癖を自覚しているため、話を終えた後はすぐに謝る傾向がある。彼女は非常に…', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155327-GJ5jjDuiglEh.png', NULL, NULL, NULL, NULL, 155327, 'SUPPORTING', 14) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017954', 'AN1766', 'アメリア・ルース', 'アメリア・ルースは、ノエが「ラ・バレイン」号に乗ってパリへ旅した際に出会った女性である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b236210-pZ3EJCSJNmqG.png', NULL, NULL, NULL, NULL, 236210, 'SUPPORTING', 19) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017955', 'AN1766', 'ローラン・フォルティス', '種族：人間　職業：シャスール隊長　彼は人間であり、「第六のパラディン」として知られ、シャスールとしての功績により、緑色の宝石「ジャスパー」を授与されている。  ローランドは、自身の信念に対する狂信的な姿勢を強調するような振る舞いをしばしば見せ、周囲の状況や、自分の言動が他者からどう受け止められているかには無頓着に見える。それにもかかわらず、彼は実際には非常に鋭敏で、さりげなく状況を自分の意のままに操る。また、真面目で有能、そして手強い敵でもあり、あらゆる手段を厭わず', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b139554-kD2aBERnYQPA.png', '8月19日', NULL, '河西健吾', NULL, 139554, 'SUPPORTING', 452) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017956', 'AN1766', 'Johann', '種族：ダンピール　職業：情報屋　パートナー：ダンテ、リッチ　ヨハンは、情報ブローカーとして活動するダンピールであり、ダンテとリッチの仲間である。  ヨハンは、往々にして生き生きとした表情を見せ、からかいや軽妙な口調で話すなど、派手な性格が特徴だ。身体的な接触を好む傾向があり、話している時に相手に体をすり寄せたり、腕を回したりすることがある。しかし、追い詰められれば、ヨハンは仲間を守るために手段を選ばない。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155329-iTKKoVhnjfdw.png', NULL, NULL, '遊佐浩二', NULL, 155329, 'SUPPORTING', 70) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017957', 'AN1766', 'マーネ', 'マーネは、コント・パークス・オルロックのもとで、妹のノックスと共に彼の専属警護として働いている吸血鬼である。（出典：The Mochizuki Wiki）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b242842-B2ebjuIckBhR.png', NULL, NULL, NULL, NULL, 242842, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017958', 'AN1766', 'モロー', 'ドクター・モローは、望月ジュンの『ヴァニタスの事例研究』に登場する人間である。かつては吸血鬼の研究を行うためシャスールに雇われていた狂気の科学者だったが、自らも吸血鬼になることに執着した結果、シャスールから追放されてしまった。   （出典：Mochijun Wiki）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b250994-OS8LOk0wcp7B.jpg', NULL, NULL, NULL, NULL, 250994, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017959', 'AN1766', 'アストルフォ・グラナトゥム', '種族：人間　職業：シャスールのパラディン　彼は15歳でシャスール史上最年少のパラディンとなった人間であり、「吸血鬼はすべて本質的に邪悪である」という偏見に囚われ、信仰の名の下に吸血鬼の根絶に生涯を捧げてきた。   アストルフォは戦闘において精神異常的な行動を示す。女性と間違えられたといった些細な不満を理由に、人間も吸血鬼も区別なく虐殺することを好む。彼の信念は、チャ', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b145998-2aV7SZGyWXBc.png', NULL, NULL, '村瀬歩', NULL, 145998, 'SUPPORTING', 211) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017960', 'AN1766', 'ムル', 'ノエの飼い猫。ムルはイライラしている様子以外、他の感情を一切見せないが、ノエのことをとても大切に思っているようだ。よく影に潜んで、ノエを見守っている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b146015-TTM14WCYx74X.jpg', NULL, NULL, '小牧未侑', NULL, 146015, 'SUPPORTING', 429) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017961', 'AN1766', 'マルコ', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b300606-8bCvzjriOiWA.png', NULL, NULL, '小形満', NULL, 300606, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017962', 'AN1766', 'ルキウス・オリフラム', '種族：吸血鬼　職業：大公　パートナー：ジャンヌ　ルカは、大公の称号を継ぐために生まれた貴族出身の吸血鬼である。彼は女王と親しい関係にあるが、まだその役割を担うには若すぎるため、叔父のルースヴェン卿が彼に代わって職務を遂行している。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b153506-DC5iKSUyp1Sp.png', '7月31日', NULL, '下地紫野', NULL, 153506, 'SUPPORTING', 38) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017963', 'AN1766', 'オリヴィエ', '種族：人間　職業：シャスールのパラディン　オリヴィエは、シャスールとしてのローランドの不適切な振る舞いに常に苛立ちを覚え、神経が高ぶっている。彼はローランドに対してすぐに怒りを露わにし、ローランドのわがままをなだめることができないことに常に苛立ちを感じている。', 27, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155325-U1McQSCdYHof.png', '11月3日', NULL, '前野智昭', NULL, 155325, 'SUPPORTING', 114) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017964', 'AN1766', 'ジャンヌ', '種族：吸血鬼　職業：シュヴァリエ（現在）、ボロー（過去）　ルカのシュヴァリエを務める吸血鬼。  ジャンヌはルカを激しく守り抜き、彼のシュヴァリエとしての職務を遂行する際には厳格さと力強さを漂わせているが、特に嫌っているヴァニタスの前では、慌てふためく傾向がある。 かつてボローだった過去のため、自分に向けられる優しさに慣れておらず、その結果、優しさを受けるとすぐに動揺してしまう。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b89836-xLr4mkxojjc3.png', '4月21日', NULL, '水瀬いのり', NULL, 89836, 'SUPPORTING', 2431) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017965', 'AN1766', 'ジョルジュ', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b246646-8KhsoXiKOW6i.jpg', NULL, NULL, NULL, NULL, 246646, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017966', 'AN1766', 'マリア', 'マリアは、望月ジュンの『ヴァニタスの事例研究』に登場する人間のキャラクターである。シャスールとして、マリアは「吸血鬼は総じて邪悪である」という偏見にさらされてきたため、自らの信仰の名の下に、吸血鬼を根絶することに人生を捧げてきた。 最近、マリアは、シャスール・パリ支部に新しく配属されたローラン・フォルティスの指揮下で活動することになった。（出典：望月ジュン Wiki）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b246645-5ogTSNaXyCOX.jpg', NULL, NULL, NULL, NULL, 246645, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017967', 'AN1766', 'ドミニク・ド・サド', '種族：ヴァンパイア　職業：貴族、王室近衛兵　ノエの幼なじみであり、ロイスとヴェロニカの妹。 父はサド伯爵、祖父はノエの師匠である。 彼女は軽薄で、遊び心があり、エネルギッシュで、魅力的な若い令嬢だ。初登場時には機械を使ってバラの花びらを散らすほど、風格と優雅さを兼ね備えた歩き方をする。しかし、身近な人々を傷つけると疑う相手に対しては、躊躇なく手を出す。', 20, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b139553-Ni2xZ2U8aPii.jpg', '6月1日', NULL, '茅野愛衣', NULL, 139553, 'SUPPORTING', 1509) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017968', 'AN1766', 'ネーニア', 'ネーニアは、望月ジュンの『ヴァニタスの事例研究』に登場する、神秘的で幽玄な存在である。シャルラタンの一員として、ネーニアは仲間たちと共に、吸血鬼の潜在意識に侵入し、その真の名を歪めることで「マルノメン」を植え付ける活動を行っている。 現時点では、ネーニアが何者なのか、またその行動の動機は何かについては明らかになっていない。', NULL, 'なし', 'https://s4.anilist.co/file/anilistcdn/character/large/b155248-TIy6LhGqTb4W.jpg', NULL, NULL, '名塚佳織', NULL, 155248, 'SUPPORTING', 16) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017969', 'AN1766', 'ノックス', 'ノックスは、コント・パークス・オルロックのもとで、兄のマーネと共に彼の専属警護として活動している吸血鬼である。（出典：The Mochizuki Wiki）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b242840-UmpjDA6l05dT.png', NULL, NULL, NULL, NULL, 242840, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017970', 'AN1767', 'アルマ＝レプシウス', 'レプキウス家の三女。ルーリーの親友であり、「第二の紋章」を宿している。マティアスやルーリーほど魔力は高くないが、弓術の腕前は抜群である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b138226-acx8enyabd5f.png', NULL, NULL, '白石晴香', NULL, 138226, 'MAIN', 74) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017971', 'AN1767', 'マティアス＝ヒルデスハイマー', '約5000年以上前の前世では「ガイアス」として知られていた彼は、転生魔法を用いて「第一のクレスト」よりも優れた新たなクレストを手に入れるため、マティアスとして転生を果たした。 転生により「第四のクレスト」を手に入れることに成功した。彼の人生の主な目標は、異空間に棲む強大なモンスターたちに挑み、戦えるだけの力を得ることである。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b138225-ru1YtY83CuVU.png', NULL, NULL, '玉城仁菜', NULL, 138225, 'MAIN', 113) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017972', 'AN1767', 'ルリイ＝アーベントロート', 'アベンドロス家の娘。初対面からマティアスに想いを寄せており、マティアスの前世と同じように「ファースト・クレスト」を宿している。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b138224-AVeo46WVr6qB.png', NULL, NULL, '鈴代紗弓', NULL, 138224, 'MAIN', 97) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017973', 'AN1767', 'イリス', '「黒竜イリス」としても知られる彼女は、現存するドラゴンの中でも最も古く、最強の一体である。千年の時を経て再会した際、マティアスの正体を知っているのは彼女だけであり、彼の願いに応じてそのことを秘密にすることにした。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b201538-KJ2lLvuf2Pde.png', '1月21日', NULL, '井澤詩織', NULL, 201538, 'MAIN', 252) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017974', 'AN1767', 'Devilius', '彼は第一アカデミーの代表だ。一見、悪魔のように見えた。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b206805-bPalNg9jfi7T.png', NULL, NULL, '岡本信彦', NULL, 206805, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017975', 'AN1767', 'フェイカス', '初代王立アカデミーの校長。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b206785-T4t4YWViUwJu.png', NULL, NULL, '飛田展男', NULL, 206785, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017976', 'AN1767', '国王', 'アイス王国の王。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b206783-kUmyCIHY9pdw.png', NULL, NULL, '堀内賢雄', NULL, 206783, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
