INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017980', 'AN1767', 'ガイアス', 'ガイアスは、およそ1万2000年前、「賢者」と呼ばれた強力な魔術師だった。彼は「第一の紋章」を持って生まれ、そのため、ある一連の魔法を習得した後は、それ以上の成長ができなくなってしまった。 この人生において、彼は並外れて強力な存在と見なされていたが、宇宙の彼方に潜む怪物たちに立ち向かうために、さらに強くなりたいと願い、その目標を達成するために転生した。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b262323-3YTMyGHArzA8.png', NULL, NULL, '小野大輔', NULL, 262323, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017981', 'AN1767', 'Elhart', '彼は悪魔だ', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b206790-0DVdshPaUApF.png', NULL, NULL, '松風雅也', NULL, 206790, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017982', 'AN1767', 'ガイル', 'ガイルはアイス王国の騎士団長である。また、マティアスの父であるカストルの知人でもある。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b206591-MNpkxTkXVi9K.png', NULL, NULL, '小林親弘', NULL, 206591, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017983', 'AN1767', 'ザリディアス', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b195258-E1QZEsQ7icYP.png', NULL, NULL, '子安武人', NULL, 195258, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017984', 'AN1767', 'エデュアルト', '第二王立アカデミーの校長。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b206587-lP2xWm7leQP2.png', NULL, NULL, '小山力也', NULL, 206587, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017985', 'AN1767', 'ギルアス', '彼は、マティのグループがギルド内でランクアップできるかどうかを判断するための審査員だ', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b208360-FvNPw2Elcpk8.png', NULL, NULL, '松岡禎丞', NULL, 208360, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017986', 'AN1768', 'リーシア・エルフリーデン', '種族：人間　リーシア・エルフリーデンは、『現実主義勇者の王国再建記』シリーズのメインヒロインである。 彼女はエルフリーデンの王女であり、前王アルベルト・エルフリーデンの娘であるほか、ソーマの仮の婚約者として、フレイドニアの初代正妃でもあった。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n133336-lB9x2ceRcDfp.jpg', NULL, NULL, '水瀬いのり', NULL, 133336, 'MAIN', 571) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017987', 'AN1768', '相馬一也', '相馬一也は、『i』『現実主義英雄の大王国再建記』</i>シリーズの男性主人公である。彼は地球人であり、英雄として異世界に召喚されたが、前王アルベルト・エルフリーデンによる的確な布告により、エルフリーデン王国の王となった。一也が王位を簒奪したと考える民衆の反乱を避けるため、王は娘を一也に嫁がせた。一也は他者に自己紹介する際、日本の姓の形式を用いて', 19, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n133333-53OfUScBG41p.png', NULL, NULL, '小林裕介', NULL, 133333, 'MAIN', 328) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017988', 'AN1768', 'トモエ・イヌイ', '種族：ミスティックウルフ　トモエ・イヌイは、『現実主義英雄の王国再建記』シリーズに繰り返し登場するキャラクターである。（出典：『現実主義英雄の王国再建記』Wiki）', 10, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n133338-boVMSdhJ8qrG.png', NULL, NULL, '佳原萌枝', NULL, 133338, 'SUPPORTING', 132) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017989', 'AN1768', 'エクセル・ウォルター', '彼女は、カルラ・バルガスとジュナ・ドーマの祖母であり、かつて空軍司令官を務めたカストール・バルガスの義母でもある。現在は国防軍の最高司令官を務めている。', 500, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b214660-HihQJwEjpxB9.png', NULL, NULL, '堀江由衣', NULL, 214660, 'SUPPORTING', 85) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017990', 'AN1768', 'ジーニャ・マクスウェル', 'ジェニアは人付き合いを好まないが、かなり人当たりが良い。たとえ周囲が彼女の考えを「おかしな」ものだと一蹴しても、普通に会話を続けることができる。これは、カズヤやルドウィン、そして最近親しくなった研究者の同僚たちとのやり取りにおいて、特に顕著に表れている。', 20, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b277885-x7dWyHBRQEFy.png', NULL, NULL, '小原好美', NULL, 277885, 'SUPPORTING', 15) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017991', 'AN1768', 'ジャンヌ＝ユーフォリア', '年齢：17歳前後　ジャンヌ＝ユーフォリアは、『現実主義勇者の王国再建記』シリーズに登場する常連キャラクターである。彼女はグラン・カオス帝国の皇太子兼軍司令官であり、現皇后マリア・ユーフォリアの妹でもある。  （出典：『現実主義勇者の王国再建記』Wiki）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n133340-KomdNl7C72cy.png', NULL, NULL, '石川由依', NULL, 133340, 'SUPPORTING', 73) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017992', 'AN1768', 'エリシャ・エルフリーデン', '種族：人間　エリシャ・エルフリーデンは、『現実主義勇者の王国再建記』シリーズの登場人物である。彼女は、エルフリーデン王国第12代国王の死後に起きた王位継承危機において、エルフリーデン王家の最後の生存者として、同王国の正統な王位継承者であった。 彼女は後に「アルバート」と結婚し、彼に自身の姓を名乗らせるとともに、エルフリーデン王国第13代国王の座を譲った。  （出典：『現実主義勇者の王国再建記』Wiki）', 30, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b133339-fbwbEqZaYGhX.png', NULL, NULL, '井上喜久子', NULL, 133339, 'SUPPORTING', 49) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017993', 'AN1768', 'ジュナ・ドーマ', 'ジュナ・ドーマは、『現実主義勇者の王国再建記』シリーズの女性主人公の一人である。彼女はエクセル・ウォルターの孫娘である。', 19, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n133337-EPxGDgelQBlI.png', NULL, NULL, '上田麗奈', NULL, 133337, 'SUPPORTING', 313) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017994', 'AN1768', 'マリア・ ユーフォリア', '彼女はジャンヌ＝ユーフォリアの姉である。現在はグラン・カオス帝国の女帝であり、同帝国で初めて即位した女性である。', 19, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b218413-2g3qJI1IYrkx.png', NULL, NULL, '金元寿子', NULL, 218413, 'SUPPORTING', 54) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017995', 'AN1768', 'マルクス', '種族：ハーフエルフ　かつてエルフリーデン王国の首相を務めていたが、ハクヤ・クオンミンにその座を譲り、現在は元統治者であるアルベルト・エルフリーデンとエリシャ・エルフリーデンの侍従長を務めている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b237304-FpF8kUImT9Dp.png', NULL, NULL, '青山穣', NULL, 237304, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017996', 'AN1768', 'アイーシャ・ウドガルド', '「神に守られた森」のダークエルフ族長の娘。武術大会で優勝した後、才能ある者たちの集いにおいて発見された5人のうちの1人。 ソーマがダークエルフたちに森を救う方法を教えた後、彼の護衛を務めるようになり、次第に彼に深く恋に落ちる。非常に意欲的で忠実なため、よく動物に例えられる。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/n133334-PKS9Bt9CeQpL.jpg', NULL, NULL, '長谷川育美', NULL, 133334, 'SUPPORTING', 281) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017997', 'AN1768', 'アルベルト・エルフリーデン', 'アルバートはエルフリーデンの元国王であり、そのため最高機密に関する知識を多少持っている。アルバートは親切で思いやりのある人物だが、決断力に欠け、指導者としては弱さが見られる。彼は家族を愛し、国を深く思いやっているが、その不適切な指導と優柔不断さにより、エルフリーデン王国は衰退してしまった。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b237299-02DE0veVrZML.png', NULL, NULL, '麦人', NULL, 237299, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017998', 'AN1768', 'ハクヤ・クオンミン', 'ハクヤ・クオンミンは、『現実主義英雄の王国再建記』シリーズに繰り返し登場するキャラクターである。現在はフレイドニア王国の首相を務めている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n133335-8UW3OkykJmFL.jpg', NULL, NULL, '興津和幸', NULL, 133335, 'SUPPORTING', 90) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH017999', 'AN1768', 'ユノ', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b262756-nNli1Yl0VOGe.png', NULL, NULL, '朝井彩加', NULL, 262756, 'SUPPORTING', 28) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018000', 'AN1768', 'ユリウス・アミドニア', 'ユリウス・アミドニア（後にジュリアス・ラスタニアと改名）は、併合前のアミドニアの追放された非公式な統治者である。彼は故ガイウス・アミドニアの息子であり、ロロア・アミドニアの兄にあたる。 その後、彼はラスタニア王家に婿入りし、その姓を名乗るようになった。ユリウスは虚栄心が強く、自己中心的な人物であり、偉大さと征服への野望を抱いていた。 父ほど短気ではなかったものの、同じ理想を共有していた。しかし、国を統治する能力は著しく欠けており、彼は……', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b237297-cfQlKohfeKb7.png', NULL, NULL, '野島健児', NULL, 237297, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018001', 'AN1768', 'ポンチョ・パナコッタ', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b214656-14nUxWYEYR2v.png', NULL, NULL, '水中雅章', NULL, 214656, 'SUPPORTING', 32) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018002', 'AN1768', 'セリィナ', 'セリィナは、現在パルナム城の首席メイドであり、リシアの専属付き人である。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b247727-ybKiqqkAT8Cz.png', NULL, NULL, '貫井柚佳', NULL, 247727, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018003', 'AN1768', 'ボーダン・ウドガルド', '「神に守られた森」のダークエルフの首領であり、ロブソール・ウドガルドの兄弟、そしてアイーシャ・ウドガルドの父である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b246570-AO3gofG9aYwE.png', NULL, NULL, '江越彬紀', NULL, 246570, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018004', 'AN1768', 'カルラ・バルガス', '彼女はカストール・バルガスの娘であり、エクセル・ウォルターの孫娘、そしてリーシア・エルフリーデンの友人である。かつてはバルガス公国空軍の副司令官を務めていたが、現在は相馬一也とリーシアの奴隷兼メイドとなっている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b214655-u0U3jZHFYGLC.png', NULL, NULL, '愛美', NULL, 214655, 'SUPPORTING', 89) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018005', 'AN1768', 'カストール・バルガス', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b214658-opBktRdm17a4.png', NULL, NULL, '福山潤', NULL, 214658, 'SUPPORTING', 15) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018006', 'AN1768', 'ゲオルグ・カーマイン', '種族：ライオン・ビーストマン　ゲオルグ・カーマインは、『現実主義勇者の王国再建記』シリーズの登場人物である。一週間戦争以前は、エルフリーデンの陸軍司令官兼公爵を務めていた。  （出典：『現実主義勇者の王国再建記』Wiki）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n133341-NmGIzUwoTgiv.png', NULL, NULL, '楠大典', NULL, 133341, 'SUPPORTING', 29) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018007', 'AN1768', 'ロロア・アミドニア', '種族：人間　ロロア・アミドニアは、『現実主義勇者の王国再建記』シリーズの女性主人公の一人である。ガイウス・アミドニアの娘であり、ユリウス・アミドニアの妹である。  （出典：『現実主義英雄の王国再建記』Wiki）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/n133342-pJC7sUq7cmn3.png', NULL, NULL, '市道真央', NULL, 133342, 'SUPPORTING', 170) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018008', 'AN1768', 'ヒルデ・ノーグ,', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b263883-br6wkkodW670.png', NULL, NULL, '中原麻衣', NULL, 263883, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018009', 'AN1768', 'ルドウィン・アークス', 'ルドウィンは、聡明でカリスマ性あふれる貴族である。傑出した騎士として、カズヤが彼と初めて出会った当時、王室近衛隊の隊長を務めていた。エルフリーデンの貴族でありながら、幼なじみを経済的に支えるため、質素な生活を送っている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b237301-FhZAWvyJNA9G.png', NULL, NULL, '古川慎', NULL, 237301, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018010', 'AN1769', '猫柳ミロ', 'パンダクリニックを経営する、卓越した医療技術を持つ若き医師。淡い青色の髪を持ち、左目の周りにパンダのようなあざがあるため、「パンダ」と呼ばれている。', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b211162-bB9k8QbeJa56.png', NULL, NULL, '花江夏樹', 168, 211162, 'MAIN', 314) ON CONFLICT DO NOTHING;
