INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018042', 'AN1771', '龍造寺朱音', '彼女はレイトの担当看護師だ。茜は背の高い女性（水原怜人よりも背が高い）で、朱色の髪をポニーテールに結んでおり、毛先にはカールがかけられ、前髪は右側に垂れている。 彼女は垂れ目のような青い瞳を持ち、砂時計のような体型をしており、筋肉質ではあるものの、最も際立っているのはその非常に大きな胸だ。茜は性的な自信に満ちていて気さくで、裸体を披露することや、さらには性的な行為に及ぶことに対しても、何の躊躇いもないようだ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b169793-3QAFrAEwbaUZ.png', '3月25日', NULL, '大地葉', NULL, 169793, 'SUPPORTING', 122) ON CONFLICT DO NOTHING;
