INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018053', 'AN1771', 'クロエ・マンスフィールド', 'クロエ・マンスフィールド氏は、UW世界本部の元特使であり、UW平和維持活動局の局長を務めている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b169808-l1KkC8iuGOi9.png', NULL, NULL, '大久保瑠美', NULL, 169808, 'SUPPORTING', 36) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018054', 'AN1771', '片桐麗亜', '片桐麗亜は、水原怜人の献身的な秘書である。麗亜は男性に対して憎悪を抱いている。 この態度が、水原怜人への不当な扱いに繋がっている。男性への憎悪ゆえに、リアは女性、とりわけ周防美来だけを愛してきた。リアは美来と知り合ってから長い間、彼女に対して親密な感情を抱くようになり、常に美来に触れたり、その美しさを褒めたりしたくなる衝動に駆られている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b169803-ICd0O3jBlVUF.png', '7月12日', NULL, '渡部恵子', NULL, 169803, 'SUPPORTING', 42) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018055', 'AN1771', '黒田・レイン・ちふゆ', '黒田・レイン・ちふゆは、ケイモン・ウェスト私立高校の天才的な3年生で、黒田マリアの妹である。', 18, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b169800-MtDFtYpKAHI8.png', '1月30日', NULL, '高森奈津美', NULL, 169800, 'SUPPORTING', 27) ON CONFLICT DO NOTHING;
