INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018057', 'AN1772', '明日小路', '1～3組、生徒番号1番。ある事情からセーラー服に強い憧れを抱いている少女。明るく率直な性格で、学校生活をとても楽しみにしている。スポーツが得意だ。（出典：公式サイト、翻訳）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b159265-LiHxRweeEyGb.jpg', '4月4日', NULL, '村上まなつ', NULL, 159265, 'MAIN', 816) ON CONFLICT DO NOTHING;
