INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018077', 'AN1772', '大熊実', '1～3組、生徒番号3番。理にかなった物事や現象が好き。特に生き物には目がない。ロバイ私立学園に入学して以来、小道に興味を抱いている。（出典：公式サイト、翻訳）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b252587-U4vBTcXLLmjX.png', '11月24日', NULL, '小原好美', NULL, 252587, 'SUPPORTING', 30) ON CONFLICT DO NOTHING;
