INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018082', 'AN1772', '千嵐部長', '3年生。演劇部の部長。小柄でほっそりした体型の少女で、1年生の頃はトップの成績を収めていたが、現在は慢性的な遅刻常習者となっており、その奇妙な振る舞いから「変人」と呼ばれている。 小道と友乃が部に入部するまでは、演劇部の部員は彼女一人だけで、部活動として自作の動画を動画サイトにアップロードして公開していた。（出典：ウィキペディア、翻訳）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b262599-0tIFRiR3FC7z.png', NULL, NULL, '種﨑敦美', NULL, 262599, 'SUPPORTING', 22) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018083', 'AN1772', '谷川景', '1～3組、生徒番号9番。名門・翔明学園の入学試験に合格した優秀な生徒だ。小道と出会ったことをきっかけに、自撮りに興味を持つようになった。（出典：公式サイト、翻訳）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b252579-lo77gpjtj6nk.png', '6月27日', NULL, '関根明良', NULL, 252579, 'SUPPORTING', 47) ON CONFLICT DO NOTHING;
