INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018087', 'AN1773', 'ソン・リャンハ', '彼は、香港のトライアドを独力で壊滅させたことで、少なくとも20の組織から指名手配されている殺し屋だ。シャトーと出会って以来、彼女と過ごす時間を代償に、彼女を尾行し、その情報を売りさばいている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b157016-BDgdKQQlEdt5.jpg', NULL, NULL, '下野紘', NULL, 157016, 'MAIN', 409) ON CONFLICT DO NOTHING;
