INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018117', 'AN1775', 'ケーナ', 'レベル：1100　種族：ハイエルフ　称号：スキルマスターNo.3　生命維持装置が機能不全に陥ったことをきっかけに、VR世界「リーデール」へと転落した。入院生活以来、ほとんどの時間をVRMMORPGで過ごしてきた。病院での生活経験から、子供や高齢者に対して自然と優しく接する。  ケーナは「フォスターシステム」（NPC補償プログラム）から計3体のサブキャラクターを登録しており、そのうち2体はゲーム内で購入したものであった。当時、彼女は3体すべてを自分の子供として扱うことに決めていた。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b179625-LDDVKhnWMIWN.png', NULL, NULL, '幸村恵理', NULL, 179625, 'MAIN', 303) ON CONFLICT DO NOTHING;
