INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018142', 'AN1775', 'ミミリイ', 'リーデールでケーナが生まれ変わった村の近くにある水中の鉱脈で、奇妙な魔法のポータルに閉じ込められてしまった人魚。ケーナは彼女を救い出し、村で住む場所を提供することになった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b273560-Su99VWMY0btQ.png', NULL, NULL, '二ノ宮ゆい', NULL, 273560, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
