INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018144', 'AN1776', '高木', '名前の明かされていない学校に通う中学生。1-2組の教室の後ろの席で、西片の隣に座っている。学業も運動も得意だが、自分の唯一の弱点は脇の下がくすぐったいことと、西片をからかうのをやめられないことだと自認している。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/120800-fZe52KrIKqv6.jpg', NULL, NULL, '高橋李依', 150, 120800, 'MAIN', 3409) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018145', 'AN1776', '西片', '西片は中学1年2組の生徒だ。教室の後ろの方で、高木の隣に座っている。ブラックコーヒーのような苦いものは苦手で、こっそり『100％片思い』という恋愛小説を読んだり見たりしており、とても臆病だ。学力は平均的だ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/120799-175LQCsgpSJk.jpg', NULL, 'O', '梶裕貴', 150, 120799, 'MAIN', 885) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018146', 'AN1776', '北条', '北条は、高木や西片と同じクラスに在籍する生徒だ。彼女はクラスメートたちとは対照的に、大人びた性格をしている。誰かが子供っぽい振る舞いをしているのを見るたびに、彼女は「なんて子供っぽいんだ」と口にする。そんな大人びた性格にもかかわらず、浜口のドジなところには、つい愛おしさを感じてしまうことが多い。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b163024-VqFXLeKj8fEq.png', NULL, NULL, '悠木碧', NULL, 163024, 'SUPPORTING', 63) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018147', 'AN1776', '田辺先生', '田辺先生は1年2組の担任で、そのクラスには高木、西片、真野、中井、サナエ、ミナ、ユカリが在籍しています。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b128609-YITeO7eJEarZ.jpg', NULL, NULL, '田所陽向', NULL, 128609, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018148', 'AN1776', '木村', '西片の友人', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b128610-guKKI3hp3vB3.jpg', NULL, NULL, '落合福嗣', NULL, 128610, 'SUPPORTING', 53) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018149', 'AN1776', 'ダンディ', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b260887-tp6V5f9j9kJO.png', NULL, NULL, '玄田哲章', NULL, 260887, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018150', 'AN1776', '浜口', '浜口は西片の友人の一人だ。彼は北条に興味を持っているようだ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b163023-Wz79KMySWvya.png', NULL, NULL, '内山昂輝', NULL, 163023, 'SUPPORTING', 16) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018151', 'AN1776', '日比野ミナ', 'ミナは元気で陽気な女の子で、グループの中ではいつも明るい存在です。彼女はいつも遊び好きで、よく騒いでいます。また、ミナは走るのが苦手で、すぐに疲れてしまいます。例えば、学校のマラソンにワクワクしていたのに、スタートしてすぐに疲れてしまったこともあります。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b128608-j1uRTq46p5XJ.jpg', NULL, NULL, '小原好美', NULL, 128608, 'SUPPORTING', 216) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018152', 'AN1776', '西片ちー', '西片と（旧姓）高木の娘。ピーマンは大嫌いだが、お父さんをくすぐるのが大好き。物語の冒頭では、幼稚園に通っている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b124599-Xl7uFi8rQP7W.png', NULL, NULL, '宮本侑芽', NULL, 124599, 'SUPPORTING', 119) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018153', 'AN1776', '中井', '西片と高木の同級生の一人で、真野の彼氏。   中井は、とても穏やかで親しみやすく、のんびりとした性格で、真野と過ごすよりも男友達と過ごすことを好んでいる。彼は、真野のことを今でも深く気にかけているものの、彼女と過ごすのは難しいと語っている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b128607-Yp2bNIh9Wfl4.jpg', NULL, NULL, '内田雄馬', NULL, 128607, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018154', 'AN1776', '高尾', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/n128612-xagYExD10Kpd.jpg', NULL, NULL, '岡本信彦', NULL, 128612, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018155', 'AN1776', '月本先生', '月本サナエの姉。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b268304-6RkumS7HMmXV.png', NULL, NULL, '菊池紗矢香', NULL, 268304, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018156', 'AN1776', '鷹川すみれ', '鷹川すみれは、高木と西片の同級生の一人だ。彼女は高木の親友である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b189581-F16jV4QsDI6S.png', NULL, NULL, '朝日奈丸佳', NULL, 189581, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018157', 'AN1776', '真野', '真野は西片と高木の同級生であり、中井とは公にされていない関係にある。真野は一般的に人見知りが激しく、不安がり、特に中井に話しかけようとする時は照れくさそうな様子を見せる。また、他人に邪魔されたりしつこく絡まれたりするとすぐに苛立ちを露わにするなど、顕著な怒りの問題を抱えている。 中井との関係については、彼と接しようとする際、しばしば自分の行動を疑ってしまう。彼女は中井にもっとこの関係に関心を持ってほしいと願っているが、愛は', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b128606-mXAI7pwWuCE7.png', NULL, NULL, '小岩井ことり', NULL, 128606, 'SUPPORTING', 48) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018158', 'AN1776', 'キュン子', 'キュン子は『100％片思い』のヒロインです。これは『からかい上手な高木さん』の世界観を共有する少女向けアニメ・漫画シリーズです。西片のお気に入りのシリーズであり、密かな楽しみでもあります。   続編の漫画『からかい上手（元）の高木さん』では、このシリーズが『300％片思い』として続くことが示唆されている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b227379-4s2X5bVgIl7B.png', NULL, NULL, '高橋李依', NULL, 227379, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018159', 'AN1776', '天川ユカリ', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b128614-4E0vL5Z3Tg4z.jpg', NULL, NULL, '市道真央', NULL, 128614, 'SUPPORTING', 62) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018160', 'AN1776', 'イケ男', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b227380-eqWOJNKEkhBF.png', NULL, NULL, '梶裕貴', NULL, 227380, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018161', 'AN1776', '月本サナエ', '月本サナエは、西片や高木と同じクラスの同級生であり、ミナやユカリの親友の一人である。サナエは、非常に率直でありながら、思いやりがあり、頭の良い少女だ。いつも無表情で淡々とした態度で知られるサナエは、一人でいることを好む。 運動神経が非常に優れており、特に走ることや水泳が得意だ。普段は感情を表に出さない外見とは裏腹に、サナエは親友のミナとユカリを深く大切に思っている。3人はいつも一緒にいる姿が見られる。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b128611-lehh3l21kXm1.jpg', NULL, NULL, '小倉唯', NULL, 128611, 'SUPPORTING', 89) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018162', 'AN1777', 'キャル', '種族：ビースト　キャルは、よく友達の愚痴をこぼすものの、結局はいつもついていくため、「ツンデレ」と表現できる。 口が悪く、よくイライラしたり動揺したりする。外見上は強気で厳しい態度をとろうとするが、実はとても心優しい。ギルド「ゴメット・エディフィス」のメンバーである。また、猫と遊ぶのが好きだ。', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b160246-g44lB2ZlqdiT.png', '9月2日', 'A', '立花理香', 152, 160246, 'MAIN', 1321) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018163', 'AN1777', 'ペコリーヌ', '種族：人間　旺盛な食欲と尽きることのないエネルギーを持つペコリーヌは、食事から食事へと、一見のんきな生活を送っている。彼女は常に楽観的で、相手がどう応えてこようとも、積極的に友達を作ろうとする。 また、ペコリーヌは珍しい珍味を求めて旅をするのも大好きで、調理された食材を一切無駄にしないことで、あらゆる命に敬意を払っている。彼女はギルド「グルメ・エディフィス」のギルドマスターである。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b160247-MeZX1W0Vgvo1.png', '3月31日', 'O', '市道真央', 156, 160247, 'MAIN', 827) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018164', 'AN1777', 'コッコロ', '種族：エルフ　ギルド「ゴメット・エディフィス」のメンバー。', 11, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b160248-Q37H6ZX30iwj.png', '5月11日', 'B', '伊藤美来', 140, 160248, 'MAIN', 894) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018165', 'AN1777', 'ユウキ', '善意はあるものの、しばしば状況が把握できていない記憶喪失者。', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b160249-CXTSduncrRLJ.png', NULL, NULL, '阿部敦', NULL, 160249, 'MAIN', 222) ON CONFLICT DO NOTHING;
