INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018167', 'AN1777', 'ナナカ', '種族：フィエンド', 18, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b169117-CFrLfR9JyWWV.png', '8月21日', 'O', '佳村はるか', 166, 169117, 'SUPPORTING', 21) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018168', 'AN1777', 'シオリ', '種族：ビースト　シオリは穏やかで物静かな少女だ。彼女は体が弱く、病気がちな体質だが、「ザ・ファーム」の自然豊かな環境が体調の回復に役立っている。彼女は柏崎ハツネの妹であり、ギルド「エリザベス・パーク」のメンバーでもある。読書や散歩も好んでいる。', 14, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b169700-U64McSV8GLfA.png', '11月3日', NULL, '小清水亜美', 153, 169700, 'SUPPORTING', 67) ON CONFLICT DO NOTHING;
