INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018174', 'AN1777', 'エリコ', '種族：フィエンド　エリコはユキに夢中な執着心の強い少女で、彼の好意を得るためにしばしばとんでもない手段を講じる。彼女は「ヤンデレ」のような、極端で manipulative な一面を見せている。 ごく一部の例外を除き、彼女は周囲の人々を軽んじがちだ。しかし、子供たちに対しては、優しく、まるで母親のような一面を見せることもある。彼女はギルド「トワイライト・キャラバン」のメンバーである。実験や裁縫、料理が好きだ。', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b167275-kXD9FjzZw0XE.png', '7月30日', 'B', '橋本ちなみ', 154, 167275, 'SUPPORTING', 217) ON CONFLICT DO NOTHING;
