INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018183', 'AN1777', 'アオイ', '種族：エルフ　アオイは、友達を作るのが苦手なとても内気な女の子ですが、「試練やハードル」を乗り越えようと努力する決意を持っています。 ある日、彼女はユキと出会い、二人で新しい友達を作るために「BB旅団」を結成する。彼女はギルド「フォレスティエ」のメンバーであり、友達を作るための心の準備をするのが好きだ。  （出典：プリンセスコネクト！Re:Dive Wiki）', 13, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b169506-IH5fN0djOAix.png', '6月6日', NULL, '花澤香菜', 158, 169506, 'SUPPORTING', 76) ON CONFLICT DO NOTHING;
