INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018191', 'AN1777', 'ハツネ', '種族：エルフ（山羊座）　ハツネは、テレキネシスやテレポーテーションといった超能力を持つ少女だ。彼女は現実世界ではこれらの能力を隠すことを選んでいる。しかし、能力を使おうとすると反動で眠気を感じ、よく（時には思いがけない場所で）眠ってしまう。 ユキがそばにいるときは、それほど頻繁に眠ってしまうことはないようだ。  しかし、目が覚めているときは元気いっぱいで、話し方も明るく弾んでいる。会話の中に「キラ～ン」という言葉をよく挟む。また、彼女は', 17, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b169507-AWvtXTaqw7MB.png', '12月24日', NULL, '大橋彩香', 156, 169507, 'SUPPORTING', 87) ON CONFLICT DO NOTHING;
