INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018223', 'AN1777', 'ミヤコ', '種族：フィエンド　ミヤコはプリンに対する食欲が尽きることがなく、しばしばそれを最優先事項にしている。プリンを取り上げられたり、誰かに自分のプリンを食べられたりすると、激しく怒る。 ごく稀にプリンのことが頭から離れている時は、ミヤコはかなり子供っぽく振る舞い、時折他人にいたずらをすることもある。彼女はギルド「ディアボロス」のメンバーである。  （出典：プリンセスコネクト！Re:Dive Wiki）', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b173753-TGULB8sbIGjk.png', '1月23日', NULL, '雨宮天', NULL, 173753, 'SUPPORTING', 63) ON CONFLICT DO NOTHING;
