INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018228', 'AN1778', '咲森鑑', 'ミラ、あるいは榊森カガミは、VRMMORPG『アーク・アース・オンライン』のプレイヤーであり、召喚魔法の分野における第一人者である。彼のキャラクター「ダンブルフ・ガナドール」は、魔法の頂点に立つエキスパートクラスのプレイヤーの一人と見なされている。 「ヴァニティケース」という課金アイテムの使用に多大な労力を費やした結果、彼はうっかり自分のキャラクターを小さな女の子に変えてしまった。  これは、ちょうど『アーク・アース・オンライン』が現実となった「セカンドワールド」へと彼が引き込まれた直後の出来事だった。その結果、彼は……', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b175253-4deuZrCFhq57.png', NULL, NULL, '大森日雅', NULL, 175253, 'MAIN', 189) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018229', 'AN1778', 'タクト', '冒険者の両親を持つ少年で、ミラと共にダンジョン攻略の任務に加わる。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b228906-LU7skPpQUE0I.png', NULL, NULL, '井澤佳の実 ', NULL, 228906, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018230', 'AN1778', 'メイリン', 'メイリンは、ミラと同様に『アーク・アース・オンライン』の世界へと移り住んだ「九賢人」の一人である。彼女は「道教の塔」の賢人である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b228898-eZTRuS3WG1Xx.png', NULL, NULL, '小澤亜李', NULL, 228898, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018231', 'AN1778', 'ソロモン', 'アルキテ王国の王であり、ダンブルフと同様、彼が絶大な信頼を寄せるもう一人のプレイヤーキャラクターである。臣民の前では威厳ある指導者として振る舞うが、実のところ非常に親しみやすい人物であり、王国を大切に思い、普段は地政学的な紛争の処理やモンスターへの対処に時間を費やしている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b228895-TY2h7c4f7wUV.png', NULL, NULL, '村瀬歩', NULL, 228895, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018232', 'AN1778', 'マリアナ', 'ミラの補佐を務める、妖精族の少女。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b228901-xal0ZqvpgY6h.png', NULL, NULL, '堀江由衣', NULL, 228901, 'SUPPORTING', 37) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018233', 'AN1778', 'ガレット', 'アルキテ王国の戦車部隊副司令官。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b228905-hYxVK8i9cTWa.png', NULL, NULL, '寺島惇太', NULL, 228905, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018234', 'AN1778', 'ルミナリア', 'アルキテの「九賢者」の一人であり、ダンバルフやソロモンとは古くからの友人であるプレイヤーキャラクターでもある。彼女は「災厄のルミナリア」という異名を持つ超強力な魔術師だが、ミラのそばにいるときはかなり気さくで、親しげな態度を見せる。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b228896-jclDt5Flf5hE.png', NULL, NULL, '日向未南', NULL, 228896, 'SUPPORTING', 26) ON CONFLICT DO NOTHING;
