INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018250', 'AN1779', '武蔵', '武蔵は、漫画『オリエント』の主要な主人公の一人である。彼は、小次郎やツグミと共に、史上最高の武士となるべく旅に出る。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130500-wUKWHjaw4bpT.png', '4月27日', 'O', '内田雄馬', NULL, 130500, 'MAIN', 139) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018251', 'AN1779', '鐘巻小次郎', '鐘巻小次郎は、漫画『オリエント』の第二の主人公である。彼は武蔵の幼なじみであり、鐘巻武士の隊長でもある。彼と武蔵の目標は、史上最強の武士団を結成することである。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130501-Lt6Ve49EnDGN.png', '12月29日', 'A', '斉藤壮馬', NULL, 130501, 'MAIN', 78) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018252', 'AN1779', '服部つぐみ', 'ツグミは、長い緑色の髪を二つのおさげに結んだ美しい少女だ。そのおさげには鈴がついている。普段の服装は、緑とピンクの着物に、それに合わせたボツを合わせている。武器は腕に装着している。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130940-Rb6uE43akdRA.png', '11月17日', 'A', '高橋李依', NULL, 130940, 'MAIN', 104) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018253', 'AN1779', '山本春雷', '山本春雷は、武田武士の一員であり、その「緑の剣特別隊」の副隊長を務めている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b259238-LqzO2LoK7RgV.png', NULL, NULL, '大西沙織', NULL, 259238, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
