INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018256', 'AN1779', '上杉竜臣', '上杉竜臣は、「火の元」の五大将軍の一人であり、上杉武士の隊長である。また、緑の鬼神・八岐大蛇との戦いにおいては、上杉連合を率いている。', 29, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b201286-mIpvhBIL6qAb.png', '1月17日', 'AB', '前野智昭', NULL, 201286, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
