INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018265', 'AN1779', '尼子勝巳', '天草武士のメンバーであり、当主の息子である。上杉連合の一員でもあり、武蔵と同じ小隊に配属されていた。', 16, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b268560-l2lboIdDupds.jpg', '8月10日', 'A', '梶原岳人', NULL, 268560, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018266', 'AN1779', '横道光', '天草武士の若き一員。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b290772-lvoCDQ2p51Fj.jpg', NULL, NULL, '坂田将吾', NULL, 290772, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018267', 'AN1779', '小雨田英雄', '彼はコサメダ武士の隊長である。一見、穏やかで優しい人物に見えるが、一度苛立つと本性が現れ、残酷で人を操る人物となる。 彼は優越感に浸っており、誰かが規律を破ったり、自分に異議を唱えたりすることを嫌う。彼は部下たちを徹底的に貶め、彼らが自分で考えることさえできなくなるほどに追い込む。また、城から人が出ていくことについても非常に頑なである。ツグに敗れた後、彼は支配欲を失い、世捨て人のように引きこもってしまった。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b215088-kRO6J6gsAx0G.png', NULL, NULL, '羽多野渉', NULL, 215088, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018268', 'AN1779', '直江兼竜', '職業：会計係　所属：上杉武士　上杉武士を統括する上級家臣である。「人・物・金をそれぞれの所定の場所に整える」ことを好み、普段は大量の事務処理に追われている。 小柄で、一見地味な風貌からは武士とは思えないが、部下からは慕われ、主君の達臣からも厚い信頼を寄せられている。実は、妻に7回も離婚されている。', 26, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b270360-cKMnTLtDMwcT.png', '12月2日', NULL, '花江夏樹', 150, 270360, 'SUPPORTING', 34) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018269', 'AN1779', '五月川早苗', '天草武士の若き一員。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b290803-k12xxTCD8aXa.png', NULL, NULL, '白砂沙帆', 165, 290803, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018270', 'AN1779', '真田青志', '真田青志は武田武士の一員であり、第一中隊の「青の剣」である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b259237-JiiFXIMsyTS8.png', NULL, NULL, '石谷春貴', NULL, 259237, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018271', 'AN1779', '長舩ミツル', '長舩ミツルは武士であり、龍造寺武士団の刀鍛冶長でもある。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b259316-kFPNGMw6QRwV.png', NULL, NULL, '井上麻里奈', NULL, 259316, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018272', 'AN1779', '犬塚一眞佐', '謎めいた武士であり、「オブシディアン・エイト」の一員。また、同組織のリーダーでもある。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b290820-HhCnsKFM3EaX.jpg', NULL, NULL, '森川智之', NULL, 290820, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018273', 'AN1780', '海凪小春', '彼女の父親とひよりの母親が再婚したことで、彼女はひよりの義理の姉になった。彼女は幼い頃、交通事故で母親と弟を亡くした。小春はひよりより2ヶ月早く生まれたため、姉にあたる（彼女はそれを「*すごく*」よく口にする）。 子供の頃は喘息を患っていたため、あまり外に出られず、頻繁に入院していた。そのため、家で過ごす時間が多く、外で遊ぶことについてはあまり知らなかった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b200959-BiI8OiuSETnf.png', '11月15日', 'B', '日岡なつみ', 155, 200959, 'MAIN', 98) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018274', 'AN1780', '海凪ひより', '彼女は父親からフライフィッシングを教わり、今では近くの海で釣りを楽しんでいる。子供の頃は非常に内気で、ほとんどの時間をコイの後ろに隠れて過ごしていた。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b200960-LX7duE9rhNgW.png', '1月4日', 'O', '久住琳', 154, 200960, 'MAIN', 112) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018275', 'AN1780', '吉永恋', 'ひよりの幼なじみで同級生。家族が経営するフライフィッシングショップで働いている。 父親は釣りへの情熱から、その魚の種類を表す漢字を使って「コイ」と名付けたいと考えていたが、母親は「愛」を表す漢字を使うことに決めた……発音は同じだが。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b202956-lF7ofdyWHzZi.png', '6月30日', 'A', '嶺内ともみ', 145, 202956, 'MAIN', 154) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018276', 'AN1780', '海凪ひなた', 'ひよりの母親。小春の父親である一世と再婚する。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b260888-Q4iSNB9edwVQ.png', NULL, NULL, '柚木涼香', NULL, 260888, 'SUPPORTING', 62) ON CONFLICT DO NOTHING;
