INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018278', 'AN1780', '海凪一誠', '小春のお父さん。彼は、ひよりのお母さんであるひなたと再婚した。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b260889-hb0wj32vr9o2.png', NULL, NULL, '川田紳司', NULL, 260889, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
