INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018286', 'AN1780', '海凪裕子', '一世の亡き最初の妻であり、小春の実母。息子と共に交通事故で亡くなった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b265572-QC6h3Z8HdnIr.png', NULL, NULL, '下屋則子', NULL, 265572, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
