INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018288', 'AN1780', '宮野楓', 'カエデは、一花と高校時代の旧友だ。彼女はレストラン兼バー「ベースフィールド」で働いており、趣味は狩りだ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b263942-8fudkpDUUKT3.jpg', NULL, NULL, '日笠陽子', NULL, 263942, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
