INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018292', 'AN1781', '白鳥尊', '白鳥尊は、サンライト・ビバレッジの社内バドミントンチームの最新メンバーであると同時に、同社で最も新しく、かつ最年少の営業担当者でもある。彼は、自身と宮澄建で構成されるダブルスペアの戦術家であり、フロントプレイヤーを務めている。', 19, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b252890-bFulRyE5v8z5.jpg', '5月11日', 'AB', '榎木淳弥', NULL, 252890, 'MAIN', 87) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018293', 'AN1781', '佐伯蒼汰', '酒井ソータは、サンライト・ビバレッジの社員であり、バドミントン選手でもある。ソータはシングルス選手で、普段は極めて冷静で落ち着きのある人物だ。彼はトヤの兄である。', 23, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b252891-gYFZmZxs9A90.jpg', '9月27日', 'B', '石川界人', NULL, 252891, 'MAIN', 17) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018294', 'AN1781', '宮澄建', '宮澄建はサンライト・ビバレッジの社員である。営業部に所属しており、同社のバドミントン部の主将も務めている。白鳥尊のダブルスのパートナーとして、通常はバックコートからパワープレーやディフェンスを担当している。', 32, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b252894-b5b86MbzAVhd.jpg', '3月29日', 'O', '三木眞一郎', NULL, 252894, 'MAIN', 160) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018295', 'AN1781', '佐伯橙也', '佐伯橙也は、サンライト・ビバレッジの社員であり、バドミントン選手でもある。橙也はサンライト・ビバレッジの企画部に所属し、社内バドミントンチームでダブルスをプレーしている。 彼は竹田浩輝とダブルスを組んでおり、ソータの弟である。高校時代には白鳥尊とチームメイトだったため、ミコトがチームに加入した当初から、ミコトのプレースタイルや先読み能力をよく理解していた。', 19, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b252892-7ak42IchRX1y.jpg', '4月3日', 'B', '逢坂良太', NULL, 252892, 'MAIN', 17) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018296', 'AN1781', '竹田浩輝', '竹田浩輝は、サンライト・ビバレッジの社員であり、バドミントン選手でもある。  浩輝は、サンライト・ビバレッジの営業部で宮澄建や白鳥尊と共に働き、彼らとバドミントンも楽しんでいる。ダブルスのパートナーは佐伯橙也だ。浩輝はコミュニケーション能力に長け、おちゃめな性格だが、本番の試合では緊張のあまり本来の力を発揮できないことがよくある。', 27, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b252893-SQ5WlVbXduZZ.jpg', '7月19日', 'A', '柿原徹也', NULL, 252893, 'MAIN', 14) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018297', 'AN1781', '美空綾人', '美空綾人は、ユニシックスに所属するバドミントン選手です。綾人は昨年の全国高校バドミントン選手権大会で個人優勝を果たし、わずか17歳でユニシックスに入団しました。彼はとても感情豊かで、元気いっぱいです。', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b263429-SQ0GFjagVitW.jpg', NULL, NULL, '村瀬歩', NULL, 263429, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018298', 'AN1781', '矢田鏡子', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b269518-AyXhaABUL8L7.jpg', NULL, NULL, '花守ゆみり', NULL, 269518, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018299', 'AN1781', '間柴勇歩', '間柴勇歩は、トマリ・トランスポートに所属するバドミントン選手だ。勇歩はトマリ・トランスポートでシングルスを担当している。彼は熱血で、度胸と気概、そして何よりも筋肉に溢れている。', 23, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b264662-hBlEtzbJlNQQ.jpg', '11月25日', 'O', '土岐隼一', NULL, 264662, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018300', 'AN1781', '仲邑周平', '仲邑周平は、三ツ星銀行に所属するバドミントン選手です。周平は、三ツ星銀行で瀧本千空とペアを組んでダブルスをプレーしています。', 24, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b270184-Co6vZnvD7E8M.jpg', '4月27日', 'A', '堀江瞬', NULL, 270184, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018301', 'AN1781', '立花梓馬', '立花梓馬は、トマリ運輸の社員であり、バドミントン選手でもある。  東はトマリ運輸でダブルスを担当しており、現在は外崎士龍とペアを組んでいる。中学・高校時代には白鳥尊とダブルスを組んでいたが、当時は「神童」と称される相手とペアを組むことに、多少の劣等感を抱いていた。', 19, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b264663-PZWtWdSJRgS0.jpg', '11月14日', NULL, '八代拓', NULL, 264663, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018302', 'AN1781', '伊吹泉太郎', '伊吹泉太郎は、三ツ星銀行に所属するバドミントン選手である。  泉太郎は三ツ星銀行のシングルス選手であり、現在、世界ランキング1位のシングルス選手である。', 29, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b270187-DQWSYJ2S1C5U.jpg', '1月21日', 'B', '置鮎龍太郎', NULL, 270187, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018303', 'AN1781', '外崎士龍', '外崎士龍は、トマリ・トランスポートに所属するバドミントン選手である。士龍は、トマリ・トランスポートで立花梓馬とペアを組んでダブルスをプレーしている。', 28, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b264664-FyAfIOnrPrO7.jpg', '10月31日', 'O', '濱野大輝', NULL, 264664, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018304', 'AN1781', '霧島琢磨', '霧島琢磨は、三ツ星銀行に所属するバドミントン選手である。琢磨は、出雲尚弘とペアを組んで三ツ星銀行のダブルス選手として活躍している。現在、彼は世界ランキング1位のダブルス選手である。弟の霧島隼人は、世界ランキング2位である。', 19, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b270186-YU3qhKUIFAhM.jpg', '8月22日', 'B', '内田雄馬', NULL, 270186, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018305', 'AN1781', '郷倉虎徹', '郷倉虎徹は、トマリ運輸に所属するバドミントン選手である。  虎徹は、猿橋佑慧とペアを組んで、トマリ・トランスポートのダブルス選手として活躍している。立花梓馬がチームに加入する前は、外崎士龍とペアを組んでいた。彼は非常に物静かで、彼が話すのを耳にすることはめったにない。', 28, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b264665-SiJLgqOJS2fD.jpg', '12月25日', 'O', '杉田智和', NULL, 264665, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018306', 'AN1781', '瀧本千空', '瀧本千空は、三ツ星銀行のバドミントン選手です。千空は、仲邑周平とペアを組んで、三ツ星銀行のダブルス選手として活躍しています。', 24, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b270185-nGAYJI0Bz2HP.jpg', '6月9日', 'A', '白井悠介', NULL, 270185, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018307', 'AN1781', '大野安臣', '大野安臣はサンライト・ビバレッジのゼネラルマネージャーであり、バドミントンのコーチも務めている。安臣はいつもサングラスをかけている。彼は気難しく頑固だが、侮れない存在だ。見た目以上に頭が良く、信頼されるコーチである。', 46, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b262588-9rmb1w0Bkiw7.jpg', '8月1日', 'B', '黒田崇矢', NULL, 262588, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018308', 'AN1781', '猿橋佑慧', '猿橋佑慧は、トマリ・トランスポートに所属するバドミントン選手です。佑慧は、トマリ・トランスポートで郷倉虎徹とペアを組んでダブルスをプレーしています。', 24, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b264666-beUV57eX6WlE.jpg', '7月25日', 'A', '岡本信彦', NULL, 264666, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018309', 'AN1781', '出雲尚弘', '出雲尚弘は、三ツ星銀行に所属するバドミントン選手である。尚弘は三ツ星銀行で、霧島琢磨とペアを組んでダブルスをプレーしている。三ツ星銀行に入団する前は、サンライト・ビバレッジに所属し、宮澄建とペアを組んでいた。', 27, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b270188-ZqQrrxhbc84E.jpg', '12月14日', 'B', '古川慎', NULL, 270188, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018310', 'AN1781', '荻野目大樹', '荻野目大樹は、ユニシックスに所属するバドミントン選手です。大樹はユニシックスでダブルスを担当しており、幼なじみの霧島隼人とペアを組んでいます。', 25, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b263427-IHjuuCJLgOKT.jpg', NULL, NULL, '小野友樹', NULL, 263427, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
