INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018312', 'AN1781', '徳井咲哉', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b284332-lWmFdRFsxeDZ.png', NULL, NULL, '蜂須賀智隆', NULL, 284332, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018313', 'AN1781', '霧島隼人', '霧島隼人はユニシックスに所属するバドミントン選手である。隼人はユニシックスでバドミントンをしている。 彼は幼なじみの荻野目大樹とペアを組んでいる。隼人は現在、弟の霧島琢磨に次ぐ世界ランキング2位のダブルス選手である。彼はバドミントンの実力だけでなく、その端正なルックスでも知られ、非常に人気がある。', 25, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b263428-8ySAsCAe6gmY.jpg', NULL, NULL, '福山潤', NULL, 263428, 'SUPPORTING', 16) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018314', 'AN1781', '碓山トヲル', '彼はサンライト・ビバレッジの社員である。  臼山は、サンライト・ビバレッジの品質保証部門に所属する社員である。彼は佐伯蒼汰の直属の上司であり、無謀な営業判断を下す宮澄建を頻繁に叱責しなければならない。彼は非常に真面目で厳しい人物だ。以前はバドミントンをしていたが、今はもうやっていない。', 29, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b266336-IRoN9cpMXz3F.jpg', '6月16日', 'A', '前野智昭', NULL, 266336, 'SUPPORTING', 18) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018315', 'AN1782', '蒼生シュウタ', '第24区にある「アオイ・ベーカリー」のオーナーの息子。とても運動神経が良く、毎日一生懸命働いている。かつては「ミスター24」として街を守っていたヒーローだったが、今は家業を手伝うためにパン作りに追われている。ランとコキは彼の幼なじみだ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b253386-fsmNqLELes7J.jpg', NULL, NULL, '榎木淳弥', NULL, 253386, 'MAIN', 38) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018316', 'AN1782', '翠堂コウキ', '第24区にある名門・スイド財閥の跡取り。蘭やシュタの幼なじみであり、あすみの兄でもある。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b253387-yMNhnSX5ZHSz.jpg', NULL, NULL, '石川界人', NULL, 253387, 'MAIN', 22) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018317', 'AN1782', '朱城ラン', '「RGB」のメンバーであり、DoRedのリーダー。ランは、自身のメッセージを広めるためにアート制作のライブ配信を行うグラフィティアーティスト兼インフルエンサーであると同時に、ハッカーでもある。彼はシュタとコキの幼なじみである。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b253388-MLh045gKDIuL.jpg', NULL, NULL, '内田雄馬', NULL, 253388, 'MAIN', 58) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018318', 'AN1782', '翠堂豪理', 'コキとアスマの父親。第24区の区長であり、著名な政治家である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b257183-Wduf1FjDBmZJ.png', NULL, NULL, '楠大典', NULL, 257183, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
