INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018323', 'AN1782', 'ゼロス', '第24区出身の、正体不明ながら世界的に有名なグラフィックアーティスト。幼い頃のランとクナイに多大な影響を与え、彼らの師とみなすことができる。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b270139-8RFD7OUbGcDA.jpg', NULL, NULL, '諏訪部順一', NULL, 270139, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
