INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018334', 'AN1783', 'リチャード', '激しい陣痛の末、リチャードはインターセックス（生殖器や性的な解剖学的構造が、女性や男性の典型的な定義には当てはまらない状態で生まれるさまざまな状態を指す総称）として生まれた。 リチャードは虹彩異色症を患っており、左目は黄色、右目は紫色をしている。リチャードの母親は彼を怪物と見なし、軽蔑していた。妻の憎悪に気づかない父親に、リチャードは愛されながら育てられた。リチャード自身は、見捨てられることを恐れ、苦しみに苛まれる子供だった。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b161180-LJamS7fwTi3X.png', '10月2日', NULL, '斎賀みつき', NULL, 161180, 'MAIN', 449) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018335', 'AN1783', 'ヘンリー6世', 'ヘンリー6世はランカスター家の当主である。戦争や殺戮を嫌う敬虔なキリスト教徒であり、羊飼いに憧れていた。ある時、森でリチャード3世と出会い、互いの正体を知らないまま惹かれ合うことになる。 ヘンリー6世はマーガレットと結婚しており、ランカスター家のエドワードの父である。ヘンリーは臆病者として最もよく知られている。しかし、この臆病さは誤解であり、彼は戦争を憎むため自ら軍を率いることを拒み、その結果、妻のマーガレットが彼に代わって軍を率いることになる。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b175115-PSz8hHalrzu0.png', NULL, NULL, '緑川光', NULL, 175115, 'MAIN', 157) ON CONFLICT DO NOTHING;
