INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018338', 'AN1783', 'ウォリック', '「キングメーカー」として知られ、当初はヨーク家、その後ランカスター家の強力な支持者であった。ネヴィル家出身で、イザベルとアンの父である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b175122-gS9L7CIzYT5f.png', NULL, NULL, '三上哲', NULL, 175122, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
