INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018347', 'AN1783', 'エリザベス', 'エドワード4世の妻。彼女は権力を手に入れ、夫の死の復讐を果たすためだけに彼と結婚した。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b175129-19gFYJALVlLp.png', NULL, NULL, '伊藤静', NULL, 175129, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
