INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018349', 'AN1783', 'マーガレット', 'ヘンリー6世の妻であり、ランカスターのエドワード王子の母。ランカスター家の出身であり、夫の王位を支える実力者であった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b175118-Q0sARh3OdW7r.png', NULL, NULL, '大原さやか', NULL, 175118, 'SUPPORTING', 10) ON CONFLICT DO NOTHING;
