INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018351', 'AN1783', 'ジェイムズ・ティレル', '左目に傷跡のある謎の殺人鬼。本名は誰にも知られておらず、記憶を失っているようだ。彼はリチャードを王として崇めている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b175121-UAxBuR0B4Oes.png', NULL, NULL, '緑川光', NULL, 175121, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
