INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018353', 'AN1783', 'バッキンガム', 'リチャードの盟友であり、後に恋人となる人物。リチャードの「キングメーカー」と見なされている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b175136-NigFmKHajZHQ.png', '9月4日', NULL, '杉山里穂', NULL, 175136, 'SUPPORTING', 84) ON CONFLICT DO NOTHING;
