INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018356', 'AN1784', '黒井津燈香', 'タイトルにもなっている黒一（クロイツ）さんは、邪悪な秘密結社「アガスティア」の怪物開発部の助手であり、アガスティアの敵と戦うための怪物を作り出そうとする一方で、上司たちからの過酷で、時に矛盾した要求の板挟みになる羽目になる。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b250980-mREEEGtdsSBU.png', NULL, NULL, '前田佳織里', 159, 250980, 'MAIN', 56) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018357', 'AN1784', 'ウルフ・ベート', 'アガスティアの最新モンスターの一体。狼男として開発が進められていたが、アカシックがベテに「もっと可愛く」と要求したため、完成直前に突然、狼少女へと姿を変えさせられた。ブレイダーとの最初の戦いを生き延びた後、ベテはモンスター開発部へ異動となり、そこでまた別の助手として働くことになった。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b250981-9MzqfgCF85Yj.png', NULL, NULL, '天野聡美', 151, 250981, 'MAIN', 69) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018358', 'AN1784', '不滅のカミュラ', '彼女は、魅惑的な容姿を持つアガスティアの幹部の一人である。体内に「究極のユニバーサル・セル」と呼ばれる細胞を宿していることから、「不死のカムリア」として知られている。 彼女は理想主義的な経営哲学を持ち、常に組織の利益を最優先する仕事人間として知られているが、私生活ではかなりの金銭マニアである。（出典：公式サイト、翻訳）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b259685-JeGU0POy9ySe.png', NULL, NULL, '竹達彩奈', 142, 259685, 'SUPPORTING', 22) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018359', 'AN1784', 'フェンリル', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b262353-TndFkplaCI3S.png', NULL, NULL, '緑川光', NULL, 262353, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
