INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018363', 'AN1784', '峰円小春', '彼女は、秘密結社「ブラック・ロア」のモンスター開発部門の主任研究員である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b266405-1LrHgO13YsWu.png', NULL, NULL, '小宮有紗', NULL, 266405, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018364', 'AN1784', '佐田巻始', '常に白衣とARゴーグルを身につけている、アガスティアの開発責任者。気さくな性格だが、締め切りに追われると時々参ってしまうこともある。ゴーグルを外すと、その素顔は意外にもハンサムだ。（出典：公式サイト、翻訳）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b254524-FmwKcniR8HFl.png', NULL, NULL, '梅原裕一郎', 176, 254524, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
