INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018367', 'AN1784', 'エルバッキー', '彼女は、「シークレット・ソサエティ：ブラック・ローレ」の峰円小春によって生み出された宇宙猫のモンスターです。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b283061-lQsLKde3TJuj.jpg', NULL, NULL, '原田ひとみ', NULL, 283061, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018368', 'AN1784', 'メギストス', 'アガスティアの首席戦略家であり、頭脳役。カリスマ性に富み、組織の実質的な意思決定者である。その立場上、モンスターの開発に関して黒一と意見が対立することもあるが、実際には部下を非常に気遣っている。ある意味、悪の組織にとって理想的なボスと言える。  （出典：公式サイト、翻訳）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b258064-80zA5zEzioKV.png', NULL, NULL, '稲田徹', 200, 258064, 'SUPPORTING', 23) ON CONFLICT DO NOTHING;
