INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018371', 'AN1784', 'マミー', '彼女はアイドルが好きで、自分もアイドルになろうと努力している「アンチブレイダー」のモンスターだ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b283062-HsiqrplVkHwe.jpg', NULL, NULL, '小林友里花', NULL, 283062, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018372', 'AN1784', 'アカシック', '邪悪な秘密組織「アガスティア」のリーダー。外見や振る舞いは若い少女のようだが、その能力は組織内で最強である。彼女は衝動的に行動する傾向があり、彼女のたった一言で組織の方向性やモンスターの在り方が突然変わり、黒一や同僚たちをしばしば動揺させる。  （出典：公式サイト、翻訳）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b258065-YdxHXnvZfUNP.png', NULL, NULL, '市道真央', 127, 258065, 'SUPPORTING', 29) ON CONFLICT DO NOTHING;
