INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018375', 'AN1784', 'メルティ', 'Wulf Bete、アカシック、そしてKuroitsuによって生み出されたチョコレートの怪物。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b283064-L97sz2iYAvUt.jpg', NULL, NULL, '富田美憂', NULL, 283064, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018376', 'AN1784', '佐田巻健司', 'ケンシン・ブレイダーは、正義感あふれる変身ヒーローだ。彼の正体は、弁当店でアルバイトをしている青年・ケンジである。彼は正直で誠実な性格で、正義感に燃える立派な青年だが、その真面目さゆえに、女性には全くモテない。    （出典：公式サイト、翻訳）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b258066-gRxAryF9hXG6.png', NULL, NULL, '寺島拓篤', 178, 258066, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
