INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018378', 'AN1784', 'フルーレティ', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b262363-Zb5OTfyih650.png', NULL, NULL, '石上静香', NULL, 262363, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018379', 'AN1784', 'カノン・サンダーバード', '彼は長距離狙撃を専門とする鳥型のモンスターだ。少なくとも本人はそう言っている。見た目は巨大なひよこのように、コミカルな風貌をしている。性格は穏やかで人情味があるが、真面目な性格ゆえに、時折、自分の存在意義に悩まされているように見えることもある。  （出典：公式サイト、翻訳）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b259681-zGY2x1DrPQ5K.png', NULL, NULL, '土岐隼一', NULL, 259681, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
