INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018382', 'AN1784', 'ヒュドラ', '背中に異次元から水蛇を召喚できる、少女の姿をしたモンスター。本来は毒を使った遠距離攻撃が得意な神となる予定だったが、これは実装されていない。 少女はひどく怯えていて弱々しいが、水蛇たちは彼女を「マツ」と呼び、妹のように可愛がっている。（出典：公式サイト、翻訳）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b259683-CDfPAm0sTYUX.png', NULL, NULL, '藍川ふみ', 132, 259683, 'SUPPORTING', 21) ON CONFLICT DO NOTHING;
