INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018385', 'AN1785', 'M4 SOPMOD II', 'M4 SOPMOD IIは、フルネームが長すぎると感じているため、「SOP-II」と呼ばれることを好む。彼女は戦闘と仲間との時間を愛する、情熱的で意欲的なT-Dollであり、自らをサディストと公言しており、敵を拷問し、その身体の一部を集めたいという抑えきれない衝動を抱いている。 SOP-II自身の言葉によれば、これはサンギス・フェリの部隊だけでなく、味方の敵であれば誰に対しても当てはまる。というのも、彼女の主な動機は、自らの目的のために戦うことよりも、友人を守り、「悪党」を罰することにあるからだ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b135794-Fdqm46wDku4V.png', NULL, NULL, '田村ゆかり', NULL, 135794, 'MAIN', 154) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018386', 'AN1785', 'M4A1', 'M4A1はARチームのリーダーだが、経験に欠けている。そのため、決断力に乏しく、やや頼りないT-Dollだと評されることが多い。M4A1は、誕生以来「他のT-Dollよりも重要だ」と言われてきたため、自分を責めたり、自分の判断を疑ったりする傾向がある。 その不安感から、彼女は他者、とりわけチームメイトに比べて、自分の命をはるかに軽んじてしまう。ARチームの保護から切り離されたシミュレーション状況では、彼女は', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b135795-BFUbZxAfi4OJ.png', NULL, NULL, '戸松遥', NULL, 135795, 'MAIN', 138) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018387', 'AN1785', 'ST AR-15', 'ST AR-15（略称：AR-15）は、真面目で厳格、かつ有能なエリートT-ドールであり、ARチームの一員である。ARチームのメンバーに対しては厳しい態度をとるものの、AR-15は彼らを心から友人として考えており、仲間を傷つけた敵への復讐こそが、彼女にとって大きな原動力となっていた。 グリフィンから一時逃亡した後、彼女は自身の自由だけを重んじる「反抗的な兵士」という評判を得てしまった。彼女は「兵士の勇気こそが指揮官の名誉となる」と語り、自信を持って戦いに臨む。M4とは対照的に、w', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b135793-eBJobz7dVXAX.png', NULL, NULL, '加藤英美里', NULL, 135793, 'MAIN', 108) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018388', 'AN1785', 'M16A1', 'ARチームの最古参メンバーとして、M16A1はAR M4A1自身をも凌ぐほど、チーム各メンバーの性格を深く理解していた。多少無鉄砲な振る舞いを見せることもあったが、M16A1はARチームの中で最も冷静沈着なT-Dollと見なされており、「勇気と愚かさを分けるのは結果だけだ」と語っていた。 彼女はチームの他のメンバーにとってメンターであり、戦術指導者としての役割を果たしており、感情を持つことこそが、T-Dollと、雇用されているような無思考な殺戮マシンとの重要な違いであると考えていた。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b135782-1Zjpc21SX7Zk.jpg', NULL, NULL, '山根希美', NULL, 135782, 'MAIN', 77) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018389', 'AN1785', '简缇娅', 'ジェンティアンは、グリフィン＆クライガーに所属する22歳の女性指揮官で、セクター09の第794ステーションに配属されている。（出典：ガールズ・フロントライン ウィキ）', 22, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b186325-n2OgV0QyeyJj.png', '12月23日', 'A', '小松未可子', NULL, 186325, 'MAIN', 18) ON CONFLICT DO NOTHING;
