INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018393', 'AN1785', '干擾者', 'サポートコマンドドール、モデルSP914「干擾者」は、味方にも敵に対しても、穏やかで物腰が柔らかく、親切な印象を与える。 しかし、彼女と接する者は、その優しい表向きの姿の奥に空虚さを感じることが多く、そのあまりに、部下のリングリーダー「狩猎者」は恐怖から「干擾者」に対して嫌悪感を示したほどである。（出典：Girls'' Frontline wiki）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b186355-hsLLty5i8l8C.png', NULL, NULL, '大坪由佳', NULL, 186355, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
