INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018395', 'AN1785', '石軍', 'セクター09付近の第601ステーションに配属されている、グリフィン＆クライガーの指揮官。（出典：ガールズ・フロントライン ウィキ）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b186351-RfR3OKILrPV0.png', NULL, NULL, '三瓶雄樹', NULL, 186351, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018396', 'AN1785', 'アルケミスト', 'サンギス・フェリの特殊作戦部隊型の首謀者。 数多くの戦術に長けているが、特に尋問を専門としており、標的を追い詰め、挑発することに大きな喜びを見出している。 非常に傲慢で残酷、高慢ではあるものの、感情面では非常に成熟しており、概して遊び心も豊かだ（例えば、よくペアを組むことになるデストロイヤーをからかうことが多い）。サンヴィス・フェリの仲間のためなら一肌脱ぐことも厭わず、彼らを「まるで大きな幸せな家族のようなもの」とさえ述べている （これは狩猎者にとっては大いに', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b194319-4jePYqpZzEEb.jpg', NULL, NULL, '佐藤有世 ', NULL, 194319, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018397', 'AN1785', 'ベレゾヴィッチ・クルーガー', 'ベレゾヴィッチ・クルーガーは、グリフィン＆クルーガー社の創設者兼代表である。現在は退役した軍人であり、かつては新ソビエト連邦内務省の職員を務めていた。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b186701-6jLlEjJ7Z55l.png', NULL, NULL, '大塚明夫', NULL, 186701, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
