INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018403', 'AN1785', 'Elisa', 'Lyco社が開発したハイエンド人工知能。指揮官が簡単な命令を下すだけで、メインフレーム「エリサ」がそれを実行するための合理的な行動方針を自動的に算出する。 この高性能AIメインフレームは、彼女に直接忠誠を誓う戦闘ドール部隊を擁しており、インターネットを介して遠隔操作を行い、指令を実行させることができる。しかし、エリサは単なるAIプログラムではない。ライコの究極の目標は、自己認識能力を備えた完璧なAIを生み出すことであり、', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b194324-BinHD5Lz87sC.png', NULL, NULL, '高橋李依', NULL, 194324, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018404', 'AN1785', 'P7', '漫画の中で、ジェンティアンが指揮を執るT-Doll', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b186327-zh8HY6KJp3T4.png', NULL, NULL, '黒沢ともよ', NULL, 186327, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018405', 'AN1785', '狩猎者', '機動戦闘ドール、型番SP721。サンギス・フェリの戦闘型首領であり、干擾者（ガガー）に直属している。機敏かつ知性が高く、狩猎者は戦闘における敵への嫌がらせや追撃に最も適しており、通常は単独での戦闘任務を好む。 ほとんどの戦闘型リーダーと同様、狩猎者はスケアクロウやエクスキューショナーといった指揮型リーダーほど多くの通常のSF部隊を指揮することはできないため、自身の潜在能力を最大限に発揮するために、しばしば彼らと連携して行動する。（出典：ガールズ・フロントライン）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b186346-8tidW3LA2t29.png', NULL, NULL, '萩原あみ', NULL, 186346, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
