INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018408', 'AN1785', 'HK416', 'HK416は、エリートT-ドールとしての地位と自身の戦闘能力を大いに誇りに思っている、真面目で口うるさいドールだ。また、強い正義感を持っており、それが彼女を弱者やチームメイトを守るように駆り立てている。  G11の怠けぶりに常に頭を抱えているものの、かつてG11をギャングのメンバーから救い出したことから、416は彼女と非常に親しい関係にある。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b135776-wwEo4JVN0Lvf.png', NULL, NULL, '野中藍', NULL, 135776, 'SUPPORTING', 127) ON CONFLICT DO NOTHING;
