INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018411', 'AN1785', 'UMP9', 'UMP9（通称「9」）は、率直で親しみやすい性格が特徴の、有能なT-Dollである。UMP45との出会いをきっかけに、彼女に対して強い憧れを抱くようになり、時には「お姉ちゃん」と呼ぶこともある。 第404小隊内では、9は45の副官としての役割を果たしており、どんな状況でも通常は45の味方をするが、時折45の機嫌を損ねてしまうこともある。第404小隊がチームとしてどれほど機能不全に陥っていようとも、9はそれを「家族」だと主張し続けている。 45や416とは異なり、9は小隊の評判を気にかけており、', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b135781-irEp09XYYIyq.png', NULL, NULL, '能登麻美子', NULL, 135781, 'SUPPORTING', 84) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018412', 'AN1785', 'MP-446', '漫画の中で、ジェンティアンが指揮を執るT-Doll', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b189825-hkKRkyN6hdUq.png', NULL, NULL, '野水伊織', NULL, 189825, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018413', 'AN1785', 'グリフィンスタッフ', 'グリフィン社に勤める男性', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b263191-6zRLPJxfZcBh.png', NULL, NULL, '大町朋裕', NULL, 263191, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018414', 'AN1785', 'UMP45', 'UMP45（通常「45」と略される）は、反逆したタクティカルドールであり、第404小隊のリーダーである。重大な裏切りによって形成された、執念深く冷徹で攻撃的な性格は、彼女のドライなユーモアによってかろうじて覆い隠されており、それが、彼女がめったに見せない深い「ソル」の神性を隠す役割を果たしている。 45は、ARチームのような自己犠牲的で英雄的な人々を嫌っている。彼女は、命は捨ててしまうにはあまりにも尊いものだと考えているからだ。この哲学は、かつての師であるUMP40から受け継いだものである。しかし、彼女の中には、ある程度の敬意も秘められている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b135775-loHv3CUlX9DD.png', NULL, NULL, '嶺内ともみ', NULL, 135775, 'SUPPORTING', 137) ON CONFLICT DO NOTHING;
