INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018424', 'AN1785', 'カリーナ', 'カリーナはグリフィン＆クリューガーの後方支援担当官であり、2062年にG&Kに入社した際、司令官の副官に就任して以来、一貫してその指揮下で勤務している。 彼女の仕事は、作戦中に司令官とそのT-ドールたちが使用する絶え間なく変動する資源の管理に加え、秘書業務も担当することである。（出典：Girls'' Frontline wiki）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b184836-J1KNKw4hgMNR.png', NULL, NULL, '東山奈央', NULL, 184836, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018425', 'AN1785', 'PPSh-41', '漫画の中で、ジェンティアンが指揮を執るT-Doll', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b186205-QWgFmeo4zM1X.png', NULL, NULL, '上坂すみれ', NULL, 186205, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018426', 'AN1785', 'ペルシカ', 'ペルシカは、タクティカルドールの科学者であり、16Labの創設者兼所長、そして元90wishのメンバーである。天才的な頭脳の持ち主として、現代のT-ドールが使用する最先端技術のほとんどを開発してきた。（出典：Girls'' Frontline wiki）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b184831-uKU9NW4zySlM.png', NULL, NULL, '萩原あみ', NULL, 184831, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
