INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018432', 'AN1785', '赫丽安图丝', 'ヘリアントゥス（「ひまわり」を意味する名前で、略してヘリアンとも呼ばれる）は、グリフィン＆クリューガーに所属する高位の将校である。彼女は本部からの命令を戦術指揮官に伝達するだけでなく、指揮官の行動を監視・報告する役割も担っている。  （出典：Girls'' Frontline wiki）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b186347-z5J5tzZWybTU.png', NULL, NULL, '苅谷瑠衣', NULL, 186347, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
