INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018435', 'AN1785', 'カモロフ', 'カモロフ司令官は、グリフィン＆クリューガーに所属する23歳の男性司令官で、セクター09近郊の第737ステーションに配属されている。（出典：ガールズ・フロントライン Wiki）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b186350-3q9XEefaxtTr.png', NULL, NULL, '星野充昭', NULL, 186350, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018436', 'AN1785', 'ガリル', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b196270-sonKsvMujhEQ.png', NULL, NULL, '御手洗 かりん', NULL, 196270, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018437', 'AN1785', 'スケアクロウ', '先遣偵察ドール、モデルSP65。情報の収集と分析には長けているが、直接的な戦闘には不向きである。サンギス・フェリのドールの中では、やや下位のランクに位置づけられている。 理性的で物静か、しかし辛辣な物言いを持ち、職務の遂行に徹し、感傷的なことを軽蔑している。感情豊かではあるものの、命令に従うことしかできないと彼女が感じるグリフィン・ドールたちに対して、優越感を抱いている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b191349-67JEnR8fbdr0.png', NULL, NULL, '奥野香耶', NULL, 191349, 'SUPPORTING', 14) ON CONFLICT DO NOTHING;
