INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018450', 'AN1786', '副署長', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b256578-b9BAyRjISQb7.png', NULL, NULL, 'ケンドーコバヤシ', NULL, 256578, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018451', 'AN1787', '青山カズキ', 'ミナト族の前に突然現れたカズキは、部族への加入を申し出た謎めいた青年だ。  左手を負傷しているため、XBを思うようにプレイできないようだ。しかし、なぜかXBの戦術に精通しており、ビームバットの扱い方についても詳しい知識を持っており、その知恵でミナトに勝利をもたらした。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b250098-ngZA61mQao16.png', '5月18日', NULL, '千葉翔也', NULL, 250098, 'MAIN', 40) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018452', 'AN1787', '有栖川さおり', 'サオリは「ミナト・トライブ」の副リーダーだ。その可憐な外見とは裏腹に、神谷の速球もキャッチできる。サオリは優秀なキャッチャーである。彼女は誰よりも「ミナト・トライブ」のメンバーを大切に思っている。 サオリは規則や道徳を厳格に守り、それを破ったメンバーに対しては、お気に入りの爆発性エアガンを容赦なく使う。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b250099-ZV50eoXbEGMN.png', '11月22日', NULL, '渕上舞', NULL, 250099, 'MAIN', 49) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018453', 'AN1787', '大門愛海', 'マナミは「ミナト・トライブ」のメンバーだ。物腰が柔らかく、神の加護を受けて、常にメンバーを支えている。ミナトの隠れ家「ラブリー・オーシャン」は、マナミが立ち上げた店だ。普段は穏やかだが、一度怒り出したら、誰も彼をなだめることはできない。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b250100-kgbaEOnPBPP0.png', '7月20日', NULL, '落合福嗣', NULL, 250100, 'MAIN', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018454', 'AN1787', '神谷瞬', '神谷瞬は、湊族のリーダーである。チームメイトに意味不明なあだ名をつけたり、コーヒーで二日酔いになったりするなど、奇行が目立つ。また、ビーバムバットを使える数少ない選手の一人であり、打撃と投球の両方をこなすオールラウンダーでもある。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b250101-u1UPu7Addq9x.png', '2月22日', NULL, '石田彰', 179, 250101, 'MAIN', 78) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018455', 'AN1787', '三田三太郎', 'サンタロウは「ミナト・トライブ」のメンバーで、自分はミナトのエースだと主張している。実際にはミナトの控え投手である。好色で、汚い言葉を多用し、無作法な振る舞いをする。よくサオリに叱られ、ボコボコにされるが、改める気配は微塵もない。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b250102-ZqBhiP4kgGoY.png', '3月30日', NULL, '田村睦心', NULL, 250102, 'MAIN', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018456', 'AN1787', '白金ハル', '彼は臆病な少年で、常にいじめられている。自分に自信が持てず、そのことで心を縛られているものの、彼は優れた視力と素早い反射神経を持っており、神谷はその才能を見抜き、それを活用しようと、ハルを自身の「ミナト・トライブ」に誘うことにした。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b250103-17GMPMc5gk9F.png', '1月20日', NULL, '堀江瞬', 160, 250103, 'MAIN', 32) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018457', 'AN1787', 'タイガ', '最強の男、神谷瞬を倒すことを目指して、タイガは海を越えてネオ・トーキョーへとやってきた。彼はミナト・トライブに加わるが、XBの初心者であるタイガは、ゲームのルールを覚えるのに苦労している。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b250104-rYXo8C4zkscP.png', '10月10日', NULL, '沢城千春', NULL, 250104, 'MAIN', 20) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018458', 'AN1787', 'ねこまる', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b250106-7IBL4wjotNMu.png', NULL, NULL, '渕上舞', NULL, 250106, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018459', 'AN1787', '園田不兆', 'オタ族の首領。 彼は型にはまった調和を嫌悪し、常に「混沌」を追い求めている。 彼は強盗であり、殺人者でもある。混沌のためなら、手段を選ばない。彼の行動の中には、一般の人には理解できないものもある。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b256840-Y83oSUTr4JyW.png', '1月12日', NULL, '寺島惇太', NULL, 256840, 'SUPPORTING', 16) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018460', 'AN1787', 'ジャッジロボ', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b263537-3aryiVwuP3l3.png', NULL, NULL, '鷲見昂大', NULL, 263537, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018461', 'AN1787', '鳳王次郎', '千代田一族のリーダー。最強のXBプレイヤーになるため、天心の指導を受けてきた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b250107-zj1GlEyyYIOx.png', '9月26日', NULL, '諏訪部順一', NULL, 250107, 'SUPPORTING', 51) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018462', 'AN1787', '雪谷えのき', 'オタ族の一員。その可愛らしい外見とは裏腹に、笑いながらロケットランチャーを発射する。エノキは食べるのが大好きで、いつもお腹を空かせている。食料の確保が難しいオタ市では、食料に困らないよう、園田たちと一緒に暮らしている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b256842-PbpQqVplAHme.png', '10月15日', NULL, '近藤玲奈', NULL, 256842, 'SUPPORTING', 22) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018463', 'AN1787', '轟英二', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b263539-XGvJGnYJdKRS.png', '12月1日', NULL, '小野賢章', NULL, 263539, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018464', 'AN1787', '鳳天心', 'ネオ・トーキョーの王。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b250108-UZdzbhYKb7yz.png', '1月31日', NULL, '中博史', NULL, 250108, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018465', 'AN1787', '旭川カイ', 'オタ・トライブの一員。悪役たちの中でも群を抜いて最も狂気じみた男。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b256844-YFPKjvlwiDAP.png', '2月5日', NULL, '梶原岳人', NULL, 256844, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018466', 'AN1787', 'ヤスヒロ', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b275286-ThGQS7P0YNdG.png', NULL, NULL, '池田恭祐', NULL, 275286, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018467', 'AN1787', '梅田蘭吉', '「アダチ・トライブ」の副リーダーの一人で、モッドの製作者でもある。アダチ・トライブのバイカー集団の中でも、特にバイク操作に長けており、その巧妙なライディングで敵を翻弄する。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b256835-CsOzXp1C1MPn.png', '8月19日', NULL, '増田俊樹', NULL, 256835, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018468', 'AN1787', '西郷ロク', 'オタ族の一員。ロクはがっしりとした体格で、車を軽々と持ち上げることができる。あまり話したがらない、物静かな男だ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b256843-sJEIXGX1gQyw.png', '6月9日', NULL, '松田健一郎', NULL, 256843, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018469', 'AN1787', '池尻ぷりん', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b275287-N3X36wKjptMR.png', NULL, NULL, '前田玲奈', NULL, 275287, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018470', 'AN1787', '辰沼龍斗', '足立族の副族長の一人。足立族のバイカー集団の中でも、彼ほどスリリングな走りを見せる者はいない。その力強い走りで敵を蹴散らす。タツトは足立族の中では珍しい、物静かな男だ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b256836-8igsOuMzqrPg.png', '4月8日', NULL, '武内駿輔', NULL, 256836, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018471', 'AN1787', '羽田清死郎', 'オタ族の一員。園田に対して強い殺意を抱いており、常に彼の命を狙っている。しかし、そのたびに反撃を受けてきた。羽田はいつも血まみれだ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b256841-N3eCcsCc7LZi.png', '12月17日', NULL, '野津山幸宏', NULL, 256841, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018472', 'AN1787', '千住百太郎', '足立族のリーダーであり、エースピッチャー。「ファイアバット」といったユニークなXBギアを操る百太郎。XBに対して強い誇りを持っている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b256837-auEe4Zx8gyAM.png', '11月23日', NULL, '熊谷健太郎', NULL, 256837, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018473', 'AN1787', '五反田豊', '品川部族のリーダー。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b256845-3XJO0h1v0yQD.png', '4月10日', NULL, '駒田航', NULL, 256845, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018474', 'AN1787', '上野弥次郎兵衛', '台東族の首長。その能力は謎に包まれている。ヤジロベは、部族間の戦いの最前線に立つことはめったにない。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b256838-aq51hcwXskP2.png', '9月12日', NULL, '中村悠一', NULL, 256838, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018475', 'AN1787', '大井南', '品川トライブのメンバーであり、五反田の秘書でもある。XBプレイヤーとしても、ビジネスにおいても、ミナミは五反田の才能に魅了され、秘書として完璧なサポートを提供している。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b256846-NPut34HBOw33.png', '12月22日', NULL, '村井美里', NULL, 256846, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018476', 'AN1787', '神木結衣', '天心の秘書。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b250105-YdFRZXwf840L.png', '3月15日', NULL, '小松未可子', NULL, 250105, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018477', 'AN1787', '桜花札', 'タイトー・トライブのエース選手。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b256839-xAXFbXsKUj9u.png', '4月14日', NULL, '小野大輔', NULL, 256839, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018478', 'AN1788', '大和晴', 'ポジション：ピボ  ロサンゼルスのサンタモニカで育ち、U-18フットサルワールドカップの試合で天王寺刻成選手を見たことをきっかけに、日本へ移住した。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b149401-FWeKFluqp1dw.png', '8月20日', 'A', '高良崚太', 169, 149401, 'MAIN', 21) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018479', 'AN1788', '天門泰雅', 'ポジション：ゴールキーパー　幼なじみの南雲竜がライバルチームの選手たちに傷つけられたことをきっかけに、中学時代に喧嘩に巻き込まれた元不良。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b149404-dYQsx7mKWjd9.png', '5月15日', 'A', '坂井易直', 179, 149404, 'MAIN', 17) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018480', 'AN1788', '幸永椿貴', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b149405-KRahncOXbH3y.png', NULL, NULL, '山口諒太郎', NULL, 149405, 'MAIN', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018481', 'AN1788', '南雲竜', 'ポジション：ピボ  小柄であることをあまり気にしておらず、常にチームに「神モード」をもたらしてくれる。性格は穏やかだが、非常に洞察力に富んでいる。 小柄ながらも、かつてはジュニア大会で得点王に輝いた攻撃的な選手だ。アマチュアのフットサル選手であるヤマトには、まるで兄のようによく指導している。幼なじみの彼が、いつかまたフットサルを再開してくれることを願っている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b149403-BmcGuoSeTTNR.png', '4月21日', 'O', '古田一紀', 160, 149403, 'MAIN', 18) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018482', 'AN1788', '榊星一郎', 'ポジション：ウイング　清一郎はクールで無口な性格で、自分自身にも他人にも厳しい。中学生の頃からオールラウンドな選手として卓越した才能を発揮してきた。チームメイトの助けを借りずに、すべてを自分一人でこなすほうが良いと考えている。 アマチュアのフットサル選手である大和晴を特に信用しておらず、二人はよく口論になる。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b149400-kOXOXF99AHia.png', '1月1日', NULL, '石森周斗', 177, 149400, 'MAIN', 12) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018483', 'AN1788', '月丘柊依', 'ポジション：ディフェンダー　光陽フットサルクラブのキャプテンであり、1年間の留学を終えてスペインから帰国したばかり。また、岡山学園の天王寺トキナリやアダルベルト学園の樫良木ルイらと共にU-18代表チームにも所属していた。 彼は、いわゆる「ゴールデン・トライアングル」の一員だった。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b149412-mhTHbwVWpoen.png', '12月24日', NULL, '吉原康平', 181, 149412, 'MAIN', 14) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018484', 'AN1788', '宇佐美智', '彼は「光陽フットサルクラブ」の監督である。彼と幸永椿貴は、月丘柊依がスペインから帰国するまで、このフットサルチームを支えていた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b254141-PQWcdOE6JD2r.png', NULL, NULL, '山下誠一郎', NULL, 254141, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
