INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018493', 'AN1788', '結城心', 'ポジション：ゴールキーパー　シンはアダルベルト・フットサルクラブの副キャプテンであり、樫良木ルイの幼なじみである。クラブを率いながらいじめを行うロイスとは異なり、副キャプテンとしてチームメイトに優しく接し、彼らの意見に従っている。 しかし、その優しさゆえに、ロイスが理不尽な練習を強いると、チームメイトから怒られることもある。彼は二葉ともえの才能を見抜き、フットサルクラブに誘った。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b254144-b76wS98ikmoc.png', '11月13日', 'O', '新井雄也', 185, 254144, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
