INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018496', 'AN1788', '二葉ともえ', 'ポジション：アラ。 トモエは、テレビ番組『スペース戦隊ギャラクシーヒーローズ』が大好きで、生粋のオタクだが、怖い人だと誤解されがちだ。友人の結城心からフットサルの誘いを受けた。また、トモエは両利きである。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b254145-oT4of8awKTGa.png', '2月6日', 'AB', '山本智哉', 170, 254145, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
