INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018525', 'AN1789', '遠野美弥子', '遠野美弥子は、アニメ『i』『ハナ・ランマン！ブロムボール</i>』で、野道すみれ役を演じている声優です。率直な性格のため、志穂やほのかとも気兼ねなく自由に話すことができます。（出典：公式サイト、翻訳・編集済み）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b273965-dN96hjYKpHwP.png', NULL, NULL, '荻野葉月', NULL, 273965, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018526', 'AN1789', '五十鈴りお', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b262820-7uQoquKHGyT9.png', '5月4日', 'B', '洲崎綾', 151, 262820, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018527', 'AN1789', '福岡雄介', '福岡雄介は、アニメ『<i>ハナ・ランマン！ブロムボール</i>』の監督を務めている。40代で、以前はアニメーターだった。細部までこだわるタイプではないが、サウンドや声優についてある程度の知識を持っている。（出典：公式サイト、翻訳・編集済み）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b273966-mMwQfGWVpI3B.png', NULL, NULL, '兼政郁人', NULL, 273966, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018528', 'AN1789', '由良桐花', NULL, 34, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b262821-wNCq7JZ1JIGJ.png', '1月17日', 'A', '五十嵐裕美', 167, 262821, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018529', 'AN1789', '斉田源三郎', '斉田源三郎氏は、アニメ『<i>ハナ・ランマン！ブロムボール</i>』の第2話監督を務めるほか、制作会社「サンザン・プロ」の会長も務めている。過去には、AiRBLUEの代表である鳳真咲氏とも良好な関係を築いてきた。彼の話し方は、時に威圧的に感じられることもある。  （出典：公式サイト、翻訳・編集）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b273967-GSnW6ts08Vf8.png', NULL, NULL, '松山鷹志', NULL, 273967, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018530', 'AN1789', '安藤紗月', '安藤紗月は、<i>『ハナ・ランマン！ブロム・ボール』</i>の編集者です。無量坂京子とは親しい関係にあり、お互いを「ケイちゃん」と「サキちゃん」と呼び合っています。京子の代わりに、アニメ関連の打ち合わせに出席することもあります。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b263884-A6gqE3MPw8zd.png', NULL, NULL, '中原麻衣', NULL, 263884, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018531', 'AN1789', '無量坂京子', '無量坂京子は、月刊少年雑誌で5年以上にわたり連載されている『<i>ハナ・ランマン！ブロムボール</i>』シリーズの原作者である。彼女は物静かな性格で、話すことよりも絵を描くことを好む。その創作スタイルは、漫画のストーリーよりもキャラクターを重視する傾向がある。  （出典：公式サイト、翻訳・編集）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b273968-1IDPzIoF4TB8.png', NULL, NULL, '種﨑敦美', NULL, 273968, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018532', 'AN1789', '名木原琴子', '名木原琴子は、アニメ『i』『ハナ・ランマン！ブロム・ボール</i>』で、ユキハラ・リッカ役を演じる若手声優です。（出典：公式サイト、翻訳・編集済み）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b273961-rU9jLHUx1nTZ.png', NULL, NULL, '鬼頭明里', NULL, 273961, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018533', 'AN1789', '夕塚のぞみ', '夕塚のぞみは、アニメ『<i>ハナ・ランマン！ブロムボール</i>』で主人公のミダレザキ・ヒバナ役を演じる人気声優です。（出典：公式サイト、翻訳・編集済み）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b273969-xSeY0jPnauTN.png', NULL, NULL, '内田真礼', NULL, 273969, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
