INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018536', 'AN1789', '望月エイジ', '望月エイジ氏は、アニメ『i』『ハナ・ランマン！ブロムボール』</i>のプロデューサーを務めている。もともと音楽部門に所属していたが、3年前にアニメ映像部門に異動した。（出典：公式サイト、翻訳・編集）', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b273963-pPS6yLhhEP16.png', NULL, NULL, '興津和幸', NULL, 273963, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018537', 'AN1789', '高阪せつ子', '高阪せつ子さんは、アニメ『i』『ハナ・ランマン！ブロムボール』</i>で、セント・スカイブルー学園の校長役を演じるベテラン声優です。彼女は周囲の若手声優たちを気遣い、彼らの絆を深める手助けをしています。（出典：公式サイト、翻訳・編集）', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b273971-Mo6pDFRBT0yh.png', NULL, NULL, '渡辺久美子', NULL, 273971, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
