INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018547', 'AN1790', 'ジョイ', 'ジョイはバイクが大好きな若い女性です。彼女は陽気で、思ったことを率直に口にするタイプです。その話し方のせいで、無愛想で自己中心的な人だと誤解されることもよくありますが、実は親切で誠実な人です。彼女の父親は貿易業を営んでおり、多くの人から厚い信頼を寄せられています。 父親の影響もあってか、ジョイもまた多くの人から尊敬されている。リョウと同じように、ジョイも幼い頃に母親を亡くしている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b273241-Fi3mFSnXioly.png', NULL, NULL, '市道真央', NULL, 273241, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
