INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018555', 'AN1792', '和実ゆい', 'ユイは、のんびりとしていて、率直で、元気いっぱいな中学2年生です。家族はダイナーを経営しており、彼女は一人っ子です。食欲が旺盛で、すぐに空腹になります。彼女の決め台詞は「おいしい笑顔～！」と「お腹すいた～！」です。新鮮な野菜が大好きです。 ユイは、祖母の「食べ物は笑顔」というモットーを大切にしている。コメコメの力によって、キュア・プレシオスに変身することができる。', 13, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b260897-xQjXcxjv2ySX.jpg', '8月31日', NULL, '菱川花菜', 155, 260897, 'MAIN', 78) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018556', 'AN1792', '華矯らん', 'ランは、おしゃべりが大好きな、かわいい中学2年生です。 彼女の家族はラーメン店を経営している。妹と弟が一人ずついる。食べ物にはとても興味津々で、興奮すると止まらなくなるほどおしゃべりだ。キュレスタにこっそりご飯に関する投稿をしている。メンメンの力によって、キュア・ヤムヤムに変身することができる。', 13, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b260898-bcm0llgIrOeB.png', '7月11日', NULL, '井口裕香', 150, 260898, 'MAIN', 61) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018557', 'AN1792', '芙羽ここね', 'ココネは、おしゃれで色白の美人だ。メイクやかわいいものが大好きな中学2年生。家族は高級レストランを経営しており、彼女は一人っ子だ。「高嶺の花」と呼ばれている。一人でいることが好きで、あまり話さない。 ココネの好きなパンは、カレーパンとハート型のパンです。パムパムの力を使って、キュア・スパイシーに変身することができます。', 13, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b260899-OuEXVOZAsF26.png', '3月13日', NULL, '清水理沙', 165, 260899, 'MAIN', 76) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018558', 'AN1792', 'メンメン', 'Mem-Mem is the Energy fairy of Noodles, and resembles a dragon. About 4-5 in human years, he''s relaxed and doesn''t make a fuss. He''s impressed by Ran''s passion. When he joins forces with Ran he enters his "bowl form." He ends his sentences with "~men" (~メン).', 4, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b260905-OMX4BStCLWIN.png', '11月11日', NULL, '半場友恵', NULL, 260905, 'MAIN', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018559', 'AN1792', 'パムパム', 'Pam-Pam is the Energy Fairy of Bread, and resembles a dog. She''s 4 or 5 in human years, and loves to get compliments. She loves Kokone. When she combines forces with Kokone, she enters "Sandwich form." She ends her sentences with "~pam" (~パム).', 4, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b260904-B9R11giWBgZh.png', '4月12日', NULL, '日岡なつみ', NULL, 260904, 'MAIN', 12) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018560', 'AN1792', 'コメコメ', 'Kome-Kome is the Energy Fairy of Rice, and resembles a white fox. Compared to Pam-Pam and Mem-Mem, she''s young, innocent and energetic. When she combines forces and transforms with Yui, she enters her "rice ball form." She ends her sentences with "~kome" (~コメ).', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b260903-VYxVRNTVgpUn.png', '8月18日', NULL, '高森奈津美', NULL, 260903, 'MAIN', 25) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018561', 'AN1792', '菓彩あまね', '新泉中学校の生徒会長。「フルーツパーラーKASAI」というフルーツ店兼カフェを家族で経営している。 アマネは、上品で勤勉、親切で思いやりのある人物です。周囲の人々のことを大切に思うあまり、時として頑固になることもあります。また、強い正義感の持ち主としても知られています。彼女は、みんなを笑顔にしたいと願っています。', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b260908-lYwmFvAAnexX.jpg', '11月24日', NULL, '茅野愛衣', NULL, 260908, 'MAIN', 54) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018562', 'AN1792', '品田拓海', 'タクミは物言いが率直だが、人のことを気遣う性格だ。恋愛に関する話題になると、慌てふためいてしまう。また、他人の意見に左右されることなく、自分の感情や意見を率直に表現する。 彼の家族は「福庵」というゲストハウスを経営している。和実ゆいは彼の幼なじみだ。彼は彼女を深く思いやり、想いを寄せている。また、たくりはゆいの幸せを守るためなら、どんなことでもするだろう。', 14, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b260907-b1vk7XSaxkWX.png', '11月3日', NULL, '内田雄馬', NULL, 260907, 'SUPPORTING', 16) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018563', 'AN1792', 'ウバウゾー', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b264071-1gzDrFcg4cnN.png', NULL, NULL, '堀総士郎', NULL, 264071, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018564', 'AN1792', 'ナルシストルー', 'ナルシストルーは、自らを天才と称する人物で、かなり皮肉屋なところがある。また、敵を攻撃する前に、遠くから観察することを好む。その名の通り、彼は他人を見下す極めて傲慢なナルシストであり、目的を達成するためなら暴力も厭わない。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b278693-YXZlF85x0XUv.png', NULL, NULL, '阪口周平', NULL, 278693, 'SUPPORTING', 14) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018565', 'AN1792', '山倉もえ', '新泉中学校の副校長。アマネに感化され、彼女と共に活動している。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b301472-1XDEWuIKafP7.jpg', NULL, NULL, '長谷川育美', NULL, 301472, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018566', 'AN1792', '品田あん', 'タクミのお母さん。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b263724-FDlev6kj1jbt.png', NULL, NULL, '大西沙織', NULL, 263724, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018567', 'AN1792', '本間ともえ', '新泉中学校の生徒。トモエは、タクミに片思いをしている感情豊かな少女だ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b301471-AnNRDLGzQ1YD.jpg', NULL, NULL, '島袋美由利', NULL, 301471, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
