INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018569', 'AN1792', 'スピリットルー', 'ナルシストルーが開発したロボットであり、バンドル・ギャングの将軍でもある。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b313465-zJOlnoC8Rfr8.jpg', NULL, NULL, 'かぬか光明', NULL, 313465, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
