INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018571', 'AN1792', '轟', 'フワ家の専属執事。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b313466-4FSKPYfL4vgM.jpg', NULL, NULL, '樫井笙人', NULL, 313466, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018572', 'AN1792', 'クッキング', 'クッキング界の王者。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b263727-kSuHefJNftwG.png', NULL, NULL, '鈴木琢磨', NULL, 263727, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018573', 'AN1792', 'ローズマリー', 'レシピボンを求めてクッキングダムからやってきたコックファイター。美意識が高く、美容の知識にも精通している。また、よく泣く感情豊かな性格で、友人を深く思いやり、必要な時にはいつでもアドバイスを惜しまない。  ローズマリーは「デリシオス・フィールド」と呼ばれる異次元を召喚することができ、キュアたちが地球の無実の市民を傷つけることなく、バンドル・ギャングと戦うことを可能にしている。また、白兵戦も得意だ。この能力はさらに強化され、', 36, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b260906-xY0J4k21M0mv.png', '8月2日', NULL, '前野智昭', NULL, 260906, 'SUPPORTING', 17) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018574', 'AN1792', 'フェンネル', 'フェンネルは、クッキングドムの帝国衛兵隊長である。彼はローズマリーの同僚であり、親友でもある。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b264025-ghl2OJuOkrlu.png', NULL, NULL, '三上哲', NULL, 264025, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018575', 'AN1792', 'クックイーン', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b264024-0CqlIbvErFBu.png', NULL, NULL, '篠原恵美', NULL, 264024, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018576', 'AN1793', '豬八戒', '穏やかで落ち着いた外見とは裏腹に、八戒は決して侮れない妖怪である。戦闘時には自身の「気」を強力なエネルギーの爆発へと変換できるほか、それを盾として形作り、自身や仲間を守ることもできる。彼はリミッターの役割を果たす3つのイヤカフを身につけている。 これらを外すと、彼の真の力が解き放たれる。この姿になれば、自分よりはるかに大きな妖怪や、多数の敵を次々と倒すことも珍しくない。しかし、仲間を危険にさらす可能性があるため、八戒はこうした行動をためらうことが多い。  ot', 22, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b219-JDw11bFgEtRX.jpg', '9月21日', 'AB', '石田彰', 181, 219, 'MAIN', 86) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018577', 'AN1793', 'ヘイゼル＝グロース', 'ヘーゼルは『西遊記リロード』に登場するキャラクターで、「虫でさえも」編から登場し始めた。    ～ 背景 ～    彼は、豊かな西方大陸出身の外国人で、シャングリラを訪れるために海を渡ってきた。 その装いは教会のものだが、実際には、彼にとって父であり「師」でもあった男の足跡をたどり、魔物を退治している。幼い頃、師が魔物に殺されたため、彼は今、心に消えることのない復讐の念を抱いており、', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/21498.jpg', NULL, NULL, '遠近孝一', NULL, 21498, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018578', 'AN1793', 'ガティ=ネネホーク', 'ガティ（Gat）またはガト（Gato）は、『西遊記リロード』に登場するキャラクターで、「虫でさえも」編から登場し始めた。『西遊記リロード』第9巻第43話で明らかになった通り、彼のフルネームはガティ＝ネネホークである。     ～ 背景 ～    ヘーゼルの大柄なボディーガード兼旅の仲間であり、2丁の拳銃を操る。ヘーゼルがペンダントに「ソル」を蓄えているか、あるいは近くから「ソル」を採取できる死体がある限り、即座に蘇生または回復できるため、彼はヘーゼルのために無謀な戦いも厭わない。 彼の過去については、ほとんど知られていないが、', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/29907.jpg', NULL, NULL, '小山力也', NULL, 29907, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018579', 'AN1793', '你健一', '彼は『天地開元「無天」経』の守護者であり、現役の三蔵僧の一人である。現在は出自を隠し、ホト城で牛魔王復活実験を遂行する役割を担っているが、その目的は不明である。 彼は常に遠方から三蔵一派の動きを観察している。彼らの将来をまるでゲームのように眺めることを楽しんでいるため、遠方からトラブルを煽っているのだ。これは三蔵一派に限ったことではなく、近隣の古賀寺の一派も彼の掌握下にある。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/9263.jpg', NULL, NULL, '大塚芳忠', NULL, 9263, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
