INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018592', 'AN1795', 'エゼット', 'エゼットは、地球出身ではない少年で、「ニンジャガム」を探してこの惑星に不時着した。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b306764-m6fr42ux9gWL.png', NULL, NULL, '榎木淳弥', NULL, 306764, 'MAIN', 0) ON CONFLICT DO NOTHING;
