INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018594', 'AN1795', 'ジェーン', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b187907-yJszgkoEphDR.png', NULL, NULL, '皆川純子', NULL, 187907, 'MAIN', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018595', 'AN1795', 'ルーシー', 'ルーシーは、アニメ『ニンジャラ 2Dカートゥーン』の第2話の主人公です。ルーシーは右目に計り知れない力を秘めており、それが理由で眼帯をしています。 その力ゆえに、周囲から「怪物」と呼ばれることが多く、そのせいで友達を失うことを恐れている。そのため、彼女は内気で人付き合いを避けるようになった。ある時、WNAアカデミーへの入学案内状を受け取った。忍者になることで、彼女は自分の力に自信を持つようになり、今ではありのままの自分を楽しむことができるようになった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b187871-QtC1yqcLkiXl.png', '2月26日', NULL, '悠木碧', NULL, 187871, 'MAIN', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018596', 'AN1795', 'バーン', 'バーンは『ニンジャラ』の第1話の主人公です。彼は母親と暮らしている陽気な少年で、バスケットボールが大好きです。その才能は抜群で、友人たちからは「天才」と呼ばれています。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b187875-pwlHH5g4C6XF.png', NULL, NULL, '小林由美子', NULL, 187875, 'MAIN', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018597', 'AN1795', 'カッペイ', 'カッペイは忍者村出身の少年で、ゲヌンサイの孫である。自分が本物の忍者の末裔であることを知った彼は、ガムッチと共に、祖父の弟であるゲンリュウサイを探す旅に出る。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b193481-RBR9Mbtz06Cg.png', '9月16日', NULL, '村瀬歩', NULL, 193481, 'MAIN', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018598', 'AN1795', 'ガムッチ', 'ガムッチは、忍者の力と関係があると思われる不思議な生き物だ。彼は宇宙人だと言われている。武器に変身する能力を持ち、その力を使ってカッペイの戦いを助けた。彼はカッペイと友達になり、ゲンリュウサイを探す旅に同行した。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b193482-H4AL3mYddmOS.jpg', NULL, NULL, '井上ほの花', NULL, 193482, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018599', 'AN1796', 'ドラゴノイド', 'ドラゴノイドは、『バクガン・バトル・プラネット』、『バクガン・アーマード・アライアンス』、『バクガン：ジオガン・ライジング』に登場するドラゴンタイプのバクガンである。ダン・クーソーの守護バクガンである。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b210056-gZ6KuWaObyvk.jpg', NULL, NULL, '武内駿輔', NULL, 210056, 'MAIN', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018600', 'AN1796', 'アテナ・モンド', 'アテナ・モンドは『爆丸エボリューションズ』の主要キャラクターです。彼女のパートナー爆丸はブリッツフォックスです。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b269088-YJSQUYfxAMPi.png', NULL, NULL, '持月玲依', NULL, 269088, 'MAIN', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018601', 'AN1796', 'ライトニング', '（犬の年齢換算で）フレンチ・ブルドッグの「ライトニング」は、自分のバクガンを持ち運び、発射できる首輪を身につけている。 いたずら動画を撮影する子供たちには「相棒」が必要だが、ヒーローたちにとってその相棒こそがライトニングだ。ダンの家の裏路地でうろついていた野良犬だったライトニングは、今では彼らの非公式なマスコットとなっている。 陽気でずんぐりした、眠たそうなフレンチ・ブルドッグのライトニングは、よくダンと共演している。その名前が示すほど速くはないが、トラブルが迫ってくると「ワン！」と吠えるのが得意だ。ライトニングはまさに', 18, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b138974-fn5o3PKyAf4m.jpg', NULL, NULL, '金田アキ', NULL, 138974, 'MAIN', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018602', 'AN1796', 'シュン・カザミ', 'シュンはまるで大人のような振る舞いをする。その真面目な態度は、服装の選び方にも表れている。すっきりとしたシルエットの青いスーツ。アインシュタインのように、彼は曜日ごとに1着ずつ持っている。ヒーローたちには1人のファンがいることを覚えているだろうか？　そう、それが彼だ。 彼の名前はシュン・カザミ。バクガンバトルでダンのチームに加わるため、地球の半分を旅してきた。年齢の割に大人びていて、早熟で謎めいたシュンは、ドラゴの発見を目撃した後、ダンの町に現れる。実は、シュンこそが', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b138976-eliOsqhOhzRM.jpg', NULL, NULL, '内山夕実', NULL, 138976, 'MAIN', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018603', 'AN1796', 'ウィントン・スタイルズ', 'ウィントンは、まるで何もないところから次々と生み出しているかのような、数え切れないほどのギアやガジェットを自在に使いこなす、のんびりとした「スラッカー・ハッカー」スタイルの持ち主だ。肩に掛けた多目的の「ハックパック」が、そのスタイルを完璧に引き立てている。 ウィントンとダンは小学1年生の頃から親友だ。二人が知り合ったのは、ダンが昼食用のテーブルからバックフリップをしようとして、持っていた携帯ゲーム機が壁にぶつかって飛んでしまった時のことだった。ウィントンはクリップとガムを使ってそれを直した。そう、ウィントンは賢い。本当に賢い。そして、多くの賢い子供たちと同じように、彼は自分の', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b138978-rC4DR1Rl4AjM.jpg', NULL, NULL, '福島潤', NULL, 138978, 'MAIN', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018604', 'AN1796', 'ダン・クーソー', 'ダンは「ヒーローズ」の「タレント」担当だ。この子にカメラを向け、何か課題を与えれば、間違いなく「いいね！」が欲しくなるようなパフォーマンスを見せてくれる。ダンは運動神経が良く、社交的で、誰にでも門戸を開き、仲間を力強く支える――本人はそう自覚していないものの、生まれながらのリーダーだ。 短くも輝かしい人生の中で、ダンは多くの友人を築いてきましたが、特に親友であるウィントン・スタイルズとリア・ベネガスに対しては並々ならぬ忠誠心を示しています。彼らは共に多くの困難を乗り越えてきており、意見が対立したとしても、誰も決して', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b138975-7tIui7jXKoN8.jpg', NULL, NULL, '高橋李依', NULL, 138975, 'MAIN', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018605', 'AN1796', 'リア・ヴェネガス', 'リア・ヴェネガスは、ファッションセンスが際立つ服装を好む一方で、芸術的なセンスも持ち合わせており、自分の見た目を一切気にしない。 彼女は視覚的に自己表現を行い、それが彼女のスタイルに反映されている――自作の「アップサイクル」ドレスにコンバットブーツを合わせたり、笑顔の猫がプリントされたTシャツの上にグランジ風のトップスを羽織ったりしている。 リア・ヴェネガスは、まさに唯一無二の存在だ。ダンとウィントンが、そのばかげたスタントを成功した動画に仕上げられなかった時、たまたま通りかかったリア・ヴェネガスが、自ら進んでいくつかの提案をすることで、その状況を好転させたのだ。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b138977-GcQhNxGferjY.jpg', NULL, NULL, '赤﨑千夏', NULL, 138977, 'MAIN', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018606', 'AN1796', 'アジット', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b162733-d4QLKYLYgKEJ.jpg', NULL, NULL, '村田太志', NULL, 162733, 'MAIN', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018607', 'AN1796', 'ブリッツフォックス', 'ブリッツフォックスは、『爆丸エボリューションズ』で初登場した、キツネのような姿をしたバクガンである。彼女はアテナ・モンドのバクガンパートナーである。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b269087-Ccvzg56R7ves.png', NULL, NULL, '八代拓', NULL, 269087, 'MAIN', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018608', 'AN1796', 'ピラビオン', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b161209-zOqMQ9us5a0B.png', NULL, NULL, NULL, NULL, 161209, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018609', 'AN1796', 'ベントン・ダスク', 'ベントン・ダスクは、バクガンが悪意や私利私欲のために利用されるのを防ぐことを使命としている。一方、姉のフィロメナ・ダスクはそれとは正反対の行動を取り、自身の会社「AAAnimus Inc.」を通じてバクガンから利益を得ようとしている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b141528-DYLo3QbaGaIw.jpg', NULL, NULL, NULL, NULL, 141528, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018610', 'AN1796', 'マサト・カザミ', 'マサト・カザミはシュンの従兄である。彼はAAANIMUS社に雇われ、シュンをヒーローの座から引きずり下ろす任務を負っている。マサトは、シュンを家族の元へ連れ戻すか、あるいは自分の家族のように彼を永遠に追放することで、自らの価値を証明しようとしている。  マサトは狡猾で、意地悪で、冷酷な人物だ。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b141529-Efxt41EybJdu.jpg', NULL, NULL, NULL, NULL, 141529, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018611', 'AN1796', 'クリスタル・ブルー', 'クリスタル・ブルーは、グレゴリウス・リードのエージェントであり、超能力者でもある。彼女のガーディアン・バクガンはノビリオスとマクソタウルス、そしてジオガン・スタードックスだ。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b215202-kXdmcdqag71X.png', NULL, NULL, NULL, NULL, 215202, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018612', 'AN1796', 'ジェニー・ハケット', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b215201-jObNGp0ALXFA.png', NULL, NULL, NULL, NULL, 215201, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018613', 'AN1796', 'マグナス・ブラック', '強力な「ニリオス」を操る仮面の少年は、ダンの最大のライバルとなる。マグナスは名声には全く関心がなく、その正体を謎に包んでいる。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b140002-1QYDNyfOqb2n.jpg', NULL, NULL, NULL, NULL, 140002, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018614', 'AN1796', 'カボ', 'すべてのバクガンの中で一番かわいい（そして一番うっとうしい）やつ。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b387575-DCob8xCUuuAK.png', NULL, NULL, '神尾晋一郎', NULL, 387575, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018615', 'AN1796', 'チャイナ・リオット', 'この6歳の「バクガン・バトラー」界の現象的存在は、甘やかされて育った一方で、恐ろしいほどの実力者でもある。自身の能力を最高額で入札した者に売り渡すことで、チャイナはAAANIMUS INC.に居心地の良い第二の居場所を見つけた。チャイナを動かす原動力は、お金と可愛いものを集めることだけだ。 チャイナはAAANIMUS INC.に所属しており、会社の目標達成のために必要とされればどこへでも赴く。彼女の最大の個人的目標は、史上最高かつ最もかわいいバクガンファイターになることだ。風変わりで、早熟で、そして恐ろしい存在だ。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b141525-2LGMPFUy0VsK.jpg', NULL, NULL, NULL, NULL, 141525, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018616', 'AN1796', 'グレゴリウス・リード', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b215203-eIYqxAJyIRBT.png', NULL, NULL, NULL, NULL, 215203, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018617', 'AN1796', 'ヴェロニカ・ヴェネガス', 'ヴェロニカはリア・ヴェネガスの母親で、アメージング・ワンズが住む町でニュース記者として働いている。彼女はよくバクガンに関する出来事を報道している。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b142095-JIgEJnjpv2gu.png', NULL, NULL, NULL, NULL, 142095, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018618', 'AN1796', 'クラビッツ', 'クラビッツはAAAnimus社の潜入工作員として活動しており、ロス・ヴォルモスに潜入し、「オーサム・ワンズ」を無力化するという任務を負っている。ある訓練中の事故で市民の家の窓が割れたことをきっかけに、彼女はダン・クーソーとライトニングを監視し始める。 彼女は、コゾ家の新しい隣人であると同時に、「アンチ・バクガン活動家」として変装する。ダン君の両親が、彼女のバクガンに対する批判に対して慎重な反応を示した際、クラビッツはアーニマス社の技術を用いてドラゴをボール形態から強制的に解放し、破壊する。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b210061-liacVoGg9ZTx.jpg', NULL, NULL, NULL, NULL, 210061, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018619', 'AN1797', '〈WISE〉局長', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b272642-S4V3jLcHwzFx.jpg', NULL, NULL, '大塚明夫', NULL, 272642, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018620', 'AN1797', 'ベネディクト・アイヴァン・グッドフェラー', 'エデン・アカデミーの現校長。エデン・アカデミーの新入生向け入学式では、新入生を歓迎するスピーチを行う。一部の教職員によると、彼は保護者からの「寄付」を受け取らず、金で買収されることはないという。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b277083-neZF7lClvA4e.jpg', NULL, NULL, '多田野曜平 ', NULL, 277083, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018621', 'AN1797', '老女', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b301863-mzKXUuQavGJw.jpg', NULL, NULL, '佐々木優子', NULL, 301863, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018622', 'AN1797', '孤児院の主人', 'アーニャ・フォージャーがロイド・フォージャーに養子として引き取られた孤児院の院長である、酔っ払った中年の男性。子供たちが放置されている状況や、ロイドの過去に対する無関心ぶりからもわかるように、彼は孤児院の運営に無関心である。 彼はアーニャを「気味の悪いガキ」と見なし、ロイドが「読み書きのできる子供」を望んでいると聞くやいなや、彼女をロイドに譲ろうとした。<br><br>（出典：スパイ×ファミリー Wiki）', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b301867-Vc4auE6Amt5O.jpg', NULL, NULL, '後藤ヒロキ', NULL, 301867, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018623', 'AN1797', 'WISE機関員', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b301868-felhZ37s3zzW.jpg', NULL, NULL, '日野未歩', NULL, 301868, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018624', 'AN1797', 'ドミニク', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b270960-ZeCmPnuQp11T.png', NULL, NULL, '梶川翔平', NULL, 270960, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018625', 'AN1797', 'ジム・ヘイワード', '彼はWISEの情報提供者であり、ベルリント市役所の財務部門に勤務していた。ユーリ・ブライアが撮影した写真により、WISEのエージェントに書類を売却している現場が露見した。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b278136-LsqqszqgIXkR.jpg', NULL, NULL, '高橋伸也', NULL, 278136, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018626', 'AN1797', 'ウォルター・エバンス', 'エデン・アカデミーのマルコム・ホール、第5寮の英語教師兼寮長。穏やかで頼りになり、保守的であると評されており、生徒たちからも親しまれている。', 59, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b274085-76olW4lNxegM.png', NULL, NULL, '家中宏', NULL, 274085, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018627', 'AN1797', '仕立て屋の店員', '「モナ＆モナッカ」で店員として働いている年配の女性。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b316686-W5z27mhVDD2i.png', NULL, NULL, '竹内恵美子', NULL, 316686, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018628', 'AN1797', 'ドノバン・デズモンド', 'ドノバン・デズモンドは、国民統一党の党首であり、トワイライトの現在の標的である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b180192-nOvkTcotZyu0.png', NULL, NULL, NULL, NULL, 180192, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018629', 'AN1797', 'マードック・スワン', 'エデン・アカデミー、クライン・ホールの2号寮の寮監であり、経済学の教師でもある。彼はエデン・アカデミーの元校長の唯一の息子である。妻はエデン・アカデミーの入学面接の1ヶ月前に離婚を申し立て、その唯一の娘の単独親権を獲得した。', 47, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b274084-jbW7ZAfCK0u4.png', NULL, NULL, '浦山迅', NULL, 274084, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018630', 'AN1797', '仕立て屋の店主', 'ベルリントにある仕立て屋「モナ＆モナッカ」の店主。ロイドが未婚の女性として候補に挙げていた一人だったが、過去に政治活動で逮捕された経歴があり、また年齢がやや高かったことから、候補から外された。 フォージャー一家がアーニャ用のエデン・アカデミーの制服を購入するために彼女の店を訪れた際、彼女はエデン・アカデミーでのいじめや誘拐事件について彼らに警告した。また、彼女は店の常連であると思われることから、ヨルとも親しい関係にあるようだ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b316687-tfXjCsfbp0N7.png', NULL, NULL, '佐藤はな', NULL, 316687, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018631', 'AN1797', 'カレン', 'エドガーの娘。トワイライトはかつて、彼女の父親を調査する目的で、彼女を「ロバート」と名乗って交際していた。カレンはかなりの犯罪行為に関与していたことが知られており、ロイドが望めば、彼女を窮地に追い込むのに十分なほどである。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b274083-RoIvenciVoSd.png', NULL, NULL, '大井麻利衣', NULL, 274083, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018632', 'AN1797', 'エドガー', 'カレンの父親であり、オスタニアにある正体不明の組織のボスである。ウェスタリスとその住民に対して強い敵意を抱いている。アーニャ・フォージャーを誘拐し、トワイライトを脅迫して自分の手下にならせようとしたことで、トワイライトと対立している。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b274082-9GV1yIXv2N70.png', NULL, NULL, '斧アツシ', NULL, 274082, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018633', 'AN1798', '白銀御行', '彼は秀知院学園の2年生で、生徒会の会長を務めている。美幸は金髪に青い目をしたハンサムな青年だ。慢性的な睡眠不足と近視のせいで、その目は鋭く光っているように見える。 普段は、秀知院学園の標準的な男子黒制服を着用しており、首には「エギュイエット」と呼ばれる金色の鎖状の装飾品を身につけている。このエギュイエットは、生徒会長としての彼の権威を象徴している。白銀は勤勉な生徒であり、たとえ……', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b121101-Q8HzKP15At2d.png', '9月9日', 'O', '古川慎', 175, 121101, 'MAIN', 9642) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018634', 'AN1798', '四宮かぐや', '秀知院学園の生徒会副会長であり、裕福な四ノ宮家の令嬢である彼女は、本気を出せば何でもこなせる多才な天才だ。育ちのせいで、本能的に他人を見下し、自分の利益のために彼らを利用する方法ばかりを考えてしまう。 かぐやは生徒会に入る前は他人とほとんど関わらなかったが、その状況も変わり始めている。彼女は極めて保護された環境で育ったため、いくつかの点で未熟な部分がある。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b120649-NPaWaIpWy60E.png', '1月1日', 'AB', '古賀葵', 158, 120649, 'MAIN', 21454) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018635', 'AN1798', '藤原千花', 'シュチイン学園生徒会の書記。彼女の行動は予測できず、思考も読み取れない。ただそこにいるだけで、無意識のうちにすべてを混乱に陥れる天災のような存在。別名「被験体F」。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b121103-UGLxT8utLPnq.png', '3月3日', 'O', '小原好美', NULL, 121103, 'MAIN', 17041) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018636', 'AN1798', '石上優', '秀知院学園の生徒会会計。学園の資金管理をすべて一人で担っていることから、美雪からは非常に重宝されている。また、かぐやを恐れているが、その理由は誰にもわからない。 ユウは物静かで、めったに口を開かないが、口を開くとたいていトラブルに巻き込まれる。劣等感を抱きつつ、人生に対して悲観的な見方をしている。その態度とは対照的に、困っている人を助けようとし、必要とあれば自分のプライドも犠牲にする。彼とは違って、', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b121102-tiQFxnSEIAwm.png', '3月3日', 'O', '鈴木崚汰', NULL, 121102, 'MAIN', 15399) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018637', 'AN1798', '伊井野ミコ', '彼女は秀知院私立学園の新入生であり、生徒会の監事である。ミコは正義感が強く、善悪について他人を正そうとする。 残念ながら、そのせいでいじめの標的となってしまったが、それでも彼女は「正しいこと」という信念を貫き続けている。彼女は藤原千花を崇拝しており、たとえそれが千花の楽しみのためであっても、彼女の言うことなら何でも聞き入る。', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b125886-TQbmqAaSgBLS.png', '5月5日', 'O', '富田美憂', 147, 125886, 'MAIN', 15669) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018638', 'AN1798', '早坂愛', '早坂愛は、修智院学園の2年生であり、四宮家の付き人である。彼女は、代々四宮家に仕え、その信頼を勝ち取ってきた早坂家の出身である。  四宮かぐやと共に修智院学園に入学するよう個人的に命じられた愛は、かぐやの高校生活を支え、10年間にわたりかぐやの生活の一部となってきた。その親密な関係ゆえに、愛はかぐやの愛想の良さが演技ではない数少ない人物の一人である。  ', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b121104-7TYRl3EEsDYU.png', '4月2日', 'AB', '花守ゆみり', NULL, 121104, 'SUPPORTING', 11383) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018639', 'AN1798', '藤原萌葉', 'モエハはチカの妹で、中学生だ。彼女は中学校の生徒会副会長を務めている。彼女もミユキに憧れており、いつか告白したいと思っている。彼女は暗い考えを口に出す癖があり、それがカグヤを大いに不安にさせている。', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b134329-cRdrf5BqmIVk.png', '6月26日', 'AB', '小澤亜李', NULL, 134329, 'SUPPORTING', 107) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018640', 'AN1798', '巨瀬工リカ', '彼女は秀知院学園のマスメディア部の部員です。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126986-Pcspig2orfPq.png', NULL, NULL, '朝井彩加', NULL, 126986, 'SUPPORTING', 50) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018641', 'AN1798', '生前徒会長', '前学生会長（本名不明）は、本作の脇役の一人である。 彼は秀知院学園の高校3年生であり、第66代生徒会長を務めている。秀知院学園の3年生で、白銀御行が1年生だった当時、生徒会長を務めていた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b212389-M0QAzDPJvn7Z.jpg', NULL, NULL, '島﨑信長', NULL, 212389, 'SUPPORTING', 16) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018642', 'AN1798', '子安つばめ', 'ツバメは3年生で、チアリーディング部の副キャプテンであり、新体操選手でもある。彼女はとても人気がある。チアリーディングの活動では、ユウを励ましている。', 18, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b134326-GOZE06QSlJSb.png', '4月4日', 'A', '福原遥', NULL, 134326, 'SUPPORTING', 423) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018643', 'AN1798', 'アドルフ・ペスカローロ', '修智院学園の校長。校則に関しては厳しいが、それでも生徒たちの好感を得る術を心得ている。 彼は、石上優が謝罪文を書くという課題を完了していなかったにもかかわらず、シュチイン学園への入学を手助けした。学校内の権威ある立場にあるにもかかわらず、自身の行動となると校則や規律をコミカルなほど無視しており、生徒を叱責している最中に校内で『ポケモンGO』をプレイしているところを、何度も公然と目撃されている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b134892-HSzCDOQagDJv.jpg', NULL, NULL, '山本格', NULL, 134892, 'SUPPORTING', 42) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018644', 'AN1798', '龍珠桃', '龍珠桃は、本作の脇役の一人である。天文部の部長であり、「インポッシブル・ガールズ」の一員でもある。 ヤクザ一家の娘である彼女は、校内で帽子をかぶったり、携帯電話でゲームをしたりするなど、校則をあまり重視していない。また、短気な性格で、周囲からは威圧的な存在と見なされている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b212390-cCppoJIBYxyA.jpg', NULL, NULL, '早見沙織', NULL, 212390, 'SUPPORTING', 48) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018645', 'AN1798', '鈴木J', 'タクシー運転手であり、東京の「ラーメン皇帝」の一人。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b275597-64W2GeSpgN5P.jpg', NULL, NULL, '丸山壮史', NULL, 275597, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018646', 'AN1798', '田沼翼', '彼は秀知院高校の生徒で、いつも白銀御行に恋愛相談をしている。柏木の彼氏。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b134327-5tqYKvBaqRe2.png', '8月25日', 'A', '八代拓', NULL, 134327, 'SUPPORTING', 40) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018647', 'AN1798', '早坂奈央', '早坂奈央は愛の母親である。二人は仲が良い様子が描かれているが、愛は母親の仕事のせいで一緒に過ごす時間があまり取れないことに、しばしば不満を抱いている。彼女もまた、四ノ宮家で働いている。　娘：早坂愛　配偶者：早坂雅人', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b275116-SOfw5qLMI0FM.png', NULL, NULL, '行成とあ', NULL, 275116, 'SUPPORTING', 19) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018648', 'AN1798', '槇原こずえ', 'マッキー・センハイは、秀知院学園の高校1年生で、テーブルトップゲーム部の部長を務めている。テーブルトップゲーム部の部長として、コズエはゲームが大好きだ。 また、文化祭のクラスイベントに向けて音声を収録する際、ミコを陽気にいじめる様子からもわかるように、彼女には少々サディスティックなユーモアのセンスがある。非常に頭脳明晰で、学期末試験では常に1年生のトップ10入りを果たしている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b176219-5XhyzA12lms2.jpg', NULL, NULL, '高野麻里佳', NULL, 176219, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018649', 'AN1798', '風野', '風野は秀知学園高校の3年生で、運動会ではチアリーディング部の部長を務めていた。彼はとてもエネルギッシュで思いやりのある人物であり、チームを応援し、石上優を支えている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b176218-x0TQnRrxS2Zs.jpg', NULL, NULL, '村田太志', NULL, 176218, 'SUPPORTING', 19) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018650', 'AN1798', '小野寺麗', '彼女は本作の脇役の一人である。 彼女は秀知院のレッド・チアチームに所属しており、石上優や伊井野ミコの同級生である。普段は比較的落ち着いた性格で、物事に対して柔軟な考えを持つが、チアチームや文化祭実行委員会に関わる時は、そのエネルギーが格段に高まる。', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b157369-9o1jZCEZMyYb.png', '5月17日', 'O', '高田憂希', NULL, 157369, 'SUPPORTING', 75) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018651', 'AN1798', '白銀の父', '美由紀と白銀圭の父。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b134893-1dpk1sQ1pGRR.jpg', NULL, NULL, '子安武人', NULL, 134893, 'SUPPORTING', 738) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018652', 'AN1798', '寺島', '彼女は秀知院学園の高校3年生で、藤原千花も所属するテーブルトップゲーム部のメンバーである。寺島は、「テラコ」から「ギガコ」へと格下げされたが、これはメートル法の接頭辞をかけた駄洒落である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b176220-ybbcG8hZSgUO.png', NULL, NULL, '本泉莉奈', NULL, 176220, 'SUPPORTING', 19) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018653', 'AN1798', '大仏こばち', 'コバチは、メガネをかけたミコの同級生で、生徒会に所属している。彼女は10年以上もミコの面倒を見てきた。', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b134331-pGWnRI42SZAl.png', '6月6日', 'B', '日高里菜', NULL, 134331, 'SUPPORTING', 125) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018654', 'AN1798', '四条眞妃', 'マキはナギサの同級生であり友人だ。短い髪を短いおさげに結っている。ナギサとは仲が良いが、実はナギサと彼女の彼氏との関係を密かに妬んでいる。というのも、彼女自身も柏木の彼氏に好意を抱いていたが、以前、告白できなかったからだ。 四ノ宮一族の分家の一員として、彼女はかぐやの2親等離れた従姉にあたるため、時折かぐやを「おばさん」と呼ぶことがある。美雪とユウは、彼女の振る舞いが非常にツンデレ（外見は冷たいが、内心は親しくなりたいと思っている）であり、まるで……', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b134328-s3cEgqb5MEbh.png', '1月1日', 'AB', '市ノ瀬加那', NULL, 134328, 'SUPPORTING', 842) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018655', 'AN1798', '藤原大地', '政治家であり、豊美、千佳、そして藤原萌葉の父親。大地は礼儀正しく、仕事にも真面目だ。また、娘たちに対して過保護な面もある。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b177065-CV1Ok4h74srn.jpg', NULL, NULL, '掛川裕彦', NULL, 177065, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018656', 'AN1798', '小林マサル', '文化祭委員会の会計担当。子安つばめに片思いをしている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b276519-dha4odF2TNMN.jpg', NULL, NULL, '天崎滉平', NULL, 276519, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018657', 'AN1798', '白銀圭', '白銀圭は白銀御行の妹である。修智院中学校に通っており、同校の生徒会の会計を務めている。兄と同じように勤勉で、時には非常にプライドが高い面もある。 また、兄の正義感を受け継いでおり、ある状況下で誰かが正しい行動をとらないことを嫌う。兄と同様、たとえ手間がかかっても、困っている人を助けることが好きだ。彼女は、', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126144-4fc2sYUVFKOJ.png', '8月1日', 'B', '鈴代紗弓', NULL, 126144, 'SUPPORTING', 1863) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018658', 'AN1798', '田中哲平', '秀知院学園の広報チームのメンバー。子安つばめに片思いをしている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b276520-gvgu9gSgsEUO.jpg', NULL, NULL, '小林千晃', NULL, 276520, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018659', 'AN1798', '阿天防ゆめ', 'オカルト研究部の部長。祖父は神社の高位の神官である。カップルをからかうのが大好きで、彼女の予言のほとんどはセクハラの口実に過ぎない。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b276379-zvGm9NJSaxJY.jpg', NULL, NULL, '加隈亜衣', NULL, 276379, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018660', 'AN1798', '柏木渚', 'ナギサは、時折カグヤに恋愛の悩みを相談してくる同級生。ツバサの彼女。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b134330-2b7ad7GPw1Wl.png', '6月25日', 'B', '麻倉もも', NULL, 134330, 'SUPPORTING', 150) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018661', 'AN1798', '風祭豪', '白銀と同様、彼は秀知院に入学する前に外部の中学校に通っていた。兄の失踪に関する手がかりを探すために同校に入学した。現在は「金融界の探偵」と呼ばれる越前ハジメの助手として活動しており、数々の難事件を解決した末、ついに兄と再会を果たした。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b275098-wKIydsZwIhXw.jpg', NULL, NULL, '岡野友佑', NULL, 275098, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018662', 'AN1798', '豊崎三郎', 'かつては、白銀の成績を妨害するために卑怯な手段を用いていたが、今では正々堂々と戦っている。彼が目を開くのは、「真の実力」を発揮するときだけだ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b275620-OjIpji2v6zhb.jpg', NULL, NULL, '小野将夢', NULL, 275620, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018663', 'AN1798', '佐藤ダイキ', '秀知院学園文化祭委員会の安全担当。子安つばめに片思いをしている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b276521-RdpaCHzGDuY2.jpg', NULL, NULL, '佐藤元', NULL, 276521, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018664', 'AN1798', '紀かれん', '彼女は秀知院学園のマスメディア部の部員です。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126987-sWw4vqsdHNWe.png', NULL, NULL, '朝日奈丸佳', NULL, 126987, 'SUPPORTING', 60) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018665', 'AN1798', '藤原祖父', '藤原姉妹の祖父。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b275621-rEbljmxNuu19.jpg', NULL, NULL, '佐々健太', NULL, 275621, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018666', 'AN1798', '小田島三郎', '東京の「ラーメン皇帝」の一人。かつて、三郎は神保町の「大食いガール」と交際していたが、二人のラーメンに対する考え方が正反対だったため、いずれは互いに喉元を掴み合うことになるだろうと考え、彼女と別れた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b137169-fQzfMsNROYyF.png', NULL, NULL, '佐藤晴男', NULL, 137169, 'SUPPORTING', 38) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018667', 'AN1799', '洋裁屋', '彼女は仕立て屋の店主である。名前は一度も明かされていないため、「仕立て屋」と呼ばれている。ライトノベルとアニメの両方で初登場したが、漫画では登場しなかった。魔法店の店主が、彼女を「友人」として言及したのみである。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b135363-23RrbClhnuD8.png', NULL, NULL, '松井恵理子', NULL, 135363, 'SUPPORTING', 28) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018668', 'AN1799', 'ベロウカ', '岩谷尚文に多くの奴隷を売りつける奴隷商人。また、奴隷やモンスターの封印儀式も行っている。その風貌や商売の内容とは裏腹に、誠実な商人である。尚文の依頼を受け、ラフタリアの村の元村人たちを奴隷として探し出し、集めている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b133722-llVcCnu20CnY.png', NULL, NULL, '緒方賢一', NULL, 133722, 'SUPPORTING', 91) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018669', 'AN1799', '女王の影', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b244843-Awt8uQOH1Zwm.png', NULL, NULL, '大津愛理', NULL, 244843, 'SUPPORTING', 23) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018670', 'AN1799', '魔法屋', '彼女は、メルロマルクの城下町で魔法の書店を営む年配の女性だ。彼女自身、魔女であると語っていた。彼女は、ナオフミとその仲間たちが魔法を習得できるよう、無料で魔法の書を渡してくれた。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b135364-V5fGstfRmnYW.png', NULL, NULL, '川崎芽衣子', NULL, 135364, 'SUPPORTING', 18) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018671', 'AN1799', 'オスト＝ホウライ', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b188635-kAM9a9yzWm23.png', NULL, NULL, '花澤香菜', NULL, 188635, 'SUPPORTING', 116) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018672', 'AN1799', 'エスノバルト', '彼は人を探し出すのが天才だ。しかも、彼は人間ではない。', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b192585-JfRTVzZ4acIR.png', NULL, NULL, '河西健吾', NULL, 192585, 'SUPPORTING', 19) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018673', 'AN1799', 'ラルクベルク', 'ラルクは赤く逆立った髪をしていて、筋肉質だ。上腕には鎌のタトゥーがあり、ハンサムに見える。彼は気ままで気楽な性格で、どんな問題にも非常にのんびりとした態度で臨む。ナオフミによれば、彼は「お兄さんタイプ」のキャラクターだ。 王になったとはいえ、彼は自由を好む。グラスと同様、彼にも戦士としての気概があり、それはナオフミとの戦いの中で見られた。彼は人の顔を見るだけでその人柄を見抜く天才だ。彼には子供っぽい一面もあり、それが表れていた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b136793-HfJKb7D6gwxj.jpg', NULL, NULL, '福山潤', NULL, 136793, 'SUPPORTING', 190) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018674', 'AN1799', 'キョウ＝エスニナ', '多くのものを発明した天才。彼は人々を軽んじ、自分のためだけに行動する。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b273149-P2mxsH7y4giL.png', NULL, NULL, '木村良平', NULL, 273149, 'SUPPORTING', 15) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018675', 'AN1799', 'ロミナ', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b279421-wddySLmwDHWm.jpg', NULL, NULL, '衣川里佳', NULL, 279421, 'SUPPORTING', 16) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018676', 'AN1799', 'テリス・アレキサンドライト', 'ラルク・バーグの仲間。彼女の肌は象牙のように白く、髪は青みがかった緑色で、日光の下できらめいていた。髪は太い三つ編みにまとめられ、肩に垂れていた。両手には、大きな宝石をあしらったバングルを身につけている。  「ジュエル」として、彼女は所有する様々な宝石からエネルギーを引き出し、それを用いて強力な呪文を唱えることができる。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b136797-zuXQf5VxGQlp.jpg', NULL, NULL, '早見沙織', NULL, 136797, 'SUPPORTING', 156) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018677', 'AN1799', 'Eclair Seaetto', '彼女は岩谷尚文の村の監督を務めている。また、エクレアは尚文の奴隷たちの武術の指導も担当している。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b136788-R4A8YUHZSTAb.png', NULL, NULL, '青木瑠璃子', NULL, 136788, 'SUPPORTING', 118) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018678', 'AN1799', 'ヨモギ＝エーマール', 'キョーの幼なじみであり、旅の仲間', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b279422-V4e6GPxgK2Sf.jpg', NULL, NULL, '河瀬茉希', NULL, 279422, 'SUPPORTING', 20) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018679', 'AN1799', 'グラス', '敵のようだと思われる謎の少女。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b136796-V3uZcLtu2IWo.jpg', NULL, NULL, '潘めぐみ', NULL, 136796, 'SUPPORTING', 403) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018680', 'AN1799', 'Elrasla  Grilaroc', 'エルラスラ・グリラロック、通称「グラニー」は、自分のレベルが年齢と同じだと語る老婆である。彼女はとっくにレベルキャップに達している。「無心転生」流武術の唯一の後継者である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b136789-cloAqOx5LMJx.jpg', NULL, NULL, '伊沢磨紀', NULL, 136789, 'SUPPORTING', 47) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018681', 'AN1799', 'クリス', 'キズナとグラスが、エスノバルトの協力を得て、さまざまなモンスターのパーツを用いて作り出した式神。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b289147-SZaVCpNXXNXo.png', NULL, NULL, '龍田直樹', NULL, 289147, 'SUPPORTING', 8) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018682', 'AN1799', 'アケ', '彼はメルロマークの若き騎士の一人である。波が押し寄せた際、英雄たちを支援するため、騎士隊に同行してリュート村へ向かった。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b137277-30o0Wf6CpFtH.png', NULL, NULL, '梶原岳人', NULL, 137277, 'SUPPORTING', 31) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018683', 'AN1799', '風山絆', 'ナオフミとその仲間たちを救う「狩りの英雄」。', 18, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b188636-32h7JtBG86Di.png', NULL, NULL, '富田美憂', NULL, 188636, 'SUPPORTING', 258) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018684', 'AN1800', '小舟潮', '小舟潮は、『サマータイム・レンダリング』シリーズのメインヒロインです。 彼女はヒトガシマ島に住んでおり、海で溺れかけていた<a href="https://anilist.co/character/155707/Shiori-Kobayakawa">シオリ</a>を助けようとした際に、海難事故で命を落とした。 彼女の死が物語の起点となり、<a href="https://anilist.co/character/155703/Shinpei-Ajiro">シンペイ</a>が葬儀に参列するために実家へ戻ってくる。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155712-zMvjVpfc4WQN.png', '7月25日', 'A', '永瀬アンナ', 162, 155712, 'MAIN', 1658) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018685', 'AN1800', '網代慎平', '網代慎平は、『サマータイム・レンダ』シリーズの主人公である。 彼は、幼なじみの<a href="https://anilist.co/character/155712/Ushio-Kofune">小舟潮</a>の葬儀に出席するため、2年ぶりに故郷の人ヶ島に戻ってきた。 幼い頃に両親を亡くし、小舟家で育ったため、彼は<a href="https://anilist.co/character/155712/小舟潮</a>や<a href="https://anilist.co/character/155706/Mio-Kofune"', 18, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155703-1CNh5yTk8xWO.jpg', '5月8日', NULL, '花江夏樹', NULL, 155703, 'MAIN', 1741) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018686', 'AN1800', '小舟澪', '彼女は<a href="https://anilist.co/character/155712/Ushio-Kofune">ウシオ</a>の妹で、高校1年生だ。スポーツが得意で、水泳部に所属しており、日焼けした肌をしている。 姉の死にもかかわらず、<a href="https://anilist.co/character/155703/Shinpei-Ajiro">シンペイ</a>が帰宅した際にも明るく振る舞うなど、前向きな一面を持っている。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155706-guouOSwrSqso.jpg', '10月20日', 'A', '白砂沙帆', NULL, 155706, 'MAIN', 1992) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018687', 'AN1800', '南方ひづる', '南方ひづるは、ペンネームで執筆活動を行っている作家です', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155711-VwaqEhjhI0FL.png', NULL, NULL, '日笠陽子', 172, 155711, 'MAIN', 1701) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018688', 'AN1800', '雁切真砂人', '雁切真砂人は、ヒトガシマ島の北部にある日東神社の宮司である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155710-ARFr8ivEt521.png', NULL, NULL, '小西克幸', NULL, 155710, 'SUPPORTING', 54) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018689', 'AN1800', '小早川達夫', 'しおりの父親。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b297468-9b9dRtep4Q07.png', NULL, NULL, '細川祥央', NULL, 297468, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018690', 'AN1800', '小舟アラン', 'アランはウシオとミオの父親である。フランス出身で、ヒトガシマで「西洋料理 コフネ」というレストランを経営している。シンペイにとっては、事故で両親を亡くした後、彼を引き取ってくれた養父である。妻のコトコは、ミオの出産後に亡くなった。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b265006-sVUhiCn089Jy.png', NULL, NULL, '玄田哲章', NULL, 265006, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018691', 'AN1800', '凸村哲', 'ヒトガシマで唯一の警察署に勤務する、気さくな警察官。その人柄から、本当に警察官なのかと疑ってしまうほどだ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b265005-h34QGhRmEoGI.png', NULL, NULL, '上田燿司', NULL, 265005, 'SUPPORTING', 26) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018692', 'AN1800', '小早川しおり', 'ヒトガシマに住む若い少女。彼女の家族は「コバ・マート」を経営している。彼女はウシオに溺れ死の危機から救われたが、その事件の末、自ら命を絶ってしまった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155707-fmMAbx73fWXz.png', NULL, NULL, '釘宮理恵', NULL, 155707, 'SUPPORTING', 23) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018693', 'AN1800', '菱形朱鷺子', '菱形朱鷺子は <a href="https://anilist.co/character/155708/So-Hishigata">So</a>の妹で、高校1年生です。 彼女は頭が良くて学年でトップの成績を収めているが、体が弱く、スポーツは得意ではない。 彼女と<a href="https://anilist.co/character/155706/Mio-Kofune">ミオ</a>は幼なじみで、同じ高校の同級生である。', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155705-odov1kqX0KEr.jpg', '6月25日', 'O', '河瀬茉希', 150, 155705, 'SUPPORTING', 101) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018694', 'AN1800', 'ハイネ', 'ハイネは『サマータイム・レンダリング』シリーズの主な敵役である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155704-2cdpcDFmNmXw.jpg', NULL, NULL, '久野美咲', NULL, 155704, 'SUPPORTING', 237) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018695', 'AN1800', '菱形窓', '菱形窓は、<a href="https://anilist.co/character/155703/Shinpei-Ajiro">シンペイ</a>の幼なじみであり、親友です。 彼は、ヒトガシマで唯一の病院である菱形クリニックの長男であり、医師を目指して勉強中だ。 正義感が強く、<a href="https://anilist.co/character/155712/Ushio-Kofune">ウシオ</a>の海難事故の現場に居合わせたにもかかわらず、それを防げなかったことを悔やんでいる。 彼は<a href="https://anilist.co/ch', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155708-mOQnFZUSbcH3.jpg', '11月20日', 'O', '小野賢章', 178, 155708, 'SUPPORTING', 72) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018696', 'AN1800', '南雲竜之介', '南方ひずルの双子の兄。龍之介は中学時代に「影」に殺された。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b231699-Gox8gbSdM0Ml.jpg', NULL, NULL, '三瓶由布子', NULL, 231699, 'SUPPORTING', 153) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018697', 'AN1800', '根津銀次郎', '根津銀次郎は、ライフルを携えた年配の猟師である。彼はヒトガシマ島に住んでおり、「影」について何かを知っているようだ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155713-XYxYOuV740Yy.png', NULL, NULL, '浦山迅', NULL, 155713, 'SUPPORTING', 97) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018698', 'AN1800', '菱形千登勢', '菱形青銅の妻であり、菱形窓と菱形朱鷺子の母。原因不明の病気と診断されており、車椅子なしでは移動することができない。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b283899-XhsGmW6SW6Yh.png', NULL, NULL, '櫻庭有紗', NULL, 283899, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018699', 'AN1800', '菱形青銅', '菱形青銅は、ソとトキコの父親である。彼は、ヒトガシマで唯一の病院である菱形クリニックの院長を務めている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155709-S0ylh1rEm2ki.png', NULL, NULL, '大塚明夫', NULL, 155709, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018700', 'AN1800', '小早川朝子', '小早川朝子は、しおりの母親であり、「コバ・マート」のオーナーである。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b297467-eo7j43dEsNh6.png', NULL, NULL, '山本亜衣', NULL, 297467, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018701', 'AN1801', '式守都', '敷森は可愛いだけでなく、頭も良く、運動神経も抜群ですが、料理はそれほど得意ではありません！ いつも危険な状況に身を投じてしまう泉を、彼女はとても気にかけています。そうした状況になると、敷森は「クール」な一面を見せます。彼女は、泉をとてもクールで優しい人だと考えています。 彼女は「カラ」という名前の飼い犬を飼っている。キュートなスタイルもクールなスタイルも彼女には似合うが、どうやらキュートなスタイルを好んでいるようだ。彼女がクールな一面を見せた後、学校の女子たちの間で彼女の人気が急上昇した。', 17, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155702-S8irhsg4QTPf.png', '10月25日', NULL, '大西沙織', 162, 155702, 'MAIN', 3804) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018702', 'AN1801', '和泉幽希', 'イズミは人懐っこくて明るい少年だ。彼は生まれてこのかた、とことん不運続きだった。何かがうまくいかないことがあれば……おそらく病院送りになってしまうだろう。それでも彼は、自分が世界で一番幸運な男だと思っている。というのも、イズミには頭が良くてスポーツ万能で、いつも自分のことを気にかけてくれる彼女がいるからだ。 敷森は、彼にとっての「白馬の騎士」なのだ。', 16, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b155701-fBaTQgKGLe4O.jpg', '2月11日', NULL, '梅田修一朗', NULL, 155701, 'MAIN', 694) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018703', 'AN1801', '担任の先生', '彼女は泉のクラスの担任です。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b270435-COewv0KiZzoY.png', NULL, NULL, '依田菜津', NULL, 270435, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018704', 'AN1801', '八満結', '彼女はシキモリの友人の一人だ。働きすぎると溶けてしまう傾向がある。無表情で、のんびりとしていて、とらえどころのない性格だが、周囲の状況をしっかりと観察している。スポーツが得意ではない、お家好きの女の子だ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b184813-xtRpLYZCSlL8.jpg', '1月12日', NULL, '日高里菜', 148, 184813, 'SUPPORTING', 599) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018705', 'AN1801', '式守藤', 'シキモリの兄。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b271882-lDkot5XAiMgH.png', NULL, NULL, '下野紘', NULL, 271882, 'SUPPORTING', 206) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018706', 'AN1801', '犬束秀', '彼は、泉と敷森を取り巻く友人グループの一員だ。正直で気さく、楽しむことが好きだ。遊ぶのが好きだが、勉強にも真剣に取り組む真面目な少年でもある。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b184814-Jo9pWb4KKsNS.png', '6月25日', NULL, '岡本信彦', NULL, 184814, 'SUPPORTING', 242) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018707', 'AN1801', '式守雅', 'シキモリの母親。娘と同じように、彼女は真面目な雰囲気を漂わせている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b280957-u9E2qoMPIX06.jpg', NULL, NULL, '朴璐美', NULL, 280957, 'SUPPORTING', 21) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018708', 'AN1801', '狼谷藍', 'もともと泉の友人。バレーボール部のエース選手。背が高くスリムで、学校ではとても人気がある。彼女と泉は、図書館委員会の活動を共にしている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b185661-hU8QpclbKiwI.jpg', '11月3日', NULL, '福原綾香', NULL, 185661, 'SUPPORTING', 1295) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018709', 'AN1801', '猫崎享', '彼女は式森の友人の一人だ。明るく元気な体操選手で、人当たりが良い。式森とユウの関係を気にかけている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b184812-pvc1B1yI6IqK.png', '3月21日', NULL, '松岡美里', 166, 184812, 'SUPPORTING', 215) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018710', 'AN1801', '和泉許子', '泉ユウの母親。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b251833-50bqPmkZHiqX.jpg', NULL, NULL, '篠原恵美', NULL, 251833, 'SUPPORTING', 202) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018711', 'AN1801', '和泉明貞', '泉ユウの父。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b251831-R0s6O1484sjh.png', NULL, NULL, '楠見尚己', NULL, 251831, 'SUPPORTING', 87) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018712', 'AN1802', '只野仁人', '役職：会長　親族：只野瞳（妹）　只野仁人は、ほぼあらゆる点でごく平凡な人物である。彼の名前は「ただの男」という意味だ。彼は古見硝子と真っ先に親しくなった人物である。  只野は、ごく普通の外見で、身長も体重も平均的な、ありふれた生徒としてよく描かれている。服装のスタイルも比較的典型的なものと見なされている。彼の唯一の特徴は、黒い髪の中に一筋ある白い立ち毛である。文化祭で女装を強いられた際、彼は……', 15, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b78093-QnJ9wDICvhSR.png', '9月29日', 'O', '梶原岳人', 168, 78093, 'MAIN', 2779) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018713', 'AN1802', '古見硝子', '立場：女神　親族：古見笑介（弟）、古見秀子（母）、古見将賀（父）、古見結子（祖母）、古見晶（いとこ）、古見貞義 （叔父）　古見硝子は本作の主人公である。学校では「マドンナ」と称されているが、コミュニケーション障害と呼べるほど他人と交流することができない。  ショウコは、ファンたちから、腰まで流れるつややかな濃い紫がかった黒髪の少女として描かれている。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b121956-5FbIbcd6gAZW.png', '12月25日', 'A', '古賀葵', 168, 121956, 'MAIN', 8307) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018714', 'AN1802', '地洗井茂夫', 'キアライ・シゲオは1年1組の生徒です。キアライはソノダやシノビノと友達です。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b160221-pqsCU44cyQyz.png', '7月8日', NULL, '赤羽根健治', NULL, 160221, 'SUPPORTING', 13) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018715', 'AN1802', '忍野裳乃', '忍野モノは1年1組の生徒だ。彼は千原や園田と友達である。この3人は第6巻の第75話と第77話で特に目立っており、そこで3人はクラスの女子（＋ナジミ）のうち、誰と付き合うのが一番いいかについて話し合っている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b160222-powdZ52BxB3W.png', '10月16日', NULL, '小野賢章', NULL, 160222, 'SUPPORTING', 43) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018716', 'AN1802', '古見結子', '親族：古見将賀（息子）、Sadayoshi Komi（息子）、古見秀子（嫁）、古見良子（嫁）、 古見晶（孫娘）、古見硝子（孫娘）、古見笑介（孫）　古見結子は、ショウコ、アキラ、ショウスケの祖母である。厳格だが、家族に対しては優しい。訪ねてくると、たいていゲームで勝負を挑んでくる。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130875-FbYx3qQw7qhS.png', NULL, NULL, '滝沢久美子', NULL, 130875, 'SUPPORTING', 9) ON CONFLICT DO NOTHING;
