INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018720', 'AN1802', '古見笑介', '親族：古見結子（祖母）、古見将賀（父）、古見秀子（母）、古見貞義（叔父）、古見良子（叔母）、古見硝子（姉）、古見晶 （いとこ） 古見笑介はショウコの弟である。普段は物静かだが、会話は上手だ。笑介は短く刈り込んだ髪型で、前髪で目が隠れていることが多い。 それでも、その風貌は母や姉に似ており、ハンサムな男性と言える。  翔介は多くの特徴を', 14, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130870-9fSkcaHdQXFq.png', NULL, NULL, '榎木淳弥', NULL, 130870, 'SUPPORTING', 543) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018721', 'AN1802', '古見良子', '小見緑央は翔子の叔母です。彼女は翔子の母親と同じくらい活発なので、知らず知らずのうちに翔子を威圧してしまうことがあります。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130877-CzNhth7ommrZ.png', NULL, NULL, '篠原恵美', NULL, 130877, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
