INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018723', 'AN1802', '会沢司', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b282223-cq4T3cZ9HkGX.png', NULL, NULL, NULL, NULL, 282223, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018724', 'AN1802', '片居誠', '不良のような風貌のカタイは、実は神経質で不器用なダメ人間で、いつも言葉に詰まってしまう。彼は自分の不器用さを克服し、友達を作りたいと願っている。  多田野は、その見せかけの威圧的な態度を見抜き、すぐにカタイの親友の一人となる。彼はコミを「師匠」と見なし、彼女が常に自分を励まして、多田野とより親しくなれるよう後押ししてくれていると考えている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130868-XqHSpjZfh8Fa.jpg', NULL, NULL, '神尾晋一郎', NULL, 130868, 'SUPPORTING', 271) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018725', 'AN1802', '井中のこ子', '井中のこ子は、田舎出身であることにコンプレックスを抱いている。その後、彼女は翔子と友達になった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130879-P5pabeiKSflK.png', NULL, NULL, '潘めぐみ', NULL, 130879, 'SUPPORTING', 33) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018726', 'AN1802', '只野瞳', '親族：只野仁人（兄）　只野瞳は只野仁人の妹である。人の心を読み取る能力という点では兄に似ている。物事に消極的で内気な兄とは対照的に、彼女は活発な性格だ。  瞳は小柄な少女で、兄と同じく大きくて丸い目をしており、表情も似ている。ミディアムレングスの髪を短いツインテールに結んでいる。 普段「普通」と見なされる兄とは対照的に、瞳は', 14, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130878-E6iil2Bh2JIX.png', NULL, NULL, '内田真礼', NULL, 130878, 'SUPPORTING', 158) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018727', 'AN1802', '古見晶', '古見晶は、翔介と翔子のいとこである。当初、彼女は、言葉を発することができず、黙って晶をじっと見つめ続ける翔子の様子に怖がっていた。しかし、うどん祭りに訪れた際、翔子にくすぐられたことをきっかけに、二人は親しくなった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130876-id56lFSXz6s0.png', NULL, NULL, '本渡楓', NULL, 130876, 'SUPPORTING', 53) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018728', 'AN1802', '前田ジュクジョスキ星雄', '前田さんは、伊丹私立高校の生徒です。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b281440-OePhT8M1gHpM.png', NULL, NULL, '桑田直樹', NULL, 281440, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018729', 'AN1802', '長名なじみ', '役職：副社長　ナジミは、性別が不明な謎めいた学生です。コミュニケーション能力に長けており、会って数分もすれば誰とでもすぐに親しくなれます。幼少期、ナジミは頻繁に転校を繰り返していたため、数え切れないほどの友達を作ることができました。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b126825-J4GTiz4OHDa5.png', '4月1日', NULL, '村川梨衣', NULL, 126825, 'SUPPORTING', 2236) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018730', 'AN1802', '園田大勢', '園田泰生は1年1組の生徒だ。園田は千原と忍野と友達である。この3人は第6巻の第75話と第77話で特に目立っており、そこで3人はクラスの女子（＋ナジミ）のうち、誰と付き合うのが一番いいかについて話し合っている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b160224-ScC6rjK9l6nV.png', '9月8日', NULL, '佐藤悠雅', NULL, 160224, 'SUPPORTING', 6) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018731', 'AN1802', '成瀬詩守斗', '成瀬は、すべての人が自分のファンだと信じている人物であり、自分に話しかけてこないのは、自分が神のような存在で、自分には話しかけられないと思っているからだと考えている。彼の考えのすべては、小梅谷忠作によって解説されている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b158377-Oy9ExRvnLCyP.png', NULL, NULL, '三浦勝之', NULL, 158377, 'SUPPORTING', 77) ON CONFLICT DO NOTHING;
