INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018735', 'AN1802', '山井恋', '山井恋は、小見翔子の1-1組の同級生の一人です。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130874-Q77FIzvZcFz1.png', '11月8日', NULL, '日高里菜', NULL, 130874, 'SUPPORTING', 164) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018736', 'AN1802', '尾鶏かえで', '物事をのんびり進めるのが好きな、ちょっとおっとりした女の子で、クリスマスから元日までずっと暖炉の映像を見続けていたほどだ。', 15, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b249856-u7JjuRKqdD2O.png', '6月10日', NULL, '森山由梨佳', NULL, 249856, 'SUPPORTING', 406) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018737', 'AN1802', '米谷忠釈', '小梅谷忠作は、成瀬志津と共に出演し、自身の内面的な思いを語る。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b158374-TJTthBklZ1bt.png', NULL, NULL, '鵜澤正太郎', NULL, 158374, 'SUPPORTING', 232) ON CONFLICT DO NOTHING;
