INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018739', 'AN1802', '左藤甘美', '佐藤アマミは1年1組の生徒です。彼女の名前は「砂糖のように甘い」という意味です。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b158376-BS0qsl1IxYMp.png', NULL, NULL, '向井莉生', NULL, 158376, 'SUPPORTING', 30) ON CONFLICT DO NOTHING;
