INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018741', 'AN1802', '中々思春', '中二病のせいで、普段から曖昧な話し方をする生徒。自分は「アルソット・レス・プリマヴェーラ」であり、古見硝子は「コミリア姫」だと主張している。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b128378-M2kHIBoYvazc.png', '2月29日', NULL, '大久保瑠美', NULL, 128378, 'SUPPORTING', 501) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018742', 'AN1802', '古見秀子', '親族：古見結子（義母）、古見将賀（夫）、古見貞義（義兄）、古見硝子（娘）、古見笑介（息子）、古見晶 （姪）　古見秀子（旧姓：仁見秀子）は、翔子と翔介の母親である。娘に似ているが、性格は10代の少女そのもので、「永遠に17歳」だと主張している。 絶望すると、彼女は「永遠の18歳」へと年をとってしまう。息子や娘と同様に、秀子も美しいとされている。対照的に、彼女はとてもおしゃべりだ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130867-cdy2mWlQhiX9.png', NULL, NULL, '井上喜久子', NULL, 130867, 'SUPPORTING', 401) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018743', 'AN1802', '加藤三九二', '加藤ミクニは、コミの1年生の修学旅行グループのメンバーである。加藤は、コミの1年生の修学旅行グループの3分の1を占めている。彼女と佐々木綾美は、コミにとってこの旅行をできるだけ楽しいものにするよう約束を交わす。 加藤は遠足のスケジュールを立てるが、物事は計画通りに進まず、その結果、佐々木とちょっとした口論になってしまう。しかし、コミがすぐに仲裁に入った。その後、漫画の中で、加藤は多田野とコミに将棋の戦略を教える。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b160227-yS2Vq0ZdsHNE.jpg', NULL, NULL, '内村史子', NULL, 160227, 'SUPPORTING', 46) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018744', 'AN1802', '根津野ちか', '根津野ちかは、多田野、翔子、奈仁美より1学年上の生徒で、翔子のスポーツ面でのライバルである。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b160203-y6up72MlNbZn.png', NULL, NULL, '潘めぐみ', NULL, 160203, 'SUPPORTING', 41) ON CONFLICT DO NOTHING;
