INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018746', 'AN1802', '上理卑美子', '上理卑美子は、内気で自信のない少女として描かれている。また、ラーメン店のレビューブログを運営しており、自らを「ラーメン通」だと自負している。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130869-lkVsFPB1KXw5.jpg', '4月30日', 'B', '藤井ゆきよ', NULL, 130869, 'SUPPORTING', 193) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018747', 'AN1802', '鬼ヶ島朱子', '鬼ヶ島のあかこは、もともと山井レンの友人グループの一員だった。彼女の名前は「鬼ヶ島の赤い少女」という意味で、これは『桃太郎』の物語に由来している。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b158375-J4dfkOKW0Prf.png', '2月3日', NULL, 'ブリドカット・セーラ・恵美', NULL, 158375, 'SUPPORTING', 32) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018748', 'AN1802', '岸姫子', 'ヒメコは、山井恋が描く「人気者」というキャラクター類型の一員として登場する、謎めいた少女である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b270955-UrUy2lRONKM0.png', '9月10日', NULL, '内田真礼', NULL, 270955, 'SUPPORTING', 21) ON CONFLICT DO NOTHING;
