INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018750', 'AN1802', '矢田野まける', '矢田野まけるは、翔子と競い合うのが好きな、競争心の強い女の子だ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130871-g7EkLNAqyAbe.png', '1月3日', NULL, '前島亜美', NULL, 130871, 'SUPPORTING', 103) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018751', 'AN1802', '古見将賀', '親族：古見結子（母）、古見貞義（兄）、古見秀子（妻）、古見硝子（娘）、古見笑介（息子）、古見晶 （姪）　古見将賀は、硝子と笑介の父親である。ダンディな中年男性として描かれている。将賀はめったに口を開かず、言葉で自分の考えを表現するのに苦労することもあり、時折、簡単に動揺してしまうこともある。  若々しい妻の態度とは対照的に、正義はしばしば成熟した、冷静沈着な姿を見せる。厳格な印象を与えることもあるが、家族に対しては', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b130865-Ztgp75hdKhQ2.png', NULL, NULL, '星野充昭', NULL, 130865, 'SUPPORTING', 131) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018752', 'AN1802', '佐々木あやみ', '佐々木綾美は、1年生の修学旅行でコミのグループのメンバーだ。彼女は、コミにとって修学旅行をできるだけ楽しいものにするために、加藤ミクニと約束を交わした。また、ヨーヨーの腕前も非常に優れている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b160228-rgVuiaV6jVOF.png', '10月1日', NULL, '髙橋ミナミ', NULL, 160228, 'SUPPORTING', 53) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018753', 'AN1802', 'しょこら', '「しょこら」は、猫カフェ「ガトー」に住んでいる黒猫です。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b280386-7DtjMFqViVM7.png', NULL, NULL, '高乃麗', NULL, 280386, 'SUPPORTING', 21) ON CONFLICT DO NOTHING;
