INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018757', 'AN1804', 'ルーカス', 'レオンに紳士としての振る舞いを指導する師匠的存在の教師。背が高く、白髪で、手入れの行き届いた口ひげを生やした年配の男性である。普段は黒いスーツを着用し、右目の上にモノクルをかけている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b274405-QBNaFfGV8ghq.png', NULL, NULL, '速水奨', NULL, 274405, 'SUPPORTING', 30) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018758', 'AN1804', 'ゲラット', 'ファノス公国の伯爵級の貴族であり、修学旅行中のホルフォート学園の生徒たちを襲撃した同公国艦隊の司令官の一人。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b278299-I5AZHHYTik7e.jpg', NULL, NULL, '黒田崇矢', NULL, 278299, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
