INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018763', 'AN1804', 'ステファニー・フォウ・オフリー', 'かつてブラッド・フォウ・フィールドと婚約していた。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b278294-7B5Iaa3yzb4f.jpg', NULL, NULL, '諏訪彩花', NULL, 278294, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018764', 'AN1804', 'クラリス・ フィア・アトリー', 'クラリスはジルクと婚約していたが、ジルクが相続権を剥奪された後、彼は手紙で婚約を破棄した。彼女は何度も彼に連絡を試みたが、ジルクは直接話すことを拒んだ。 やがて彼女はジルクを憎むようになった。彼女はエアバイクレースの最中にジルクを妨害しようとしたが、レオンがレースに勝利し、ジルクを説得して彼女と会うように仕向けた。そうして彼女は、彼からきちんとした決着をつけることができたのだ。', 18, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b278302-43Vs0WPIyEZh.jpg', NULL, NULL, '鈴代紗弓', 168, 278302, 'SUPPORTING', 45) ON CONFLICT DO NOTHING;
