INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018776', 'AN1807', 'イリーナ・リッツ・ド・オールハイド', '種族：エルフ　イリーナ・リッツ・デ・オルハイドは、アード・メテオールの幼なじみである。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b152260-Vd7MdBXyBdHE.jpg', NULL, NULL, '丸岡和佳奈', NULL, 152260, 'MAIN', 211) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018777', 'AN1807', 'ジニー・フィン・ド・サルヴァン', '種族：サキュバス　幼少期からエルラドとその一味にひどくいじめられていた若いサキュバス。アルドに助けられたことをきっかけに、彼を崇拝するようになった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b152258-4ET1kkCidvCj.jpg', NULL, NULL, '羊宮妃那', NULL, 152258, 'MAIN', 185) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018778', 'AN1807', 'アード・メテオール', '種族：人間　友達を作ることが目標の、人付き合いが苦手な魔王。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b152259-QQQuLvQlIgCS.jpg', NULL, NULL, '深町寿成', NULL, 152259, 'MAIN', 196) ON CONFLICT DO NOTHING;
