INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018781', 'AN1807', 'エルザード', '魔王が姿を消した後、世界を滅ぼす寸前まで追い込んだ古代のドラゴン。彼女はジェシカに化け、ラヴィル国立魔法学院で講師を務めている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b278388-LObFvjD4pxJj.jpg', NULL, NULL, 'ゆかな', NULL, 278388, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018782', 'AN1807', 'カーラ・メテオール', 'アード・メテオールの母。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b278390-zjRtzLqMDEx7.jpg', NULL, NULL, '渡辺弥咲', NULL, 278390, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018783', 'AN1807', 'シルフィー・メルヘヴン', '種族：人間　シルフィー・メルヘヴンは、かつて「レイジング・チャンピオン」として知られていた魔王軍の兵士だった。彼女は魔王を倒すため、ファントム・フォレストで数千年にわたり修行に励んでいる。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b259582-HcWdMIAE6Zie.png', NULL, NULL, '大橋彩香', NULL, 259582, 'SUPPORTING', 72) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018784', 'AN1807', 'エラルド', 'エルラドは、バークス公爵家の神童だと言われている。かつてはジニー・フィン・デ・サルヴァンをいじめていたが、アード・メテオールとの決闘で敗れたことをきっかけに、その行為をやめた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b278391-BFZm954epJuy.jpg', NULL, NULL, '柿原徹也', NULL, 278391, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018785', 'AN1807', 'オリヴィア・ヴェル・ヴァイン', 'オリビア・ヴェル・ヴァインは、「フォー・ヘヴンリー・キングス」の一員であり、ヴァルヴァトスの妹である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b259583-0fnCA34mBzvt.jpg', NULL, NULL, '園崎未恵', NULL, 259583, 'SUPPORTING', 211) ON CONFLICT DO NOTHING;
