INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018793', 'AN1808', 'レオ・デモンハート', '能力： -「クリムゾン・コンメット」：高レベルの攻撃魔法 -「十二層のバリア（スタティス）」：あらゆる種類の魔法を無効化または封印できる高レベルの魔法。 -「ヴィス・チェンジャー」：自分の声を誰の声にも変えることができる魔法。 -「メタモルフィシス」：変装のための魔法。 -クリアランス：病気や呪いを治すことができる魔法。-ミラージュ・アイ：目にした情報をそのまま、そのまますべての情報を発動者に送ることができる魔法の技。 レオ・デモンハートは、十二の悪魔の中で最強の存在である。', 3000, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b252702-Dr2A1l40KC4E.png', NULL, NULL, '小野賢章', NULL, 252702, 'MAIN', 285) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018794', 'AN1808', 'エキドナ', 'エキドナは、「フィロソファー・ストーン」を求めて人類への新たな侵略を率いるデーモン女王である。レオ・デーモンハートに敗北し、一旦は撤退を余儀なくされたが、軍勢の再建を図っている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b252703-RAOA2ze3N8lv.png', NULL, NULL, '本渡楓', NULL, 252703, 'MAIN', 481) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018795', 'AN1808', 'エイブラッド', 'エイブラッドは地球にやってきた小悪魔で、人間に優しく、人々の幸せを大切にしています。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b277409-jNhjAdjNmAjn.jpg', NULL, NULL, '広和平松', NULL, 277409, 'SUPPORTING', 14) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018796', 'AN1808', 'シュティーナ', 'シュティーナは、天界の王たちの一人であり、魔族軍の王でもある。彼女は魔法の将軍である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b252715-pqM8mmSgKErV.png', NULL, NULL, '伊藤静', NULL, 252715, 'SUPPORTING', 205) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018797', 'AN1808', 'リリ', 'リリは、天界の王たちの一人であり、魔界軍の王の一人でもある。彼女は獣の将軍である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b252714-XMlb7jnKNDvn.png', NULL, NULL, '大和田仁美', NULL, 252714, 'SUPPORTING', 153) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018798', 'AN1808', 'メルネス', '素早い暗殺者であり、デモン軍の校長の一人である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b252713-67WMSbt5SFjV.png', NULL, NULL, '内山夕実', NULL, 252713, 'SUPPORTING', 72) ON CONFLICT DO NOTHING;
