INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018800', 'AN1808', 'エドヴァルト', 'エドヴァルトは、天界の王たちの一人であり、悪魔軍の一員である。彼はドラゴン将軍である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b252716-Z0h57Rv17kJz.png', NULL, NULL, '稲田徹', NULL, 252716, 'SUPPORTING', 42) ON CONFLICT DO NOTHING;
