INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018802', 'AN1808', 'ジェリエッタ', 'ジェリエッタは、エドヴァルトの側近であり、その娘でもある。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b265500-maRALl2x9P6Z.png', NULL, NULL, '松岡美里', NULL, 265500, 'SUPPORTING', 58) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018803', 'AN1809', '諸葛孔明', '職業：蜀漢の丞相（元）・パートタイマー（BB Longe）マネージャー　諸葛孔明は、『パリピ孔明』シリーズの男性主人公である。 彼は、三国時代（西暦220年～280年）の著名な戦略家であり、蜀漢の元丞相である。 五中平原の戦いでその生涯の終わりを迎えようとした際、彼は死の床で、平和が息づく世界に生まれ変わりたいと願った。こうして、彼は現代の日本の東京に生まれ変わった。', 54, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b256378-SQI0aqbuTlqI.png', NULL, NULL, '置鮎龍太郎', NULL, 256378, 'MAIN', 978) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018804', 'AN1809', '月見英子', '職業：歌手、アルバイト（BB Longe）　月見英子は『パリピ孔明』シリーズのヒロインである。彼女はアマチュア歌手であり、歌手になるという夢を諦めかけていた。 しかし、軍師の諸葛孔明と出会ったことをきっかけに、彼の助けを借りて才能を開花させ始める。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b256379-iQtDQh1FZUkJ.jpg', NULL, NULL, '本渡楓', 164, 256379, 'MAIN', 1323) ON CONFLICT DO NOTHING;
