INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018806', 'AN1809', '密偵', '彼はエイコの最大のファンだ。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b279503-DZKzQ7szcgBo.png', NULL, NULL, '花江夏樹', NULL, 279503, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018807', 'AN1809', '久遠七海', 'クオン・ナナミは、エikoが路上で歌っているところを見つけたボーカリスト兼ベーシストだ。ナナミとエikoはすぐに意気投合し、初対面のその場で一緒に路上で歌うことになった。そのきっかけは、公の場での演奏許可証を持っていなかったために警察に連行されそうになっていたクオンを、エikoが救ったことだった。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b274985-rc52d7HiIPlQ.jpg', NULL, NULL, '山村響', NULL, 274985, 'SUPPORTING', 166) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018808', 'AN1809', 'KABE 太人', '職業：ラッパー　KabeTaijinは、DRBラップバトル大会で3年連続優勝を果たした若手ラッパーとして知られている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b269961-aaEX3vg5q27H.jpg', NULL, NULL, '千葉翔也', NULL, 269961, 'SUPPORTING', 185) ON CONFLICT DO NOTHING;
