INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018822', 'AN1810', 'ジュニアユース生', '子供の頃、富樫と一緒に東京シティエスペリオンFCのジュニアユースチームにトライアル参加した。しかし、既存のアカデミー選手たちからの扱いのせいで、トライアル開始から数日後にチームを去った。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b287479-6AvXbLpgfn37.png', NULL, NULL, '永瀬アンナ', NULL, 287479, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
