INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018824', 'AN1810', '橘都', '橘総一郎の異卵双生児の姉。彼女もサッカーをしており、現在は東京武蔵野女子ユースに所属している。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b280422-VP9tD8XC4bil.jpg', '6月11日', NULL, '真堂圭', NULL, 280422, 'SUPPORTING', 4) ON CONFLICT DO NOTHING;
