INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018830', 'AN1810', '練習生', '子供の頃、富樫と一緒に東京シティエスペリオンFCのジュニアユースチームにトライアル参加した。しかし、既存のアカデミー選手たちからの扱いのせいで、トライアル開始から数日後にチームを辞めた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b287481-GasaMqgujPDX.png', NULL, NULL, '金田愛', NULL, 287481, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018831', 'AN1810', '青井紀子', 'アシトとシュンの母親であり、一家が経営する店の店主。現在、アシトは東京に出ているため、シュンと共に愛媛に住んでいる。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b239921-yRWVuv2b6RUO.png', NULL, NULL, '園崎未恵', NULL, 239921, 'SUPPORTING', 65) ON CONFLICT DO NOTHING;
