INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018833', 'AN1810', '食堂のおばちゃん', '東京シティ・エスペリオンFCの施設で働くカフェテリアのスタッフ。彼女は栗林とハナを引き合わせ、栗林がハナに食事プランを作成してもらうよう頼めるようにした。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b283406-GqextMGuPObj.jpg', NULL, NULL, 'くわばらあきら', NULL, 283406, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
