INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018835', 'AN1810', '青井瞬', 'シュンは『アオアシ』の脇役であり、そのスピンオフ作品『アオアシ：ブラザー・フォート』の主人公である。彼はノリコの長男であり、アシトの兄で、現在はアルバイトをしている。 シュンは最近、実家の県を本拠地とするJリーグチーム「AC愛媛」のサッカー選手としてスカウトされ、入団が内定した。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b239920-djbTwSHFEFwC.png', NULL, NULL, '中島ヨシキ', 180, 239920, 'SUPPORTING', 29) ON CONFLICT DO NOTHING;
