INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018851', 'AN1811', '相川不動', '相川不動は、漫画『恋は世界征服のあとで』の主人公である。彼は「レッド・ジェラート」であり、ヒーローチーム「ジェラート5」のリーダーである。また、メンバーの中で最強の存在でもある。', 19, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b203268-kbd6ykxfMx9Z.png', NULL, NULL, '小林裕介', NULL, 203268, 'MAIN', 179) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018852', 'AN1811', '禍原デス美', '禍原デス美は、漫画『恋は世界征服のあとで』の第二の主人公である。彼女は金髪に緑の瞳を持つ美しい女子高生で、その「月光バトルギア」は、ウサギのような耳がついた、官能的な黒の悪魔風コスチュームである。 幼い頃から、彼女の力は並外れていた。ある道場の師範を倒してしまい、意図せずその道場を閉鎖させてしまったほどで、その強さは常軌を逸している。彼女の家族は月光と何らかの過去やつながりがあり、それがきっかけで彼女も月光に関わることになった。', 19, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b203269-u1R8bMw1Z5pp.jpg', NULL, NULL, '長谷川育美', NULL, 203269, 'MAIN', 739) ON CONFLICT DO NOTHING;
