INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018873', 'AN1811', 'アルティメット・ファントム', 'ゲッコー組織の究極のプロジェクトであるミュータント。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/default.jpg', NULL, NULL, NULL, NULL, 280431, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018874', 'AN1812', '山内紗和', '時崎くるみの幼なじみ。', 16, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b279839-6sOioxDrWaUA.jpg', NULL, NULL, '大西沙織', NULL, 279839, 'SUPPORTING', 12) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018875', 'AN1812', 'マリア', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b205227-9HJS2gTWmKIO.jpg', NULL, NULL, '三森すずこ', NULL, 205227, 'SUPPORTING', 55) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018876', 'AN1813', '時任灯里', '『失われた者』。彼女は愛情深く、気さくな性格だ。メノウは、彼女自身がその能力に気づいていないにもかかわらず、その能力のせいで彼女を殺すことができない。彼女はメノウの真意を知らずに、メノウと共に旅に出る。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b161696-BrqcyDVZDevg.png', NULL, NULL, '佳原萌枝', NULL, 161696, 'MAIN', 1146) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018877', 'AN1813', 'メノウ', '「処刑人」。並外れた魔法の才能を持つ、若き処刑人の少女。彼女は自らの使命に強く献身しており、アカリの力が制御不能になる前に彼女を始末しようと試みる。標的を殺害する前に、その能力を把握するため、親しみやすい態度で近づいていく。主な武器は短剣と聖典である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b161698-EENPlUHgwebK.png', NULL, NULL, '佐伯伊織', NULL, 161698, 'MAIN', 2575) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018878', 'AN1813', 'モモ', 'メノウのもとで働く見習い巫女。メノウには深い愛情を抱いているが、宗教的な信仰心はほぼ皆無である。細工鋸を使った戦闘には神がかった腕前を持つが、経典魔法の腕前は拙い。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b161699-uvysUdARCuam.png', NULL, NULL, '金元寿子', NULL, 161699, 'MAIN', 1019) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018879', 'AN1813', 'シシリア', '港町リベルの司祭。フレアのもとで働いており、二人は知り合いのようだが、詳しい事情は不明である。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b274774-7zjAQtNwOBWE.png', NULL, NULL, '渡辺明乃', NULL, 274774, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018880', 'AN1813', 'アーシュナ・グリザリカ', '旅するプリンセス・ナイト。強さと美しさを兼ね備えたグリザリカ王国の王女。人々は彼女を「プリンセス・ナイト」と呼び、彼女は王家の紋章が入った剣を携え、いつでも戦いに備えている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b161700-q3m4O6IR4tLh.png', NULL, NULL, '市道真央', NULL, 161700, 'SUPPORTING', 1012) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018881', 'AN1813', '少女', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b274775-aWIn1VN9uvlN.png', NULL, NULL, '春野杏', NULL, 274775, 'SUPPORTING', 200) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018882', 'AN1813', 'ミツキ', '彼は「無」という能力を携えて異世界から召喚されたが、すぐに城から追い出されてしまった。彼はあてもなくさまよっていたが、やがてメノウと出会った。', 17, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b267615-jxSlsMAtVsh0.jpg', NULL, NULL, '内田雄馬', NULL, 267615, 'SUPPORTING', 5) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018883', 'AN1813', 'フレア', '熟練の司祭であり、処刑人でもある。異世界からの「ロスト・ワンズ」を最も多く殺してきた人物だ。彼女はメノウの師であり、メノウは彼女の後継者と見なされている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b267616-aGaiksiQysWL.jpg', NULL, NULL, '甲斐田裕子', NULL, 267616, 'SUPPORTING', 11) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018884', 'AN1813', 'オーウェル', '大司教。多くの人々から信頼されており、同時代において最も優れた魔法の腕前を持つ。彼女がメノウにアカリを殺す手助けを申し出たのは、中央大聖堂内に、異世界の「純粋概念」を封じ込め、さらには殺すことさえできる部屋を管理しているからである。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b267617-1uV3yicGyDLB.jpg', NULL, NULL, '久保田民絵', NULL, 267617, 'SUPPORTING', 0) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018885', 'AN1813', 'マノン・リベール', 'リベル家当主の代表。コン・リベルの唯一の娘であり、コンが病に倒れてからは、家門の代表としてその役割を担っている。常に着物を身にまとい、優雅な振る舞いをしている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b274773-447lLpBaahEx.png', NULL, NULL, '石見舞菜香', NULL, 274773, 'SUPPORTING', 184) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018886', 'AN1814', 'デリア', '彼女は大司教の寵愛を受ける者だ。マインより1歳年上である。深紅の髪と、淡い水色の瞳をしている。ディルクを弟のように扱い、つい彼を溺愛してしまう。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b126548-RdRjwllX8aah.jpg', NULL, NULL, '都丸ちよ', NULL, 126548, 'SUPPORTING', 29) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018887', 'AN1814', 'ビンデバルト', '家族構成    妻：フラウアルムの妹　<br>コント・ビンデヴァルト。アーレンスバッハ公国の大貴族であり、ビンデヴァルト州の領主である。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b157148-qipc48bHHpXc.jpg', NULL, NULL, '茶風林 ', NULL, 157148, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018888', 'AN1814', 'ベーゼヴァンス', '家族構成   <br>彼はエーレンフェストの大司教である。銀色の髪と濃い緑色の目をしている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126545-Nz2KqtePmc9w.png', NULL, NULL, '星野充昭', NULL, 126545, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018889', 'AN1814', 'エーファ', '家族構成　身分　年齢関連　<br>マインの母親。翡翠のような緑色の髪と、黄緑に近い緑色の瞳をしている。染色工場で働いている。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126527-S5MrkQGe7DEa.jpg', NULL, NULL, '折笠富美子', NULL, 126527, 'SUPPORTING', 100) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018890', 'AN1814', 'ヨゼフ', '彼はハイディの夫で、インク工房でハイディと一緒に働いている。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b157146-lQ2LOT6IZozW.jpg', NULL, NULL, '高塚智人', NULL, 157146, 'SUPPORTING', 3) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018891', 'AN1814', 'ハイディ', '家族構成　身分　年齢関連　<br>彼女はインク作りが好きで好奇心旺盛であり、ベンノからは「もう一人のマインのようだ」と評されている。赤みがかった茶色の髪に灰色の瞳をしている。外見をあまり気にしないタイプの女性だ。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b157145-ctGRq3k64zNN.jpg', NULL, NULL, '渋谷彩乃', NULL, 157145, 'SUPPORTING', 7) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018892', 'AN1814', 'ギュンター', '家族構成　身分　年齢関連　<br>マインの父親。青い髪と薄茶色の瞳をしている。兵士として働いており、現在はエーレンフェスト市のソス門で警備にあたっている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126528-OWdSG6sWkaga.jpg', NULL, NULL, '小山剛志', NULL, 126528, 'SUPPORTING', 75) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018893', 'AN1814', 'ヴォルフ', 'ステータス：　階級：平民　職業：インクギルドのギルドマスター　<br>彼はインクギルドのトップである。貴族を助けるためなら犯罪も厭わないという噂が数多く流れている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b156189-WKWqTowVlVIo.jpg', NULL, NULL, '髙階俊嗣', NULL, 156189, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018894', 'AN1815', 'ロー・クリスタス', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b221393-hWarjc5oywHv.jpg', NULL, NULL, '岡咲美保', NULL, 221393, 'MAIN', 159) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018895', 'AN1815', 'セービル', '彼はウェニアス王国の王立魔法学校の生徒であり、このシリーズの主人公である。成績がクラス最下位だったため、退学を免れるための対策として、特別訓練への参加を命じられた。 力を目覚めさせる前は、魔法が使えないことで知られていた。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b221395-fSMwMzD0NnRr.jpg', NULL, NULL, '梅田修一朗', NULL, 221395, 'MAIN', 44) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018896', 'AN1815', 'ホルト', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b221394-9xic1SWuo78k.jpg', NULL, NULL, '鈴代紗弓', NULL, 221394, 'MAIN', 112) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018897', 'AN1815', 'クドー', NULL, NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b221396-hRbEBb6Rb52F.jpg', NULL, NULL, '八代拓', NULL, 221396, 'MAIN', 21) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018898', 'AN1815', 'ホルデム', '人狼のビーストフォールン。元々は王子だったが、不倫が発覚したことをきっかけに一族から逃げ出し、ソレナのもとで暮らすことになった。平穏な生活を送るため、王家の血筋を隠すべく、ソレナに自分をビーストフォールンに変えてくれるよう頼んだ。  ソレナが処刑された後、彼はソレナの孫娘（後にアルバスであることが判明）の世話を任された。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b142957-n05NN60Kkh2r.png', NULL, NULL, '加藤将之 ', NULL, 142957, 'SUPPORTING', 18) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018899', 'AN1815', 'ライオス', 'ライオスは、スピンオフ続編『魔法使い黎明期』に登場する脇役である。     彼は思いやりのある性格だが、両親が魔術や魔法を使う者たちに対して抱く恐怖や不信感については、やや無邪気な面がある。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b279674-kAnMVvOsZAxE.jpg', NULL, NULL, '釘宮理恵', NULL, 279674, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018900', 'AN1815', 'リーリ', NULL, NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b282146-jyv7I79iFf1n.jpg', NULL, NULL, '石見舞菜香', NULL, 282146, 'SUPPORTING', 16) ON CONFLICT DO NOTHING;
