INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018903', 'AN1815', '傭兵', '彼は「ビーストフォールン」の一人であり、獣のような外見と超人的な力という呪いを背負って生まれた人々の一人である。生前、虐待を受けていたにもかかわらず、彼は善良な人間であり続け、荒々しい態度を見せつつも、実はとても心優しい人物である。 彼の名前は依然として不明である。ゼロから、「その名前を使えば自分を操ることができる」という魔女たちに、決して自分の名前を明かしてはならないと警告されていたからだ。それ以来、彼は単に「傭兵」と呼ばれている。', NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b139365-WY49zFTkGtHJ.jpg', NULL, NULL, '矢野正明', NULL, 139365, 'SUPPORTING', 117) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018904', 'AN1815', '暴虐', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b290740-4o5nrd1bjR7v.jpg', NULL, NULL, '佐藤拓也', NULL, 290740, 'SUPPORTING', 2) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018905', 'AN1815', 'ゼロ', '主人公。彼女は魔女で、外見は子供のように見えるが、おそらくははるかに年上である。彼女は「ソーサリー」と「マジック」の両方に精通し、後者を独自に発展させた。 膨大な知識を持つ一方で、宝石の価値や金銭のやり取りといった基本的な知識については全く無知である。通常なら他人を当惑させるような状況でも、彼女にとっては何の問題もない。彼女は傭兵に、彼に本来の人間としての姿を取り戻させてやると約束した上で、彼を雇った。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b126102-9ipG5YNFl8C2.jpg', NULL, NULL, '花守ゆみり', NULL, 126102, 'SUPPORTING', 527) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018906', 'AN1815', 'タワーズ ナッシング カディオ', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b290741-ienY4X2ZgWSo.jpg', NULL, NULL, '永野善一', NULL, 290741, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018907', 'AN1815', 'アルバス', '性別：   若き魔法使いであり、「ゼロの魔術師団」の一員。旅の途中でゼロと傭兵（マーセナリー）と出会う。  アルバスは、やがて「ゼロのグリモワール」を探す彼らの旅に加わることになる。', NULL, NULL, 'https://s4.anilist.co/file/anilistcdn/character/large/b142955-1ExYxRLM8nly.jpg', NULL, NULL, '大地葉', NULL, 142955, 'SUPPORTING', 37) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018908', 'AN1815', 'カディ', NULL, NULL, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b300145-jl33WIXgUr0u.png', NULL, NULL, '内村史子', NULL, 300145, 'SUPPORTING', 1) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018909', 'AN1816', '氷室菖蒲', '彼女は埼玉大学の大学院1年生の科学技術研究者である。 学業上のライバルである雪村心夜に恋をした彼女は、彼がその愛を証明するために数学的・論理的な証明を要求してきたことをきっかけに、彼と共にその証明の旅へと踏み出す。皮肉屋な一面もあるが、普段は真面目で、何よりも論理を重んじるため、何よりもその証明の旅にひたむきに取り組んでいる。', 23, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b141945-tOxjXKTlfBTE.jpg', NULL, NULL, '雨宮天', 170, 141945, 'MAIN', 1040) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018910', 'AN1816', '雪村心夜', '彼は埼玉大学の科学技術分野の大学院1年生で、アヤメと密接に協力して研究を行っている。 彼女が自分を愛していることを知った後、彼は自分が愛についても、彼女に対する自分の気持ちについても何も分かっていないことに気づき、二人が本当に愛し合っているかどうかを確かめるために、彼女と共に一連の数学的・論理的な実験に乗り出す。彼は少し恥ずかしがり屋なところはあるが、それ以外は綾音と同じように真面目で論理的であり、その性格ゆえに彼女の数学的な探求にしっかりと付き添っている。', 23, '男性', 'https://s4.anilist.co/file/anilistcdn/character/large/b141948-221k2ROoa3ZH.png', NULL, NULL, '内田雄馬', 177, 141948, 'MAIN', 351) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018911', 'AN1816', '棘田恵那', 'エナはビデオゲームをするのが大好きで、仕事に対するモチベーションや野心といったものはほとんどない。また、単に自分を楽しませたり、騒ぎを起こしたりするために、シンヤをからかったり、コウスケを茶化したりするのも好きだ。エナはかなり頭が良くて気まぐれで、時には猫のような振る舞いをすることもある。', NULL, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b141949-w1Rszg3M3wxv.png', NULL, NULL, '大森日雅', NULL, 141949, 'MAIN', 493) ON CONFLICT DO NOTHING;
INSERT INTO characters (character_id, anime_id, name, description, age, gender, image_url, birthday, blood_type, voice_actor, height, anilist_id, role, favourites) VALUES ('CH018912', 'AN1816', '奏言葉', '彼女は、読者の視点に近い「語り手」の役割を担っている。狂気じみた実験を行うアヤメとシンヤに常に振り回されながらも、彼女はその流れに身を任せ、彼らが何をしているのかを語りつつ、心の中では容赦なく彼らを批判している。  （出典：公式サイト、翻訳・編集）', 22, '女性', 'https://s4.anilist.co/file/anilistcdn/character/large/b141946-qiAiWnAwM58u.png', NULL, 'B', '原奈津子', 162, 141946, 'MAIN', 220) ON CONFLICT DO NOTHING;
